export const DEFAULT_NORMAL_PRESET = preservedAnalogStrings; 
export const DEFAULT_STRUM_PRESET = PLUCKED_PATCHES[0]; 
export const DEFAULT_LATCH_PRESET = preservedNoiseWash;
export const DEFAULT_ARP_PRESET = PLUCKED_PATCHES[0];
export const DEFAULT_PRESET = preservedAnalogStrings;

import { useSyncExternalStore } from 'react';
import { AppSettings, SynthPreset, PresetState, PlayMode, StoreState, StoredLayout } from '../types';
import { DEFAULT_SETTINGS, DEFAULT_NORMAL_PRESET, DEFAULT_LATCH_PRESET, DEFAULT_STRUM_PRESET, DEFAULT_ARP_PRESET, DEFAULT_USER_BANK, DEFAULT_COLORS } from '../constants';
import { XmlService } from './XmlService';

const SETTINGS_KEY = 'prismatonal_settings_v5'; 
const PRESET_KEY = 'prismatonal_presets_v5';
const USER_BANK_KEY = 'prismatonal_user_bank_v1';

class PrismaStore {
  private state: StoreState;
  private listeners: Set<() => void> = new Set();

  constructor() {
    // Load Settings with Robust Deep Merge
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    let loadedSettings: AppSettings = DEFAULT_SETTINGS;

    if (savedSettings) {
        try {
            const parsed = JSON.parse(savedSettings);
            loadedSettings = {
                ...DEFAULT_SETTINGS,
                ...parsed,
                layoutApproach: parsed.layoutApproach || DEFAULT_SETTINGS.layoutApproach,
                limitDepths: { ...DEFAULT_SETTINGS.limitDepths, ...(parsed.limitDepths || {}) },
                limitComplexities: { ...DEFAULT_SETTINGS.limitComplexities, ...(parsed.limitComplexities || {}) },
                colors: { ...DEFAULT_COLORS, ...(parsed.colors || {}) }, 
                limitVisuals: { ...DEFAULT_SETTINGS.limitVisuals, ...(parsed.limitVisuals || {}) },
                uiPositions: { ...DEFAULT_SETTINGS.uiPositions, ...(parsed.uiPositions || {}) },
                arpeggios: parsed.arpeggios || DEFAULT_SETTINGS.arpeggios,
                arpBpm: parsed.arpBpm || DEFAULT_SETTINGS.arpBpm,
                generationOrigins: parsed.generationOrigins || DEFAULT_SETTINGS.generationOrigins
            };
        } catch (e) {
            console.error("Failed to parse settings, reverting to defaults", e);
            loadedSettings = DEFAULT_SETTINGS;
        }
    }

    // Load Presets
    const savedPresets = localStorage.getItem(PRESET_KEY);
    let loadedPresets: PresetState;

    if (savedPresets) {
        try {
            const parsed = JSON.parse(savedPresets);
            loadedPresets = {
                normal: parsed.normal || JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
                latch: parsed.latch || JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
                strum: parsed.strum || JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
                arpeggio: parsed.arpeggio || JSON.parse(JSON.stringify(DEFAULT_ARP_PRESET))
            };
        } catch (e) {
            loadedPresets = {
                normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
                latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
                strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
                arpeggio: JSON.parse(JSON.stringify(DEFAULT_ARP_PRESET))
            };
        }
    } else {
        loadedPresets = {
            normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
            latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
            strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
            arpeggio: JSON.parse(JSON.stringify(DEFAULT_ARP_PRESET))
        };
    }

    // Load User Bank
    const savedUserBank = localStorage.getItem(USER_BANK_KEY);
    let loadedUserBank: SynthPreset[] = DEFAULT_USER_BANK;
    if (savedUserBank) {
        try {
            loadedUserBank = JSON.parse(savedUserBank);
        } catch(e) {
            loadedUserBank = DEFAULT_USER_BANK;
        }
    }

    this.state = {
        settings: loadedSettings,
        presets: loadedPresets,
        userBank: loadedUserBank,
        layout: null // Layout is not persisted to localStorage to save space/quota
    };
  }

  // --- ACTIONS ---

  updateSettings = (partial: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => {
    const current = this.state.settings;
    let next: AppSettings;

    if (typeof partial === 'function') {
      next = partial(current);
    } else {
      next = { ...current, ...partial };
    }

    if (next === current) return;

    this.state = { ...this.state, settings: next };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(next));
    this.notify();
  };

  setPreset = (mode: PlayMode, newPreset: SynthPreset) => {
    const current = this.state.presets[mode];
    if (newPreset === current) return;

    const nextPresets = { ...this.state.presets, [mode]: newPreset };
    this.state = { ...this.state, presets: nextPresets };

    localStorage.setItem(PRESET_KEY, JSON.stringify(nextPresets));
    this.notify();
  };

  saveUserPatch = (slotIndex: number, preset: SynthPreset) => {
      if (slotIndex < 0 || slotIndex >= 100) return;
      const newBank = [...this.state.userBank];
      newBank[slotIndex] = { ...preset, category: 'User' };

      this.state = { ...this.state, userBank: newBank };
      localStorage.setItem(USER_BANK_KEY, JSON.stringify(newBank));
      this.notify();
  };

  setLayout = (layout: StoredLayout | null) => {
      this.state = { ...this.state, layout };
      // Do not save to localStorage
      this.notify();
  };

  exportXML = () => {
      const xml = XmlService.exportState(this.state);
      XmlService.downloadFile(xml);
  };

  importXML = async (file: File) => {
      try {
          const partial = await XmlService.parseImport(file);
          if (partial) {
              const nextState = { ...this.state, ...partial };
              localStorage.setItem(SETTINGS_KEY, JSON.stringify(nextState.settings));
              localStorage.setItem(PRESET_KEY, JSON.stringify(nextState.presets));
              localStorage.setItem(USER_BANK_KEY, JSON.stringify(nextState.userBank));
              this.state = nextState;
              this.notify();
              return true;
          }
      } catch (e) {
          console.error(e);
          alert("Failed to import XML file.");
      }
      return false;
  };

  // --- SUBSCRIPTION ---
  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getSnapshot = () => {
    return this.state;
  };

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const store = new PrismaStore();

export function useStore() {
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot);

  return {
    settings: state.settings,
    presets: state.presets, 
    userBank: state.userBank,
    layout: state.layout,
    updateSettings: store.updateSettings,
    setPreset: store.setPreset,
    saveUserPatch: store.saveUserPatch,
    setLayout: store.setLayout,
    exportXML: store.exportXML,
    importXML: store.importXML
  };
}

import { useState, useEffect, useMemo, useRef } from 'react';
import { AppSettings, LatticeNode, LatticeLine, StoredLayout } from '../types';
import { generateLattice } from '../services/LatticeService';
import { store } from '../services/Store';

export const useLatticeData = (settings: AppSettings, globalScale: number) => {
    const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
    const [isGenerating, setIsGenerating] = useState(false);
    const [isInitialLoad, setIsInitialLoad] = useState(true);
    const [dynamicSize, setDynamicSize] = useState(2000);
    const dynamicSizeRef = useRef(2000);

    const generationDeps = useMemo(() => {
        return JSON.stringify({
            tuning: settings.tuningSystem,
            layout: settings.layoutApproach,
            depths: settings.limitDepths,
            complexities: settings.limitComplexities,
            hidden: settings.hiddenLimits,
            ratio: settings.latticeAspectRatio,
            skin: settings.activeSkin,
            origins: settings.generationOrigins
        });
    }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.activeSkin, settings.generationOrigins]);

    useEffect(() => {
        setIsGenerating(true);
        const timerId = setTimeout(() => {
            const currentLayout = store.getSnapshot().layout;

            // 1. Check if we have a valid cached layout
            if (currentLayout && currentLayout.hash === generationDeps) {
                setData({ nodes: currentLayout.nodes, lines: currentLayout.lines });
                setDynamicSize(currentLayout.dynamicSize);
                dynamicSizeRef.current = currentLayout.dynamicSize;
                setIsGenerating(false);
                return;
            }

            // 2. Otherwise Generate
            const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
            const hiddenLimits = effectiveSettings.hiddenLimits || [];
            hiddenLimits.forEach((limit: number) => {
                // @ts-ignore
                if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
            });

            // Use Origins from Settings
            const result = generateLattice(effectiveSettings, effectiveSettings.generationOrigins);

            const visibleNodeIds = new Set(result.nodes.map(n => n.id));
            const visibleLines = result.lines.filter(l => {
                if (hiddenLimits.includes(l.limit)) return false;
                if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
                return true;
            });

            let maxExtent = 0;
            for (const n of result.nodes) {
                const absX = Math.abs(n.x);
                const absY = Math.abs(n.y);
                if (absX > maxExtent) maxExtent = absX;
                if (absY > maxExtent) maxExtent = absY;
            }

            const padding = 600; 
            const spacing = settings.buttonSpacingScale * globalScale; 
            const calculatedSize = (maxExtent * spacing * 2) + padding;
            const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

            const MAX_CANVAS_SIZE = 5000;
            const clampedSize = Math.min(finalSize, MAX_CANVAS_SIZE);

            if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) {
                setDynamicSize(clampedSize);
                dynamicSizeRef.current = clampedSize;
            }

            // 3. Update State and Cache in Store
            const newData = { nodes: result.nodes, lines: visibleLines };
            setData(newData);

            store.setLayout({
                hash: generationDeps,
                nodes: newData.nodes,
                lines: newData.lines,
                dynamicSize: clampedSize
            });

            setIsGenerating(false);
        }, 10);
        return () => clearTimeout(timerId);
    }, [generationDeps]); 

    // Update dynamic size if scale changes without regeneration
    useEffect(() => {
        let maxExtent = 0;
        for (const n of data.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }
        const padding = 600; 
        const spacing = settings.buttonSpacingScale * globalScale;
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        const MAX_CANVAS_SIZE = 5000;
        const clampedSize = Math.min(finalSize, MAX_CANVAS_SIZE);

        if (Math.abs(clampedSize - dynamicSize) > 50) {
            setDynamicSize(clampedSize);
            dynamicSizeRef.current = clampedSize;
        }
    }, [settings.buttonSpacingScale, globalScale]);

    return {
        data,
        isGenerating,
        isInitialLoad,
        setIsInitialLoad,
        dynamicSize,
        dynamicSizeRef
    };
};

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { AppSettings, LatticeNode } from '../types';
import { getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';

const GRID_CELL_SIZE = 100;

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
}

export const useLatticeInteraction = (
    settings: AppSettings,
    audioEngine: AudioEngine,
    midiService: any,
    nodeMap: Map<string, LatticeNode>,
    spatialGrid: Map<string, LatticeNode[]>,
    dynamicSize: number,
    globalScale: number,
    activeChordIds: string[],
    latchMode: 0 | 1 | 2,
    uiUnlocked: boolean,
    scrollContainerRef: React.RefObject<HTMLDivElement>,
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>,
    onLimitInteraction: (limit: number) => void,
    onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void
) => {
    const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
    const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());
    const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

    // Track the full node data for generation origin expansion
    const lastTouchedNodeRef = useRef<{ coords: number[], octave: number } | null>(null);

    // Refs for closure access in event handlers
    const settingsRef = useRef(settings);
    const nodeMapRef = useRef(nodeMap);
    const spatialGridRef = useRef(spatialGrid);
    const activeCursorsRef = useRef(activeCursors);
    const persistentLatchesRef = useRef(persistentLatches);
    const dynamicSizeRef = useRef(dynamicSize);
    const globalScaleRef = useRef(globalScale);
    const lastTouchedLimitRef = useRef<number | null>(null);

    useEffect(() => { settingsRef.current = settings; }, [settings]);
    useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
    useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
    useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
    useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);
    useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
    useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);

    const audioLatchedNodes = useMemo(() => {
        const effective = new Map<string, string>(persistentLatches);
        activeChordIds.forEach(chordId => {
          const chordDef = settings.savedChords.find(c => c.id === chordId);
          if (chordDef) {
              chordDef.nodes.forEach(n => {
                  if (!effective.has(n.id)) effective.set(n.id, n.id);
              });
          }
        });
        return effective;
    }, [persistentLatches, activeChordIds, settings.savedChords]);

    const visualLatchedNodes = useMemo(() => {
        const visual = new Map(audioLatchedNodes);
        activeCursors.forEach(cursor => {
            if (cursor.hoverNodeId) {
                visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
            }
        });
        return visual;
    }, [audioLatchedNodes, activeCursors]);

    // Handle blur to clear cursors
    useEffect(() => {
        const handleBlur = () => {
            if (activeCursorsRef.current.size > 0) {
                setActiveCursors(new Map());
                cursorPositionsRef.current.clear();
                audioEngine.stopAll();
                midiService.panic();
            }
        };
        window.addEventListener('blur', handleBlur);
        return () => window.removeEventListener('blur', handleBlur);
    }, [audioEngine, midiService]);

    // Chord re-latch logic
    const prevActiveChordIds = useRef<string[]>([]);
    useEffect(() => {
        if (settings.chordsAlwaysRelatch) {
             const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
             if (newChords.length > 0) {
                 newChords.forEach(chordId => {
                     const chordDef = settings.savedChords.find(c => c.id === chordId);
                     if (chordDef) {
                         chordDef.nodes.forEach(n => {
                            const fullNode = nodeMap.get(n.id);
                            if (fullNode) {
                                audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, 'latch');
                                if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                            }
                         });
                     }
                 });
             }
        }
        prevActiveChordIds.current = activeChordIds;
    }, [activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap, settings.baseFrequency, settings.midiEnabled, settings.midiPitchBendRange, audioEngine, midiService]);

    // Audio sync for latched nodes
    const prevAudioLatchedRef = useRef<Map<string, string>>(new Map());
    useEffect(() => {
        const current = audioLatchedNodes;
        const prev = prevAudioLatchedRef.current;

        current.forEach((originId, nodeId) => {
            if (!prev.has(nodeId)) {
                 const node = nodeMap.get(nodeId); 
                 if (node) {
                     audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency, 'latch');
                     if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                 }
            }
        });
        prev.forEach((_, nodeId) => {
            if (!current.has(nodeId)) {
                audioEngine.stopVoice(`node-${nodeId}`);
                if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
            }
        });

        prevAudioLatchedRef.current = current;
    }, [audioLatchedNodes, nodeMap, settings.baseFrequency, settings.midiEnabled, settings.midiPitchBendRange, audioEngine, midiService]);

    const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
        if (!dynamicCanvasRef.current) return null;
        const rect = dynamicCanvasRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        const centerOffset = dynamicSizeRef.current / 2;
        const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
        const baseRadius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2;

        // When checking hit, we must account for the potentially larger size in alternate layouts
        const isAlternateJILayout = settingsRef.current.tuningSystem === 'ji' && settingsRef.current.layoutApproach !== 'lattice';
        const layoutSizeMult = isAlternateJILayout ? 1.5 : 1.0; 

        const col = Math.floor(x / GRID_CELL_SIZE);
        const row = Math.floor(y / GRID_CELL_SIZE);

        const cellsToCheck = [
            `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
            `${col},${row+1}`, `${col},${row-1}`,
            `${col+1},${row+1}`, `${col-1},${row-1}`,
            `${col+1},${row-1}`, `${col-1},${row+1}`
        ];

        const grid = spatialGridRef.current;

        for(const key of cellsToCheck) {
            const nodesInCell = grid.get(key);
            if (nodesInCell) {
                for (const node of nodesInCell) {
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const vis = settingsRef.current.limitVisuals?.[node.limitTop] || { size: 1 };
                    const r = baseRadius * vis.size * layoutSizeMult;

                    if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                    const dx = x - nx;
                    const dy = y - ny;
                    if (dx*dx + dy*dy < r*r) return node;
                }
            }
        }
        return null;
    };

    const handlePointerDown = (e: React.PointerEvent) => {
        if (audioEngine) audioEngine.resume();

        if (uiUnlocked || !dynamicCanvasRef.current) return;
        e.preventDefault();
        (e.target as HTMLElement).setPointerCapture(e.pointerId);

        cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

        const hitNode = getHitNode(e.clientX, e.clientY);
        const nodeId = hitNode ? hitNode.id : null;

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.set(e.pointerId, {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: nodeId, 
                hoverNodeId: nodeId,
                hasMoved: false
            });
            return next;
        });

        if (hitNode) {
          const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
          if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
          lastTouchedLimitRef.current = hitNode.maxPrime;
          lastTouchedNodeRef.current = { coords: hitNode.coords, octave: hitNode.octave };

          if (onNodeTrigger) {
              onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
          }

          const isPersistentlyLatched = persistentLatches.has(hitNode.id);
          const isAudioLatched = audioLatchedNodes.has(hitNode.id);

          if (latchMode === 1) {
               setPersistentLatches(prev => {
                   const next = new Map(prev);
                   if (isPersistentlyLatched) next.delete(hitNode.id);
                   else next.set(hitNode.id, hitNode.id);
                   return next;
               });
          }
          else {
              if (isPersistentlyLatched) {
                  setPersistentLatches(prev => {
                      const next = new Map(prev);
                      next.delete(hitNode.id);
                      return next;
                  });
              } else if (!isAudioLatched) {
                  const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                  // Mode 2 triggers 'normal' voice now, distinct from Mode 1 'latch' voice
                  const voiceType = 'normal'; 
                  audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, voiceType);
                  if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
              }
          }
        }
    };

    const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      if (!activeCursorsRef.current.has(e.pointerId)) return;

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const cursor = activeCursorsRef.current.get(e.pointerId)!;
      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      const deltaMoveX = Math.abs(e.clientX - cursor.currentX);
      const deltaMoveY = Math.abs(e.clientY - cursor.currentY);
      let hasMoved = cursor.hasMoved;
      if (deltaMoveX > 3 || deltaMoveY > 3) {
          hasMoved = true;
      }

      if (cursor.originNodeId && settings.isPitchBendEnabled && latchMode !== 1 && scrollContainerRef.current) {
           const centerOffset = dynamicSizeRef.current / 2;
           const rect = scrollContainerRef.current.getBoundingClientRect();
           const originNode = nodeMapRef.current.get(cursor.originNodeId);
           if (originNode) {
               const spacing = settings.buttonSpacingScale * globalScaleRef.current;
               const originScreenY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
               const deltaY = e.clientY - originScreenY;
               const bentRatio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * globalScaleRef.current);
               const finalRatio = originNode.ratio * bentRatio;

               const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
               audioEngine.glideVoice(voiceId, finalRatio, settings.baseFrequency);
               if (settings.midiEnabled) midiService.pitchBend(voiceId, finalRatio, settings.baseFrequency, settings.midiPitchBendRange);
           }
      }

      if (cursor.hoverNodeId !== hitId) {
          if (latchMode === 0 && cursor.hoverNodeId) {
               const isBendingOrigin = settings.isPitchBendEnabled && cursor.originNodeId && cursor.originNodeId === cursor.hoverNodeId;

               if (!isBendingOrigin) {
                   const oldVoiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
                   audioEngine.stopVoice(oldVoiceId);
                   if (settings.midiEnabled) midiService.noteOff(oldVoiceId);
               }
          }

          if (hitNode) {
               const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
               if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);

               if (latchMode === 1) {
                  const isAlreadyLatched = persistentLatchesRef.current.has(hitNode.id);
                  if (!isAlreadyLatched) {
                      setPersistentLatches(prev => {
                          if (prev.has(hitNode.id)) return prev;
                          const next = new Map(prev);
                          next.set(hitNode.id, hitNode.id);
                          return next;
                      });
                  }
               } 
               else {
                   const isAlreadyLatched = audioLatchedNodes.has(hitNode.id);
                   const isBending = settingsRef.current.isPitchBendEnabled && cursor.originNodeId;

                   if (!isAlreadyLatched && !isBending) {
                       const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
                       audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, 'strum');
                       if (settings.midiEnabled) midiService.noteOn(voiceId, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                   }
               }
          }

          setActiveCursors((prev: Map<number, ActiveCursor>) => {
              const next = new Map(prev);
              const c = next.get(e.pointerId);
              if(c) { 
                  const updatedCursor = { ...c, hoverNodeId: hitId, hasMoved };
                  next.set(e.pointerId, updatedCursor); 
              }
              return next;
          });
      }
    };

    const handlePointerUp = (e: React.PointerEvent) => {
      if (activeCursorsRef.current.has(e.pointerId)) {
          const cursor = activeCursorsRef.current.get(e.pointerId)!;

          if (cursor.originNodeId) {
              if (latchMode !== 1) {
                  const voiceId = `cursor-${e.pointerId}-${cursor.originNodeId}`;
                  audioEngine.stopVoice(voiceId);
                  if (settings.midiEnabled) midiService.noteOff(voiceId);
              }
          } 
          else if (cursor.hoverNodeId && cursor.hoverNodeId !== cursor.originNodeId && latchMode === 0) {
               const voiceId = `cursor-${e.pointerId}-${cursor.hoverNodeId}`;
               audioEngine.stopVoice(voiceId);
               if (settings.midiEnabled) midiService.noteOff(voiceId);
          }

          cursorPositionsRef.current.delete(e.pointerId);
          setActiveCursors(prev => {
              const next = new Map(prev);
              next.delete(e.pointerId);
              return next;
          });
      }
    };

    return {
        activeCursors,
        persistentLatches,
        setPersistentLatches,
        cursorPositionsRef,
        visualLatchedNodes,
        audioLatchedNodes,
        lastTouchedLimitRef,
        lastTouchedNodeRef,
        handlePointerDown,
        handlePointerMove,
        handlePointerUp
    };
};

import React, { useEffect, useRef, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, ButtonShape } from '../types';
import { getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { useLatticeData } from '../hooks/useLatticeData';
import { useLatticeVisuals } from '../hooks/useLatticeVisuals';
import { useLatticeInteraction } from '../hooks/useLatticeInteraction';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; 
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const { data, isGenerating, isInitialLoad, setIsInitialLoad, dynamicSize, dynamicSizeRef: hookDynamicSizeRef } = useLatticeData(settings, globalScale);
  const prevDynamicSizeRef = useRef(2000);

  // Derive static grid separately to pass to interaction hook before getting visual latches
  // This avoids a cyclic dependency between hooks (Visuals <-> Interaction)
  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);
  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const GRID_CELL_SIZE = 100;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const { 
      activeCursors, 
      persistentLatches, 
      setPersistentLatches, 
      cursorPositionsRef, 
      visualLatchedNodes, 
      audioLatchedNodes,
      lastTouchedLimitRef,
      lastTouchedNodeRef,
      handlePointerDown, 
      handlePointerMove, 
      handlePointerUp 
  } = useLatticeInteraction(
      settings, audioEngine, midiService, nodeMap, spatialGrid, dynamicSize, globalScale, 
      activeChordIds, latchMode, uiUnlocked, scrollContainerRef, dynamicCanvasRef, 
      onLimitInteraction, onNodeTrigger
  );

  // Now we can use useLatticeVisuals for lines, passing the real latched nodes
  const { activeLines, brightenedLines } = useLatticeVisuals(data, settings, dynamicSize, globalScale, visualLatchedNodes);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const activeCursorsRef = useRef(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const nodeMapRef = useRef(nodeMap);
  const globalScaleRef = useRef(globalScale);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const lastNode = lastTouchedNodeRef.current;
        if (lastNode) {
             updateSettings((prev: AppSettings) => {
                 // Check if near identical origin already exists? 
                 // For now, just append. This effectively "expands scope".
                 return { 
                     ...prev, 
                     generationOrigins: [...prev.generationOrigins, lastNode] 
                 };
             });
        }
    },
    decreaseDepth: () => {
        updateSettings((prev: AppSettings) => {
             if (prev.generationOrigins.length <= 1) return prev; 
             const newOrigins = [...prev.generationOrigins];
             newOrigins.pop();
             return { ...prev, generationOrigins: newOrigins };
        });
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const visualDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      skin: settings.activeSkin,
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.tuningSystem, settings.layoutApproach, settings.activeSkin, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals, settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize, globalScale]);

  // Static Canvas Render
  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
      const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      const isAlternateJILayout = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice';
      const layoutSizeMult = isAlternateJILayout ? 1.5 : 1.0; 

      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
      }

      ctx.lineCap = 'round';

      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 3 : 1) * visualSettings.size * globalScale; 
          ctx.strokeStyle = color;
          ctx.globalAlpha = (isAlternateJILayout ? 0.5 : 0.3) * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5 * globalScale, 5 * globalScale]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;

          const radius = baseRadius * limitScale * layoutSizeMult;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale * layoutSizeMult;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * globalScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1 * globalScale;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, visualDeps]); 

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Dynamic Render Loop
  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      if (!bgCanvas || !activeCanvas) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const bgCtx = bgCanvas.getContext('2d', { alpha: true });
      const activeCtx = activeCanvas.getContext('2d', { alpha: true });
      if (!bgCtx || !activeCtx) return; 

      const currentSettings = settingsRef.current;
      const currentVisualLatched = visualLatchedRef.current; 
      const currentActiveLines = activeLinesRef.current;
      const currentBrightenedLines = brightenedLinesRef.current;
      const size = hookDynamicSizeRef.current;
      const cursors = activeCursorsRef.current;
      const currentGlobalScale = globalScaleRef.current;

      const isAlternateJILayout = currentSettings.tuningSystem === 'ji' && currentSettings.layoutApproach !== 'lattice';
      const layoutSizeMult = isAlternateJILayout ? 1.5 : 1.0; 

      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
      const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

      if (bgCanvas.width !== size * dpr || bgCanvas.height !== size * dpr) {
            bgCanvas.width = size * dpr;
            bgCanvas.height = size * dpr;
            activeCanvas.width = size * dpr;
            activeCanvas.height = size * dpr;
            bgCtx.scale(dpr, dpr);
            activeCtx.scale(dpr, dpr);
      }

      let viewX = 0, viewY = 0, viewW = size, viewH = size;
      if (scrollContainerRef.current) {
          viewX = scrollContainerRef.current.scrollLeft;
          viewY = scrollContainerRef.current.scrollTop;
          viewW = scrollContainerRef.current.clientWidth;
          viewH = scrollContainerRef.current.clientHeight;
      }

      bgCtx.clearRect(viewX, viewY, viewW, viewH);
      activeCtx.clearRect(viewX, viewY, viewW, viewH);

      const centerOffset = size / 2;
      const spacing = currentSettings.buttonSpacingScale * currentGlobalScale;
      const baseRadius = (60 * currentSettings.buttonSizeScale * currentGlobalScale) / 2;
      const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
      const colorCache = currentSettings.colors;

      const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
      const rawPhase = (time * 0.001 * animationSpeed);
      const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

      bgCtx.lineCap = 'round';
      activeCtx.lineCap = 'round';

      const viewPad = 100;
      const leftBound = viewX - viewPad;
      const rightBound = viewX + viewW + viewPad;
      const topBound = viewY - viewPad;
      const bottomBound = viewY + viewH + viewPad;

      if (currentBrightenedLines.length > 0) {
            bgCtx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;
                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;
                const limitColor = colorCache[line.limit] || '#666';
                bgCtx.beginPath();
                bgCtx.moveTo(x1, y1);
                bgCtx.lineTo(x2, y2);
                bgCtx.lineWidth = 1 * currentGlobalScale;
                bgCtx.strokeStyle = limitColor;
                bgCtx.globalAlpha = 0.8; 
                bgCtx.stroke();
            }
      }

      bgCtx.setLineDash([]); 
      for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;
            const limitColor = colorCache[line.limit] || '#666';
            bgCtx.beginPath();
            bgCtx.moveTo(x1, y1);
            bgCtx.lineTo(x2, y2);
            bgCtx.lineWidth = 4 * currentGlobalScale;
            bgCtx.strokeStyle = limitColor;
            bgCtx.globalAlpha = 1.0;
            bgCtx.stroke();
            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = bgCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');
                bgCtx.strokeStyle = grad;
                bgCtx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount) * currentGlobalScale;
                bgCtx.globalAlpha = 0.3; 
                bgCtx.stroke();
                bgCtx.lineWidth = 4 * currentGlobalScale;
                bgCtx.globalAlpha = 1.0;
                bgCtx.stroke();
            }
      }

      for (const id of currentVisualLatched.keys()) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;
             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;
             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;
             const cTop = colorCache[node.limitTop] || '#666';
             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;

             const radius = baseRadius * limitScale * zoomScale * layoutSizeMult;

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius);
                activeCtx.lineTo(x + radius, y);
                activeCtx.lineTo(x, y + radius);
                activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, colorCache[node.limitBottom] || '#666');
             activeCtx.fillStyle = grad;
             activeCtx.fill();

             if (currentSettings.isColoredIlluminationEnabled) {
                 const rp = getRainbowPeriod(currentSettings.buttonSpacingScale * currentGlobalScale);
                 const phase = (y % rp) / rp;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 activeCtx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 activeCtx.lineWidth = 4 * currentGlobalScale;
             } else {
                 activeCtx.strokeStyle = 'white';
                 activeCtx.lineWidth = 3 * currentGlobalScale;
             }
             activeCtx.stroke();
             activeCtx.shadowBlur = 0; 

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale * layoutSizeMult;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = 'white';
                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale * currentGlobalScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (radius * 0.4), y);
                    activeCtx.lineTo(x + (radius * 0.4), y);
                    activeCtx.lineWidth = 1 * currentGlobalScale;
                    activeCtx.strokeStyle = 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
      }

      if (currentSettings.isPitchBendEnabled) {
            cursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset;
                         const pos = cursorPositionsRef.current.get(c.pointerId);
                         if (!pos) return;
                         let cx = 0, cy = 0;
                         if (scrollContainerRef.current) {
                             const r = scrollContainerRef.current.getBoundingClientRect();
                             cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                             cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                         }
                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = 'white';
                         activeCtx.lineWidth = 2 * currentGlobalScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                    }
                }
            });
      }

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      switch(mode) {
          case 'rainbow':
              const period = getRainbowPeriod(settings.buttonSpacingScale * globalScale);
              const stops = [];
              for(let i=0; i<=6; i++) {
                  const pct = (i/6)*100;
                  const hue = (settings.rainbowOffset + i*60);
                  stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
              }
              return { ...baseStyle, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${period}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
  SAMPLE = 'sample',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export type TuningSystem = 'ji' | 'et' | 'indian' | 'pythagorean';

export type LayoutApproach = 
  | 'lattice' | 'diamond' | 'row' | 'honeycomb' // JI specific
  | 'et_wheel' | 'et_grid' | 'et_row'           // ET specific
  | 'indian_circle' | 'indian_thaat'           // Indian specific
  | 'pyth_spiral' | 'pyth_row';                // Pythagorean specific

export type BackgroundMode = 'rainbow' | 'charcoal' | 'midnight_blue' | 'deep_maroon' | 'forest_green' | 'slate_grey' | 'image' | 'none';

export interface LimitColorMap {
  [key: number]: string;
}

export interface LimitVisualSetting {
    size: number;   // 0.1 to 2.0 (Multiplier of base size)
    opacity: number; // 0.0 to 1.0
}

export interface LimitVisualsMap {
    [key: number]: LimitVisualSetting;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface ArpeggioStep {
    nodeId: string;
    ratio: number;
    n?: number;
    d?: number;
    muted?: boolean;
    limit?: number; // For quality indication (maxPrime)
}

export type ArpDirection = 'order' | 'up' | 'down' | 'updown' | 'random';
export type ArpDivision = '1/1' | '1/2' | '1/4' | '1/8' | '1/16' | '1/32' | '1/4T' | '1/8T' | '1/16T';

export interface ArpConfig {
    direction: ArpDirection;
    division: ArpDivision;
    octaves: number; // 1 to 4
    gate: number; // 0.1 to 1.0
    swing: number; // 0 to 100
    length: number; // 1 to 32 (Pattern Length)
    probability: number; // 0.0 to 1.0 (Chance to play)
    humanize: number; // 0 to 100 (ms of jitter)
}

export interface ArpeggioDefinition {
    id: string; // "A" - "G"
    steps: ArpeggioStep[];
    isPlaying: boolean;
    config: ArpConfig;
}

export interface XYPos {
  x: number;
  y: number;
}

export interface KeyMappings {
    volumeUp: string;
    volumeDown: string;
    spatialScaleUp: string;
    spatialScaleDown: string;
    latch: string;
    panic: string;
    center: string;
    settings: string;
    synth: string;
    off: string;
    bend: string;
    addChord: string;
    increaseDepth: string;
    decreaseDepth: string;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

export interface AppSettings {
  // Global Tuning
  tuningSystem: TuningSystem;
  layoutApproach: LayoutApproach;
  activeSkin: string; // Dynamic skin ID for visual presentation

  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Origins for lattice generation (Multiple tonality centers)
  generationOrigins: GenerationOrigin[];

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Arpeggios
  arpeggios: ArpeggioDefinition[];
  arpBpm: number;

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1
  audioLatencyHint: 'interactive' | 'balanced' | 'playback'; // Buffer size control

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Brightening
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;

  // Per-Limit Visuals (Size/Opacity)
  limitVisuals: LimitVisualsMap;

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Background
  backgroundMode: BackgroundMode;
  backgroundImageData: string | null; // Base64 string for custom image
  backgroundTiling: boolean; // True = Repeat, False = No Repeat (Centered)
  backgroundYOffset: number; // Vertical offset in pixels

  // Legacy Rainbow params (still used if mode is 'rainbow')
  isRainbowModeEnabled: boolean; 
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)

  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // Behavior
  enableKeyboardShortcuts: boolean;
  keyMappings: KeyMappings;
  strumDuration: number; // seconds, 0.1 to 2.0

  // UI Relocation & Scaling
  uiUnlocked: boolean;
  uiScale: number; // 0.5 (Tiny) to 1.5 (Huge)
  uiEdgeMargin: number; // in Millimeters (1-10)
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
    arpeggioBar: XYPos;
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  sampleId?: string | null; // ID for custom sample
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;
  category?: string; // New field for categorization

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Stereo & Pan
  spread?: number; // 0 to 1 (Voice Stereo Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)

  // Reverb Unit
  reverbType?: ReverbType; // Convolution Preset (Logic base)
  reverbMix: number; // 0 to 1
  reverbSize: number; // Duration in seconds (0.1 to 10.0)
  reverbDamping: number; // 0 (Bright) to 1 (Dark)
  reverbDiffusion?: number; // 0 (Grainy) to 1 (Smooth)

  // Delay Unit
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds

  // Arp Settings
  arpConfig?: ArpConfig;
}

// Slot Types
export type PlayMode = 'normal' | 'latch' | 'strum' | 'arpeggio';

export interface PresetState {
    normal: SynthPreset;
    latch: SynthPreset;
    strum: SynthPreset;
    arpeggio: SynthPreset;
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface StoredLayout {
    hash: string; // JSON hash of the settings that generated this layout
    nodes: LatticeNode[];
    lines: LatticeLine[];
    dynamicSize: number;
}

export interface StoreState {
    settings: AppSettings;
    presets: PresetState;
    userBank: SynthPreset[]; // 20 Save Slots
    layout: StoredLayout | null;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

export const AUDIO_PROCESSOR_CODE = `
// --- DSP UTILS ---
const TWO_PI = 2 * Math.PI;

const DUMMY_OSC_CONFIG = {
    enabled: false,
    waveform: 'sine',
    sampleId: null,
    coarseDetune: 0,
    fineDetune: 0,
    gain: 0,
    attack: 0.1,
    decay: 0.1,
    sustain: 0,
    release: 0.1,
    filterCutoff: 20000,
    filterResonance: 0,
    lfoRate: 1,
    lfoDepth: 0,
    lfoTarget: 'none'
};

const DUMMY_PRESET_DATA = {
    osc1: DUMMY_OSC_CONFIG,
    osc2: DUMMY_OSC_CONFIG,
    osc3: DUMMY_OSC_CONFIG,
    modMatrix: [],
    gain: 1.0,
    spread: 0,
    stereoPanSpeed: 0,
    stereoPanDepth: 0
};

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate) {
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.42));
    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    return this.low; 
  }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.sampleCursor = 0.0; // For sample playback
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  reset() {
      this.phase = 0.0;
      this.sampleCursor = 0.0;
  }

  // sampleBuffer is a Float32Array (mono) or null
  process(freq, type, dt, sampleBuffer) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    let sample = 0.0;

    if (type === 'sample' && sampleBuffer) {
        // Resampling logic
        // Assuming base frequency of sample is Middle C (approx 261.63 Hz)
        // Playback Rate = TargetFreq / BaseFreq
        const baseFreq = 261.63;
        const rate = freq / baseFreq;

        this.sampleCursor += rate; // dt is 1/samplerate, so at rate 1.0 we advance 1 sample per sample

        const len = sampleBuffer.length;

        // Loop the sample
        while (this.sampleCursor >= len) {
            this.sampleCursor -= len;
        }

        // Linear Interpolation
        const idx = Math.floor(this.sampleCursor);
        const frac = this.sampleCursor - idx;

        const nextIdx = (idx + 1) >= len ? 0 : idx + 1;

        const s1 = sampleBuffer[idx];
        const s2 = sampleBuffer[nextIdx];

        sample = s1 + frac * (s2 - s1);

    } else {
        // Synthesized Waveforms
        this.phase += dt * freq;
        while (this.phase >= 1.0) this.phase -= 1.0;

        switch (type) {
          case 'sine':
            sample = Math.sin(TWO_PI * this.phase);
            break;
          case 'triangle':
            let t = -1.0 + (2.0 * this.phase);
            sample = 2.0 * (Math.abs(t) - 0.5);
            break;
          case 'sawtooth':
            sample = (2.0 * this.phase) - 1.0;
            sample -= this.blep.get(this.phase, dt * freq);
            break;
          case 'square':
            sample = this.phase < 0.5 ? 1.0 : -1.0;
            sample += this.blep.get(this.phase, dt * freq);
            let phase2 = (this.phase + 0.5) % 1.0;
            sample -= this.blep.get(phase2, dt * freq);
            break;
        }
    }

    return sample;
  }
}

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.type = 'normal'; // 'normal', 'latch', 'strum'
    this.panPos = 0; 

    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0; 

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  trigger(id, freq, type) {
    this.id = id;
    this.type = type || 'normal';
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0; 

    // Reset sample cursors on trigger to restart sample from beginning
    this.oscs.forEach(osc => osc.reset());

    this.envs.forEach(env => {
        env.trigger();
    });

    this.filters.forEach(f => f.reset());
    this.lfoPhases.fill(0.0);
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
  }

  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  // Pass loaded sample registry to process
  process(presetData, dt, sampleRegistry) {
    if (!this.active || !presetData) return 0.0;

    // Smooth Pitch Glide
    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
      this.baseFreq += diff * 0.005; 
    } else {
      this.baseFreq = this.targetFreq;
    }

    const oscConfigs = [
        presetData.osc1 || DUMMY_OSC_CONFIG,
        presetData.osc2 || DUMMY_OSC_CONFIG,
        presetData.osc3 || DUMMY_OSC_CONFIG
    ];
    const matrix = presetData.modMatrix || [];

    let anyEnvActive = false;

    // 1. Compute Sources
    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        const envVal = this.envs[i].process(config, dt);
        this.envVals[i] = envVal;
        if (this.envs[i].stage !== 'idle') anyEnvActive = true;

        const rate = (config.lfoRate !== undefined) ? config.lfoRate : 0.0;
        this.lfoPhases[i] += rate * dt;
        if (this.lfoPhases[i] >= 1.0) this.lfoPhases[i] -= 1.0;
        this.lfoVals[i] = Math.sin(TWO_PI * this.lfoPhases[i]);
    }

    if (!anyEnvActive) {
      this.active = false;
      return 0.0;
    }

    let modP1=0, modP2=0, modP3=0;
    let modC1=0, modC2=0, modC3=0;
    let modG1=0, modG2=0, modG3=0;
    let modR1=0, modR2=0, modR3=0;

    const mLen = matrix.length;
    for(let i=0; i<mLen; i++) {
        const row = matrix[i];
        if (!row.enabled) continue;

        let srcVal = 0;
        switch(row.source) {
            case 'lfo1': srcVal = this.lfoVals[0]; break;
            case 'lfo2': srcVal = this.lfoVals[1]; break;
            case 'lfo3': srcVal = this.lfoVals[2]; break;
            case 'env1': srcVal = this.envVals[0]; break;
            case 'env2': srcVal = this.envVals[1]; break;
            case 'env3': srcVal = this.envVals[2]; break;
        }

        const amt = srcVal * (Number.isFinite(row.amount) ? row.amount : 0);

        switch(row.target) {
            case 'osc1_pitch': modP1 += amt; break;
            case 'osc1_cutoff': modC1 += amt; break;
            case 'osc1_gain': modG1 += amt; break;
            case 'osc1_res': modR1 += amt; break;
            case 'osc2_pitch': modP2 += amt; break;
            case 'osc2_cutoff': modC2 += amt; break;
            case 'osc2_gain': modG2 += amt; break;
            case 'osc2_res': modR2 += amt; break;
            case 'osc3_pitch': modP3 += amt; break;
            case 'osc3_cutoff': modC3 += amt; break;
            case 'osc3_gain': modG3 += amt; break;
            case 'osc3_res': modR3 += amt; break;
        }
    }

    let voiceMix = 0.0;

    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        if (!config.enabled) continue;

        const envVal = this.envVals[i];
        if (envVal < 0.0001) continue;

        let lfoVal = this.lfoVals[i];
        const lfoDepth = config.lfoDepth || 0;
        let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;

        if (config.lfoTarget === 'pitch') hardPitch = lfoVal * lfoDepth;
        else if (config.lfoTarget === 'filter') hardFilter = lfoVal * lfoDepth * 20;
        else if (config.lfoTarget === 'tremolo') hardAmp = 1.0 - (lfoVal * (lfoDepth * 0.005));

        let modPitch=0, modCutoff=0, modGain=0, modRes=0;
        if (i===0) { modPitch=modP1; modCutoff=modC1; modGain=modG1; modRes=modR1; }
        else if (i===1) { modPitch=modP2; modCutoff=modC2; modGain=modG2; modRes=modR2; }
        else { modPitch=modP3; modCutoff=modC3; modGain=modG3; modRes=modR3; }

        const cents = config.coarseDetune + config.fineDetune + hardPitch + (modPitch * 1200);
        const detuneMult = Math.pow(2, cents / 1200.0);
        const oscFreq = this.baseFreq * detuneMult;

        // Retrieve Sample Buffer if ID exists and type is sample
        let buf = null;
        if (config.waveform === 'sample' && config.sampleId) {
            buf = sampleRegistry.get(config.sampleId);
        }

        let signal = this.oscs[i].process(oscFreq, config.waveform, dt, buf);

        let cutoff = config.filterCutoff + hardFilter + (modCutoff * 5000);
        let res = config.filterResonance + (modRes * 10);
        if (res < 0) res = 0;

        signal = this.filters[i].process(signal, cutoff, res, this.sampleRate);

        const gainMod = Math.max(0, 1.0 + modGain); 
        const finalGain = config.gain * envVal * hardAmp * gainMod;

        voiceMix += signal * finalGain;
    }

    return voiceMix;
  }
}

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    // 2x Oversampling setup
    const OVERSAMPLE = 2;
    this.oversample = OVERSAMPLE;
    const workingRate = sampleRate * OVERSAMPLE;

    // Sample Registry: Map<string, Float32Array>
    this.samples = new Map();

    this.voices = [];
    // Increase physical voice limit to 64 to allow for large strums/washes
    for(let i=0; i<64; i++) {
        const v = new Voice(workingRate);
        v.panPos = Math.sin(i * 123.456); 
        this.voices.push(v);
    }

    this.presets = {
        normal: DUMMY_PRESET_DATA,
        latch: DUMMY_PRESET_DATA,
        strum: DUMMY_PRESET_DATA
    };

    this.maxPolyphony = 32; // Default starting high
    this.strumDuration = 0.5;

    this.xm1L = 0; this.ym1L = 0;
    this.xm1R = 0; this.ym1R = 0;
    this.panPhase = 0;

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'update_preset') {
        const { mode, data } = msg;
        if (mode && this.presets[mode]) {
            this.presets[mode] = this.normalizePreset(data);
        }
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
         if (msg.strumDuration) this.strumDuration = msg.strumDuration;
      } else if (msg.type === 'load_sample') {
         // Store raw float32 audio data
         if (msg.id && msg.data) {
             this.samples.set(msg.id, msg.data);
         }
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq, msg.voiceType);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => v.hardStop());
      }
    };
  }

  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) },
          osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) },
          osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
          modMatrix: (data.modMatrix || []).map(row => ({
              ...row,
              amount: (Number.isFinite(row.amount) ? row.amount : 0) / 100.0
          })),
          gain: data.gain || 0.5,
          spread: data.spread || 0,
          stereoPanSpeed: data.stereoPanSpeed || 0,
          stereoPanDepth: data.stereoPanDepth || 0
      };
  }

  triggerVoice(id, freq, type) {
    // 1. If voice ID already active (re-trigger), use it
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].trigger(id, freq, type);
            return;
        }
    }

    let heldCount = 0;
    let physicallyFree = null;
    let quietestVoice = null;
    let minLevel = 1000.0;

    // Improved Stealing Candidate Logic
    let oldestReleased = null;
    let minReleaseTime = Number.MAX_VALUE;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];

        if (!v.active) {
            if (!physicallyFree) physicallyFree = v;
            continue;
        }

        const level = v.getLevel();
        if (level < minLevel) {
            minLevel = level;
            quietestVoice = v;
        }

        if (v.releaseTime === 0) {
            // Actively held
            heldCount++;
        } else {
            // Releasing - track oldest
            if (v.releaseTime < minReleaseTime) {
                minReleaseTime = v.releaseTime;
                oldestReleased = v;
            }
        }
    }

    // STEALING LOGIC
    if (heldCount >= this.maxPolyphony) {
        if (oldestReleased) {
            oldestReleased.trigger(id, freq, type);
            return;
        }
        if (quietestVoice) {
            quietestVoice.trigger(id, freq, type);
            return;
        }
    }

    if (physicallyFree) {
        physicallyFree.trigger(id, freq, type);
    } else if (oldestReleased) {
        oldestReleased.trigger(id, freq, type);
    } else if (quietestVoice) {
        quietestVoice.trigger(id, freq, type);
    }
  }

  releaseVoice(id) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
             if (this.voices[i].type !== 'strum') {
                 this.voices[i].targetFreq = freq;
             }
        }
    }
  }

  process(inputs, outputs, parameters) {
    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];
    if (!channelL) return true;
    const len = channelL.length;

    // Oversampling Constants
    const OVERSAMPLE = this.oversample;
    const workingRate = sampleRate * OVERSAMPLE;
    const dt = 1.0 / workingRate;

    const masterPreset = this.presets.normal;
    const panSpeed = (masterPreset.stereoPanSpeed !== undefined) ? masterPreset.stereoPanSpeed : 0.0;
    const panDepth = (masterPreset.stereoPanDepth !== undefined) ? masterPreset.stereoPanDepth : 0.0;

    for (let s = 0; s < len; s++) {
        let accL = 0.0;
        let accR = 0.0;

        // --- OVERSAMPLED LOOP ---
        for (let os = 0; os < OVERSAMPLE; os++) {
            let mixL = 0.0;
            let mixR = 0.0;

            this.panPhase += dt * panSpeed;
            if(this.panPhase > 1.0) this.panPhase -= 1.0;
            const autoPanVal = Math.sin(this.panPhase * TWO_PI) * panDepth;

            for (let i = 0; i < this.voices.length; i++) {
                const v = this.voices[i];
                if (v.active) {
                    if (v.type === 'strum' && v.releaseTime === 0) {
                        if (currentTime - v.startTime >= this.strumDuration) {
                            v.release();
                        }
                    }

                    const presetToUse = this.presets[v.type] || this.presets.normal;
                    // Pass the Sample Registry to the voice process method
                    const val = v.process(presetToUse, dt, this.samples);

                    if (Number.isFinite(val)) {
                        const spreadAmount = presetToUse.spread || 0;
                        let p = v.panPos * spreadAmount;
                        p += autoPanVal;
                        p = Math.max(-1.0, Math.min(1.0, p));

                        const gainL = 0.5 * (1.0 - p);
                        const gainR = 0.5 * (1.0 + p);
                        const voiceGain = presetToUse.gain || 0.5;

                        mixL += val * gainL * voiceGain;
                        mixR += val * gainR * voiceGain;
                    } else {
                        v.hardStop();
                    }
                }
            }

            // --- NON-LINEARITIES (Apply at 2x rate to reduce aliasing) ---
            mixL *= 0.05; // Headroom
            mixR *= 0.05;

            // Soft Clipper
            mixL = Math.tanh(mixL * 0.8);
            mixR = Math.tanh(mixR * 0.8);

            accL += mixL;
            accR += mixR;
        }

        // --- DOWNSAMPLE (Decimation) ---
        // Simple averaging filter
        const outL = accL / OVERSAMPLE;
        const outR = accR / OVERSAMPLE;

        // --- DC BLOCKER (Linear, safe at 1x) ---
        const yL = outL - this.xm1L + 0.995 * this.ym1L;
        this.xm1L = outL;
        this.ym1L = yL;

        const yR = outR - this.xm1R + 0.995 * this.ym1R;
        this.xm1R = outR;
        this.ym1R = yR;

        channelL[s] = yL;
        if (channelR) channelR[s] = yR;
    }

    return true;
  }
}

registerProcessor('synth-processor', PrismaProcessor);
`;

import { SynthPreset, AppSettings, ReverbType, PresetState, PlayMode } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET, REVERB_DEFAULTS } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private masterFilter: BiquadFilterNode | null = null; // New Tone Control
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private globalBrightness: number = 1.0; // 0.0 to 1.0

  // Cache active presets for FX updates
  private activePresets: PresetState;

  // Sample Registry (ID -> Name)
  private loadedSamples: Map<string, string> = new Map();

  constructor() {
    // Initialize Presets safely
    const rawPresets = store.getSnapshot().presets;
    this.activePresets = {
        normal: this.ensurePresetSafety(rawPresets.normal),
        latch: this.ensurePresetSafety(rawPresets.latch),
        strum: this.ensurePresetSafety(rawPresets.strum),
        arpeggio: this.ensurePresetSafety(rawPresets.arpeggio)
    };

    store.subscribe(() => {
        const newPresets = store.getSnapshot().presets;
        this.updatePresets(newPresets);
    });
  }

  private isMobile() {
      return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;

     const validReverbTypes: ReverbType[] = ['room', 'hall', 'cathedral', 'plate', 'shimmer'];
     let rType: ReverbType = 'hall';

     if (p.reverbType && validReverbTypes.includes(p.reverbType)) {
         rType = p.reverbType as ReverbType;
     }

     const safe: SynthPreset = {
         ...DEFAULT_PRESET,
         ...p,
         osc1: { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) },
         osc2: { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) },
         osc3: { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) },
         modMatrix: p.modMatrix || [],
         reverbType: rType
     };

     const defaults = REVERB_DEFAULTS[rType];
     if (safe.reverbSize === undefined) safe.reverbSize = defaults.size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = defaults.damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = defaults.diffusion;

     return safe;
  }

  private updatePresets(newPresets: PresetState) {
      const modes: PlayMode[] = ['normal', 'latch', 'strum', 'arpeggio'];
      let recomputeReverb = false;

      const oldMaster = this.activePresets.normal;
      const newMaster = newPresets.normal;

      if (
          oldMaster.reverbType !== newMaster.reverbType ||
          oldMaster.reverbSize !== newMaster.reverbSize ||
          oldMaster.reverbDamping !== newMaster.reverbDamping ||
          oldMaster.reverbDiffusion !== newMaster.reverbDiffusion
      ) {
          recomputeReverb = true;
      }

      this.activePresets = {
          normal: this.ensurePresetSafety(newPresets.normal),
          latch: this.ensurePresetSafety(newPresets.latch),
          strum: this.ensurePresetSafety(newPresets.strum),
          arpeggio: this.ensurePresetSafety(newPresets.arpeggio)
      };

      if (recomputeReverb && this.ctx) {
          this.updateReverbBuffer();
      }
      this.updateFX();

      if (this.workletNode) {
          modes.forEach(mode => {
              this.workletNode!.port.postMessage({ 
                  type: 'update_preset', 
                  mode: mode, 
                  data: this.activePresets[mode] 
              });
          });
      }
  }

  public async resume() {
      if (!this.ctx) {
          await this.init(); 
      }
      if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
          await this.ctx.resume();
      }
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            const settings = store.getSnapshot().settings;
            const latencyHint = settings.audioLatencyHint || 'playback';

            this.ctx = new AudioContextClass({
                latencyHint: latencyHint,
            });

            this.ctx.onstatechange = () => {
                if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
                    this.ctx.resume().catch(e => console.warn("Audio auto-resume failed:", e));
                }
            };

            try {
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const workletUrl = URL.createObjectURL(blob);

                if (this.ctx.audioWorklet && this.ctx.audioWorklet.addModule) {
                    await this.ctx.audioWorklet.addModule(workletUrl);
                } else {
                    console.error("AudioWorklet not supported");
                    return;
                }

                URL.revokeObjectURL(workletUrl);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                (['normal', 'latch', 'strum', 'arpeggio'] as PlayMode[]).forEach(mode => {
                    this.workletNode!.port.postMessage({ 
                        type: 'update_preset', 
                        mode: mode, 
                        data: this.activePresets[mode] 
                    });
                });
                this.workletNode.port.postMessage({ 
                    type: 'config', 
                    polyphony: store.getSnapshot().settings.polyphony,
                    strumDuration: store.getSnapshot().settings.strumDuration
                });

                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
            await this.ctx.resume();
        }
    })();

    return this.initPromise;
  }

  // --- SAMPLE MANAGEMENT ---

  public async loadUserSample(file: File): Promise<string> {
      await this.init();
      if (!this.ctx) throw new Error("Audio Context not ready");

      const arrayBuffer = await file.arrayBuffer();
      const audioBuffer = await this.ctx.decodeAudioData(arrayBuffer);

      // Convert to mono Float32Array for the engine
      const channelData = audioBuffer.getChannelData(0); 

      const id = `sample-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`;

      if (this.workletNode) {
          this.workletNode.port.postMessage({
              type: 'load_sample',
              id: id,
              data: channelData
          });
      }

      this.loadedSamples.set(id, file.name.substring(0, 20)); // Store name for UI
      return id;
  }

  public getAvailableSamples(): { id: string, name: string }[] {
      return Array.from(this.loadedSamples.entries()).map(([id, name]) => ({ id, name }));
  }

  // --- EXISTING METHODS ---

  private setupFX() {
    if (!this.ctx) return;

    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
        this.masterFilter?.disconnect();
    } catch(e) { /* ignore */ }

    // Master Filter (Tone Control)
    this.masterFilter = this.ctx.createBiquadFilter();
    this.masterFilter.type = 'lowpass';
    this.masterFilter.frequency.value = 20000;
    this.masterFilter.Q.value = 0.5;

    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -8.0; 
    this.limiter.ratio.value = 10.0;
    this.limiter.attack.value = 0.005;
    this.limiter.connect(this.ctx.destination);

    // Filter -> Limiter -> Out
    this.masterFilter.connect(this.limiter);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.masterFilter);

    this.reverbNode = this.ctx.createConvolver();
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.masterFilter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.masterFilter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
    this.setMasterVolume(this.currentMasterVol);
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;

      const master = this.activePresets.normal;
      const type = master.reverbType || 'hall';

      const duration = master.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = master.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = master.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': decay = 3.0; density = 0.8; break;
          case 'hall': decay = 2.0; density = 0.6; preDelay = 0.02; break;
          case 'cathedral': decay = 1.5; density = 0.4; preDelay = 0.04; break;
          case 'plate': decay = 4.0; density = 1.0; break;
          case 'shimmer': decay = 0.8; density = 0.2; break;
          default: decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      const master = this.activePresets.normal;

      const scaledReverbMix = Math.min(1.0, master.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, master.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, master.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(master.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = master.compressorThreshold ?? -20.0;
          const ratio = master.compressorRatio ?? 12;
          const release = master.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.masterFilter) {
          // Logarithmic mapping for brightness: 0..1 -> 100Hz .. 20000Hz
          const minFreq = 100;
          const maxFreq = 20000;
          const freq = minFreq * Math.pow(maxFreq/minFreq, this.globalBrightness);
          this.masterFilter.frequency.setTargetAtTime(freq, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          this.dryGain.gain.setTargetAtTime(dryLevel * this.currentMasterVol, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    const startSample = Math.floor(preDelay * sampleRate);
    let lpL = 0, lpR = 0;
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);
        const progress = (i - startSample) / (length - startSample);
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        const env = Math.pow(1 - progress, decayCurve);
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      if (this.workletNode) {
          this.workletNode.port.postMessage({ type: 'config', polyphony: count });
      }
  }

  public setStrumDuration(duration: number) {
      if (this.workletNode) {
          this.workletNode.port.postMessage({ type: 'config', strumDuration: duration });
      }
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public setGlobalBrightness(val: number) {
      this.globalBrightness = val;
      this.updateFX();
  }

  public async startVoice(id: string, ratio: number, baseFrequency: number, type: PlayMode = 'normal') {
    if (this.ctx && (this.ctx.state === 'suspended' || (this.ctx.state as string) === 'interrupted')) {
        this.ctx.resume();
    }
    await this.init();
    if (!this.workletNode) return;

    const freq = baseFrequency * ratio;
    this.workletNode.port.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq,
        voiceType: type
    });
  }

  public stopVoice(id: string) {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number) {
    if (!this.workletNode) return;
    const freq = baseFrequency * newRatio;
    this.workletNode.port.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ type: 'stop_all' });
    this.setupFX();
  }
}

export const audioEngine = new AudioEngine();
export default AudioEngine;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { SynthPreset, WaveformType, OscillatorConfig, ModSource, ModTarget, ReverbType, PresetState, PlayMode, ArpDirection, ArpDivision } from '../types';
import { PRESETS, REVERB_DEFAULTS } from '../constants';
import { useStore } from '../services/Store';
import { audioEngine } from '../services/AudioEngine';

interface Props {
  presets: PresetState;
  onChange: (mode: PlayMode, p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

// Envelope Graph Component (Same as before)
const EnvelopeGraph = ({ attack, decay, sustain, release }: { attack: number, decay: number, sustain: number, release: number }) => {
    const width = 200;
    const height = 60;
    const pad = 2;
    const scaleTime = (t: number) => Math.min(width / 3, Math.pow(t, 0.5) * 30);
    const xA = pad + scaleTime(attack);
    const xD = xA + scaleTime(decay);
    const xS = xD + 30; 
    const xR = xS + scaleTime(release);
    const yBase = height - pad;
    const yPeak = pad;
    const ySus = yBase - (sustain * (height - 2 * pad));
    const path = `M ${pad} ${yBase} L ${xA} ${yPeak} L ${xD} ${ySus} L ${xS} ${ySus} L ${xR} ${yBase}`;

    return (
        <div className="w-full bg-slate-900 rounded border border-slate-700 h-[60px] overflow-hidden relative">
            <svg width="100%" height="100%" viewBox={`0 0 ${Math.max(width, xR + 10)} ${height}`} className="absolute top-0 left-0">
                <path d={path} fill="none" stroke="#6366f1" strokeWidth="2" />
                <path d={`${path} L ${xR} ${height} L ${pad} ${height} Z`} fill="rgba(99, 102, 241, 0.2)" stroke="none" />
            </svg>
            <div className="absolute bottom-1 right-2 text-[8px] text-slate-500 pointer-events-none">ADSR VISUALIZER</div>
        </div>
    );
};

const MATRIX_SOURCES: { id: ModSource, label: string }[] = [
    { id: 'lfo1', label: 'LFO 1' },
    { id: 'lfo2', label: 'LFO 2' },
    { id: 'lfo3', label: 'LFO 3' },
    { id: 'env1', label: 'ENV 1' },
    { id: 'env2', label: 'ENV 2' },
    { id: 'env3', label: 'ENV 3' },
];

const MATRIX_TARGETS: { id: ModTarget, label: string }[] = [
    { id: 'osc1_pitch', label: 'Pitch 1' },
    { id: 'osc1_cutoff', label: 'Cut 1' },
    { id: 'osc1_gain', label: 'Gain 1' },
    { id: 'osc1_res', label: 'Res 1' },
    { id: 'osc2_pitch', label: 'Pitch 2' },
    { id: 'osc2_cutoff', label: 'Cut 2' },
    { id: 'osc2_gain', label: 'Gain 2' },
    { id: 'osc2_res', label: 'Res 2' },
    { id: 'osc3_pitch', label: 'Pitch 3' },
    { id: 'osc3_cutoff', label: 'Cut 3' },
    { id: 'osc3_gain', label: 'Gain 3' },
    { id: 'osc3_res', label: 'Res 3' },
];

const SynthControls: React.FC<Props> = ({ presets, onChange, isOpen, onClose }) => {
  const [activeVoiceMode, setActiveVoiceMode] = useState<PlayMode>('normal');
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx' | 'arp'>('osc1');
  const { userBank, saveUserPatch } = useStore();

  const [isSaveMode, setIsSaveMode] = useState(false);
  const [saveSlotIndex, setSaveSlotIndex] = useState(0);
  const [saveName, setSaveName] = useState("");
  const [draggingCell, setDraggingCell] = useState<{ source: ModSource, target: ModTarget, startY: number, startVal: number } | null>(null);

  // Sample State
  const [availableSamples, setAvailableSamples] = useState<{id: string, name: string}[]>([]);
  const sampleInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
      if (isOpen) {
          setAvailableSamples(audioEngine.getAvailableSamples());
      }
  }, [isOpen]);

  const categorizedPresets = useMemo(() => {
      const groups: Record<string, SynthPreset[]> = {};
      PRESETS.forEach(p => {
          const cat = p.category || 'Uncategorized';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(p);
      });
      return groups;
  }, []);

  if (!isOpen) return null;

  const currentPreset = presets[activeVoiceMode];

  const updateGlobal = (key: keyof SynthPreset, val: any) => {
    onChange(activeVoiceMode, { ...currentPreset, [key]: val });
  };

  const updateArp = (key: keyof import('../types').ArpConfig, val: any) => {
      const currentArp = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };
      const newArp = { ...currentArp, [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, arpConfig: newArp });
  };

  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...currentPreset[oscKey], [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, [oscKey]: newOsc });
  };

  const loadPreset = (p: SynthPreset) => {
      const cloned = JSON.parse(JSON.stringify(p));
      onChange(activeVoiceMode, cloned);
  };

  const handleResetToDefault = () => {
      const factory = PRESETS.find(p => p.name === currentPreset.name);
      if (factory) {
          loadPreset(factory);
      } else {
          const userP = userBank.find(p => p.name === currentPreset.name);
          if (userP) loadPreset(userP);
      }
  };

  const handleSaveToSlot = () => {
      if (saveName.trim() === "") return;
      const presetToSave = { ...currentPreset, name: saveName, id: `user-${Date.now()}` };
      saveUserPatch(saveSlotIndex, presetToSave);
      setIsSaveMode(false);
  };

  const handleReverbTypeChange = (type: ReverbType) => {
      const defaults = REVERB_DEFAULTS[type];
      onChange(activeVoiceMode, {
          ...currentPreset,
          reverbType: type,
          reverbSize: defaults.size,
          reverbDamping: defaults.damping,
          reverbDiffusion: defaults.diffusion
      });
  };

  const getMatrixValue = (source: ModSource, target: ModTarget) => {
      const row = currentPreset.modMatrix?.find(r => r.source === source && r.target === target);
      return row ? row.amount : 0;
  };

  const setMatrixValue = (source: ModSource, target: ModTarget, amount: number) => {
      let newMatrix = [...(currentPreset.modMatrix || [])];
      const existingIdx = newMatrix.findIndex(r => r.source === source && r.target === target);
      if (amount === 0) {
          if (existingIdx !== -1) newMatrix.splice(existingIdx, 1);
      } else {
          if (existingIdx !== -1) {
              newMatrix[existingIdx] = { ...newMatrix[existingIdx], amount, enabled: true };
          } else {
              newMatrix.push({ id: `${source}-${target}-${Date.now()}`, enabled: true, source, target, amount });
          }
      }
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: newMatrix });
  };

  const handleMatrixDragStart = (e: React.PointerEvent, source: ModSource, target: ModTarget) => {
      e.currentTarget.setPointerCapture(e.pointerId);
      setDraggingCell({ source, target, startY: e.clientY, startVal: getMatrixValue(source, target) });
  };

  const handleMatrixDragMove = (e: React.PointerEvent) => {
      if (!draggingCell) return;
      const deltaY = draggingCell.startY - e.clientY; 
      let newVal = draggingCell.startVal + (deltaY * 1);
      newVal = Math.max(-100, Math.min(100, Math.round(newVal)));
      if (newVal !== getMatrixValue(draggingCell.source, draggingCell.target)) {
          setMatrixValue(draggingCell.source, draggingCell.target, newVal);
      }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, oscKey: 'osc1' | 'osc2' | 'osc3') => {
      const file = e.target.files?.[0];
      if (file) {
          audioEngine.loadUserSample(file).then(id => {
              setAvailableSamples(audioEngine.getAvailableSamples());
              updateOsc(oscKey, 'sampleId', id);
          }).catch(err => console.error("Sample load failed", err));
      }
      if (sampleInputRef.current) sampleInputRef.current.value = '';
  };

  const renderOscillatorTab = (oscKey: 'osc1' | 'osc2' | 'osc3', label: string) => {
      const config = currentPreset[oscKey];
      const canToggle = oscKey !== 'osc1'; 
      return (
          <div className="space-y-6 animate-in fade-in duration-300">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-sm font-bold text-slate-300 uppercase">{label} Settings</h3>
                  {canToggle && (
                      <label className="flex items-center gap-2 cursor-pointer bg-slate-900/50 px-3 py-1 rounded border border-slate-600">
                          <input type="checkbox" checked={config.enabled} onChange={(e) => updateOsc(oscKey, 'enabled', e.target.checked)} className="rounded border-slate-600 text-indigo-500 focus:ring-indigo-500" />
                          <span className={`text-xs font-bold ${config.enabled ? 'text-white' : 'text-slate-500'}`}>{config.enabled ? 'ENABLED' : 'DISABLED'}</span>
                      </label>
                  )}
              </div>
              <div className={`space-y-6 ${!config.enabled ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <div className="grid grid-cols-5 gap-1 mb-4">
                        {Object.values(WaveformType).map(w => (
                            <button key={w} onClick={() => updateOsc(oscKey, 'waveform', w)} className={`px-1 py-1 text-[9px] font-bold uppercase rounded border ${config.waveform === w ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>{w}</button>
                        ))}
                    </div>

                    {config.waveform === 'sample' && (
                        <div className="mb-4 space-y-2 bg-indigo-900/20 p-2 rounded border border-indigo-500/30">
                            <label className="text-[10px] font-bold text-indigo-300 uppercase block">Sample Selection</label>
                            <select 
                                value={config.sampleId || ''} 
                                onChange={(e) => updateOsc(oscKey, 'sampleId', e.target.value)}
                                className="w-full bg-slate-800 text-xs rounded p-1 border border-slate-600 mb-2"
                            >
                                <option value="">Select a Sample...</option>
                                {availableSamples.map(s => (
                                    <option key={s.id} value={s.id}>{s.name}</option>
                                ))}
                            </select>
                            <input 
                                type="file" 
                                ref={sampleInputRef} 
                                className="hidden" 
                                accept="audio/*" 
                                onChange={(e) => handleFileUpload(e, oscKey)} 
                            />
                            <button 
                                onClick={() => sampleInputRef.current?.click()} 
                                className="w-full py-1.5 bg-slate-700 hover:bg-slate-600 text-xs font-bold rounded border border-slate-600 transition"
                            >
                                Upload Audio File
                            </button>
                            <p className="text-[9px] text-slate-500 italic">Samples are re-pitched automatically (Root: Middle C)</p>
                        </div>
                    )}

                    <div className="space-y-3">
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Mix</span> <span>{(config.gain * 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.01" value={config.gain} onChange={(e) => updateOsc(oscKey, 'gain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Coarse</span> <span>{config.coarseDetune} cents</span></label>
                            <input type="range" min="-1200" max="1200" step="10" value={config.coarseDetune} onChange={(e) => updateOsc(oscKey, 'coarseDetune', parseInt(e.target.value))} className="w-full h-1 bg-indigo-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Fine</span> <span>{config.fineDetune} cents</span></label>
                            <input type="range" min="-50" max="50" step="1" value={config.fineDetune} onChange={(e) => updateOsc(oscKey, 'fineDetune', parseInt(e.target.value))} className="w-full h-1 bg-indigo-400 rounded appearance-none" />
                        </div>
                    </div>
                </div>
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-400">Filter</h4>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Cutoff</span> <span>{config.filterCutoff}Hz</span></label>
                        <input type="range" min="20" max="10000" step="10" value={config.filterCutoff} onChange={(e) => updateOsc(oscKey, 'filterCutoff', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                    </div>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Resonance</span> <span>{config.filterResonance.toFixed(1)}</span></label>
                        <input type="range" min="0" max="20" step="0.1" value={config.filterResonance} onChange={(e) => updateOsc(oscKey, 'filterResonance', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                    </div>
                </div>
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-400">Envelope</h4>
                    <EnvelopeGraph attack={config.attack} decay={config.decay} sustain={config.sustain} release={config.release} />
                    <div className="grid grid-cols-2 gap-3 pt-2">
                        <div><label className="flex justify-between text-xs mb-1"><span>A: {config.attack.toFixed(2)}s</span></label><input type="range" min="0.01" max="5.0" step="0.01" value={config.attack} onChange={(e) => updateOsc(oscKey, 'attack', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>D: {config.decay.toFixed(2)}s</span></label><input type="range" min="0.01" max="5.0" step="0.01" value={config.decay} onChange={(e) => updateOsc(oscKey, 'decay', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>S: {config.sustain.toFixed(2)}</span></label><input type="range" min="0.0" max="1.0" step="0.01" value={config.sustain} onChange={(e) => updateOsc(oscKey, 'sustain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>R: {config.release.toFixed(2)}s</span></label><input type="range" min="0.01" max="8.0" step="0.01" value={config.release} onChange={(e) => updateOsc(oscKey, 'release', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                    </div>
                </div>
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <h3 className="text-xs font-bold text-slate-300 uppercase mb-3">LFO</h3>
                    <div className="flex gap-2 mb-4 text-[10px]">
                        {(['none', 'pitch', 'filter', 'tremolo'] as const).map(target => (
                             <button key={target} onClick={() => updateOsc(oscKey, 'lfoTarget', target)} className={`flex-1 py-1 rounded border capitalize ${config.lfoTarget === target ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`}>{target}</button>
                        ))}
                    </div>
                    <div className="space-y-2">
                        <div><label className="flex justify-between text-xs mb-1"><span>Rate</span> <span>{config.lfoRate} Hz</span></label><input type="range" min="0.1" max="20" step="0.1" value={config.lfoRate} onChange={(e) => updateOsc(oscKey, 'lfoRate', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>Depth</span> <span>{config.lfoDepth}</span></label><input type="range" min="0" max="100" step="1" value={config.lfoDepth} onChange={(e) => updateOsc(oscKey, 'lfoDepth', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" /></div>
                    </div>
                </div>
            </div>
          </div>
      );
  };

  const arpConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };

  return (
    <div className="fixed top-0 right-0 h-full w-[450px] bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-0 overflow-hidden border-l border-slate-700 flex flex-col">
        <div className="flex justify-between items-center p-6 pb-2">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white">Close</button>
        </div>

        <div className="flex border-b border-slate-700 bg-slate-900/80 mx-4 mt-2 rounded-t-lg overflow-hidden">
            {(['normal', 'latch', 'strum', 'arpeggio'] as PlayMode[]).map(mode => (
                <button
                    key={mode}
                    onClick={() => setActiveVoiceMode(mode)}
                    className={`flex-1 py-3 text-xs font-bold uppercase transition border-b-2 ${activeVoiceMode === mode ? 'border-indigo-500 text-indigo-400 bg-slate-800' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}
                >
                    {mode}
                </button>
            ))}
        </div>

        {!isSaveMode ? (
            <div className="px-6 py-4 bg-slate-800 border-b border-slate-700 space-y-3">
                <div>
                    <label className="block text-[10px] text-slate-400 mb-1 uppercase font-bold tracking-wider">Active Patch</label>
                    <div className="relative">
                        <select 
                            value={currentPreset.name}
                            onChange={(e) => {
                                let p = PRESETS.find(pr => pr.name === e.target.value);
                                if (!p) p = userBank.find(pr => pr.name === e.target.value);
                                if (p) loadPreset(p);
                            }}
                            className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white appearance-none focus:border-indigo-500 focus:outline-none"
                        >
                            {Object.keys(categorizedPresets).map(cat => (
                                <optgroup key={cat} label={cat}>{categorizedPresets[cat].map(p => (<option key={p.id} value={p.name}>{p.name}</option>))}</optgroup>
                            ))}
                            <optgroup label="User Bank">{userBank.map((p, idx) => (<option key={`user-${idx}`} value={p.name}>{p.name}</option>))}</optgroup>
                        </select>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => { setSaveName(currentPreset.name); setIsSaveMode(true); }} className="flex-1 py-1.5 bg-indigo-700 hover:bg-indigo-600 text-indigo-100 text-xs font-bold rounded transition border border-indigo-500">Save to Slot</button>
                    <button onClick={handleResetToDefault} className="flex-1 py-1.5 bg-yellow-700 hover:bg-yellow-600 text-yellow-100 text-xs font-bold rounded transition border border-yellow-500">Reset to Default</button>
                </div>
            </div>
        ) : (
            <div className="px-6 py-4 bg-indigo-900/20 border-b border-indigo-500/30">
                <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] text-indigo-300 font-bold uppercase">Save Current Patch</label>
                    <button onClick={() => setIsSaveMode(false)} className="text-xs text-slate-400 hover:text-white">Cancel</button>
                </div>
                <input type="text" value={saveName} onChange={(e) => setSaveName(e.target.value)} placeholder="Patch Name" className="w-full bg-slate-900 border border-indigo-500 rounded p-2 text-sm mb-2 text-white" />
                <select value={saveSlotIndex} onChange={(e) => setSaveSlotIndex(parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white mb-3">
                    {userBank.map((p, idx) => (<option key={idx} value={idx}>Slot {idx+1}: {p.name}</option>))}
                </select>
                <button onClick={handleSaveToSlot} className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded text-xs transition">Confirm Save</button>
            </div>
        )}

        <div className="flex border-b border-slate-700 bg-slate-900/50">
            {(['osc1', 'osc2', 'osc3'] as const).map(osc => (
                 <button key={osc} onClick={() => setActiveTab(osc)} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === osc ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                    <span>{osc.replace('osc', 'Osc ')}</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${currentPreset[osc].enabled ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]' : 'bg-slate-700'}`}></span>
                </button>
            ))}
             <button onClick={() => setActiveTab('matrix')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'matrix' ? 'text-purple-400 border-b-2 border-purple-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Mods</span>
                <span className={`w-1.5 h-1.5 rounded-full ${(currentPreset.modMatrix?.length || 0) > 0 ? 'bg-purple-500 shadow-[0_0_5px_rgba(168,85,247,0.8)]' : 'bg-slate-700'}`}></span>
            </button>
             <button onClick={() => setActiveTab('fx')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'fx' ? 'text-green-400 border-b-2 border-green-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>FX</span>
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]"></span>
            </button>
             <button onClick={() => setActiveTab('arp')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'arp' ? 'text-red-400 border-b-2 border-red-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Arp</span>
                <span className={`w-1.5 h-1.5 rounded-full bg-red-500 shadow-[0_0_5px_rgba(239,68,68,0.8)]`}></span>
            </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700" onPointerUp={() => setDraggingCell(null)} onPointerLeave={() => setDraggingCell(null)} onPointerMove={handleMatrixDragMove}>
            {activeTab === 'osc1' && renderOscillatorTab('osc1', 'Oscillator 1')}
            {activeTab === 'osc2' && renderOscillatorTab('osc2', 'Oscillator 2')}
            {activeTab === 'osc3' && renderOscillatorTab('osc3', 'Oscillator 3')}

            {activeTab === 'matrix' && (
                <div className="space-y-4 animate-in fade-in duration-300">
                    <div className="flex justify-between items-center mb-2"><h3 className="text-sm font-bold text-purple-300 uppercase">Modulation Grid</h3><div className="text-[10px] text-slate-500 italic">Drag vertical on cells to adjust amount</div></div>
                    <div className="overflow-x-auto pb-4"><div className="min-w-[600px]"><div className="grid grid-cols-[60px_repeat(12,1fr)] gap-1">
                        <div className="text-[10px] font-bold text-slate-500">SRC / DST</div>{MATRIX_TARGETS.map(t => (<div key={t.id} className="text-[9px] font-bold text-slate-400 text-center uppercase rotate-0 whitespace-nowrap overflow-hidden text-ellipsis" title={t.label}>{t.label.replace('Osc', 'O').replace('Pitch', 'P').replace('Cut', 'C').replace('Gain', 'G').replace('Res', 'Q')}</div>))}
                        {MATRIX_SOURCES.map(source => (<React.Fragment key={source.id}><div className="text-[10px] font-bold text-purple-400 flex items-center h-8 bg-slate-900/50 px-1 rounded-l">{source.label}</div>{MATRIX_TARGETS.map(target => { const amount = getMatrixValue(source.id, target.id); const isActive = amount !== 0; return (<div key={`${source.id}-${target.id}`} className={`h-8 border border-slate-700 rounded flex flex-col justify-end items-center relative overflow-hidden cursor-ns-resize group ${isActive ? 'bg-purple-900/30 border-purple-500/50' : 'bg-slate-800 hover:bg-slate-700'}`} onPointerDown={(e) => handleMatrixDragStart(e, source.id, target.id)}>{isActive && (<div className={`absolute bottom-0 left-0 w-full transition-all ${amount > 0 ? 'bg-purple-500' : 'bg-orange-500'}`} style={{ height: `${Math.abs(amount)}%`, opacity: 0.4 }} />)}<span className={`text-[9px] z-10 font-mono ${isActive ? 'text-white font-bold' : 'text-transparent group-hover:text-slate-500'}`}>{amount !== 0 ? amount : '-'}</span></div>); })}</React.Fragment>))}
                    </div></div></div>
                </div>
            )}

            {activeTab === 'fx' && (
                 <div className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Global Effects ({activeVoiceMode})</h3>
                    <div><label className="flex justify-between text-xs mb-1 font-bold"><span>Master Gain</span> <span>{(currentPreset.gain * 100).toFixed(0)}%</span></label><input type="range" min="0.0" max="1.0" step="0.01" value={currentPreset.gain} onChange={(e) => updateGlobal('gain', parseFloat(e.target.value))} className="w-full h-1 bg-green-500 rounded appearance-none" /></div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-cyan-300 uppercase">Stereo & Pan</h3>
                         <div><label className="flex justify-between text-xs mb-1"><span>Stereo Width</span> <span>{((currentPreset.spread || 0) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.spread || 0} onChange={(e) => updateGlobal('spread', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Auto-Pan Rate</span> <span>{(currentPreset.stereoPanSpeed || 0).toFixed(2)} Hz</span></label><input type="range" min="0" max="10" step="0.1" value={currentPreset.stereoPanSpeed || 0} onChange={(e) => updateGlobal('stereoPanSpeed', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Auto-Pan Depth</span> <span>{((currentPreset.stereoPanDepth || 0) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.stereoPanDepth || 0} onChange={(e) => updateGlobal('stereoPanDepth', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" /></div>
                    </div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-teal-300 uppercase">Delay</h3>
                         <div><label className="flex justify-between text-xs mb-1"><span>Delay Mix</span> <span>{(currentPreset.delayMix * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.delayMix} onChange={(e) => updateGlobal('delayMix', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Time</span> <span>{currentPreset.delayTime.toFixed(2)}s</span></label><input type="range" min="0" max="2" step="0.05" value={currentPreset.delayTime} onChange={(e) => updateGlobal('delayTime', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Feedback</span> <span>{(currentPreset.delayFeedback * 100).toFixed(0)}%</span></label><input type="range" min="0" max="0.9" step="0.01" value={currentPreset.delayFeedback} onChange={(e) => updateGlobal('delayFeedback', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" /></div>
                    </div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-blue-300 uppercase">Reverb</h3>
                         <select value={currentPreset.reverbType || 'room'} onChange={(e) => handleReverbTypeChange(e.target.value as ReverbType)} className="w-full bg-slate-700 text-xs rounded p-1 border border-slate-600 capitalize" disabled={activeVoiceMode !== 'normal'}>{(['room', 'hall', 'cathedral', 'plate', 'shimmer'] as ReverbType[]).map(type => (<option key={type} value={type}>{type}</option>))}</select>
                         <div><label className="flex justify-between text-xs mb-1"><span>Mix</span> <span>{(currentPreset.reverbMix * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbMix} onChange={(e) => updateGlobal('reverbMix', parseFloat(e.target.value))} className="w-full h-1 bg-blue-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Size</span> <span>{(currentPreset.reverbSize || 2.5).toFixed(1)}s</span></label><input type="range" min="0.1" max="10.0" step="0.1" value={currentPreset.reverbSize || 2.5} onChange={(e) => updateGlobal('reverbSize', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Damping</span> <span>{((currentPreset.reverbDamping || 0.5) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbDamping || 0.5} onChange={(e) => updateGlobal('reverbDamping', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Diffusion</span> <span>{((currentPreset.reverbDiffusion || 0.8) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbDiffusion || 0.8} onChange={(e) => updateGlobal('reverbDiffusion', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} /></div>
                    </div>
                </div>
            )}

            {activeTab === 'arp' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Granular Arp Settings ({activeVoiceMode})</h3>
                    <div className="p-4 bg-slate-900/50 rounded border border-slate-700 space-y-4">

                        <div>
                            <label className="block text-xs font-bold text-slate-400 mb-1">Direction</label>
                            <div className="flex bg-slate-800 rounded border border-slate-600 overflow-hidden">
                                {(['order', 'up', 'down', 'updown', 'random'] as ArpDirection[]).map(dir => (
                                    <button 
                                        key={dir} 
                                        onClick={() => updateArp('direction', dir)}
                                        className={`flex-1 py-1 text-[10px] uppercase font-bold ${arpConfig.direction === dir ? 'bg-red-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                                    >
                                        {dir}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Granular Settings replacing redundant ones */}

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Probability</span> <span className="font-bold text-white">{(arpConfig.probability !== undefined ? arpConfig.probability * 100 : 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.05" value={arpConfig.probability !== undefined ? arpConfig.probability : 1.0} onChange={(e) => updateArp('probability', parseFloat(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none" />
                            <p className="text-[9px] text-slate-500 mt-1">Chance of each step playing.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Humanize</span> <span className="font-bold text-white">{arpConfig.humanize || 0} ms</span></label>
                            <input type="range" min="0" max="100" step="5" value={arpConfig.humanize || 0} onChange={(e) => updateArp('humanize', parseInt(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none" />
                            <p className="text-[9px] text-slate-500 mt-1">Random timing offset per step.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Octave Range</span> <span className="font-bold text-white">{arpConfig.octaves}</span></label>
                            <input type="range" min="1" max="4" step="1" value={arpConfig.octaves} onChange={(e) => updateArp('octaves', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" />
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Swing</span> <span className="font-bold text-white">{arpConfig.swing}%</span></label>
                            <input type="range" min="0" max="100" step="1" value={arpConfig.swing} onChange={(e) => updateArp('swing', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" />
                        </div>

                    </div>
                    <p className="text-[10px] text-slate-500 text-center italic">Sequence Length and Division are now controlled per-pattern in the matrix view.</p>
                </div>
            )}

            <div className="pt-4 border-t border-slate-700 mt-4">
                <p className="text-[10px] text-slate-500 text-center">Changes applied immediately</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

import React, { useEffect, useRef, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, ButtonShape } from '../types';
import { getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { useLatticeData } from '../hooks/useLatticeData';
import { useLatticeVisuals } from '../hooks/useLatticeVisuals';
import { useLatticeInteraction } from '../hooks/useLatticeInteraction';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; 
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const { data, isGenerating, isInitialLoad, setIsInitialLoad, dynamicSize, dynamicSizeRef: hookDynamicSizeRef } = useLatticeData(settings, globalScale);
  const prevDynamicSizeRef = useRef(2000);

  // Derive static grid separately to pass to interaction hook before getting visual latches
  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);
  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const GRID_CELL_SIZE = 100;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const { 
      activeCursors, 
      persistentLatches, 
      setPersistentLatches, 
      cursorPositionsRef, 
      visualLatchedNodes, 
      audioLatchedNodes,
      lastTouchedLimitRef,
      lastTouchedNodeRef,
      handlePointerDown, 
      handlePointerMove, 
      handlePointerUp 
  } = useLatticeInteraction(
      settings, audioEngine, midiService, nodeMap, spatialGrid, dynamicSize, globalScale, 
      activeChordIds, latchMode, uiUnlocked, scrollContainerRef, dynamicCanvasRef, 
      onLimitInteraction, onNodeTrigger
  );

  const { activeLines, brightenedLines } = useLatticeVisuals(data, settings, dynamicSize, globalScale, visualLatchedNodes);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const activeCursorsRef = useRef(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const nodeMapRef = useRef(nodeMap);
  const globalScaleRef = useRef(globalScale);

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const lastNode = lastTouchedNodeRef.current;
        if (lastNode) {
             updateSettings((prev: AppSettings) => {
                 return { 
                     ...prev, 
                     generationOrigins: [...prev.generationOrigins, lastNode] 
                 };
             });
        }
    },
    decreaseDepth: () => {
        updateSettings((prev: AppSettings) => {
             if (prev.generationOrigins.length <= 1) return prev; 
             const newOrigins = [...prev.generationOrigins];
             newOrigins.pop();
             return { ...prev, generationOrigins: newOrigins };
        });
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const visualDeps = useMemo(() => JSON.stringify({
      tuning: settings.tuningSystem,
      layout: settings.layoutApproach,
      skin: settings.activeSkin,
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.tuningSystem, settings.layoutApproach, settings.activeSkin, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals, settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize, globalScale]);

  // --- STATIC CANVAS RENDER ---
  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
      const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;
      const skin = settings.activeSkin;

      // Skin Constants
      const isMinimal = skin === 'minimal';
      const isTechnical = skin === 'technical';
      const isOrganic = skin === 'organic';

      const isAlternateJILayout = settings.tuningSystem === 'ji' && settings.layoutApproach !== 'lattice';
      const layoutSizeMult = isAlternateJILayout ? 1.5 : 1.0; 

      // Batch lines by limit
      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
      }

      ctx.lineCap = isTechnical ? 'butt' : 'round';

      // DRAW LINES
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }

          // Skin: Line Styles
          if (isTechnical) {
              ctx.lineWidth = 0.5 * globalScale;
              ctx.strokeStyle = color;
              ctx.globalAlpha = 0.6 * visualSettings.opacity;
              if (limit !== 1) ctx.setLineDash([2 * globalScale, 4 * globalScale]);
              else ctx.setLineDash([]);
          } 
          else if (isMinimal) {
              ctx.lineWidth = (limit === 1 ? 2 : 1) * globalScale;
              ctx.strokeStyle = limit === 1 ? '#475569' : '#334155'; // Slate greys
              ctx.globalAlpha = 0.4 * visualSettings.opacity;
              ctx.setLineDash([]);
          } 
          else if (isOrganic) {
              ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size * globalScale;
              ctx.strokeStyle = color;
              ctx.globalAlpha = 0.15 * visualSettings.opacity; // Very soft
              ctx.setLineDash([]);
          }
          else {
              // Default
              ctx.lineWidth = (limit === 1 ? 3 : 1) * visualSettings.size * globalScale; 
              ctx.strokeStyle = color;
              ctx.globalAlpha = (isAlternateJILayout ? 0.5 : 0.3) * visualSettings.opacity; 
              if (limit === 1) ctx.setLineDash([5 * globalScale, 5 * globalScale]);
              else ctx.setLineDash([]);
          }
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      // DRAW NODES
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;

          const radius = baseRadius * limitScale * layoutSizeMult;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          // Skin: Fill/Stroke Styles
          if (isTechnical) {
              ctx.fillStyle = '#0f172a'; // Dark bg
              ctx.fill();
              ctx.lineWidth = 2 * globalScale;
              ctx.strokeStyle = cTop;
              ctx.stroke();
          } 
          else if (isMinimal) {
              ctx.fillStyle = cTop; // Flat color
              ctx.fill();
              // No stroke
          }
          else if (isOrganic) {
              const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
              grad.addColorStop(0, cTop);
              grad.addColorStop(1, 'rgba(0,0,0,0)'); // Fade out
              ctx.fillStyle = grad;
              ctx.globalAlpha = 0.8 * limitOpacity;
              ctx.fill();
              ctx.globalAlpha = 1.0 * limitOpacity;
          }
          else {
              // Default
              const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
              grad.addColorStop(0.45, cTop);
              grad.addColorStop(0.55, cBottom);
              ctx.fillStyle = grad;
              ctx.fill();
          }

          const combinedScale = settings.buttonSizeScale * limitScale * layoutSizeMult;
          if (combinedScale > 0.4) {

              if (isTechnical) {
                  ctx.fillStyle = cTop;
                  ctx.font = `normal ${Math.max(10, 12 * combinedScale * globalScale)}px monospace`;
              } else if (isMinimal) {
                  ctx.fillStyle = 'rgba(255,255,255,0.9)';
                  ctx.font = `bold ${Math.max(10, 14 * combinedScale * globalScale)}px sans-serif`;
              } else if (isOrganic) {
                  ctx.fillStyle = 'white';
                  ctx.font = `italic ${Math.max(10, 14 * combinedScale * globalScale)}px serif`;
              } else {
                  ctx.fillStyle = 'white';
                  ctx.font = `bold ${Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * globalScale}px sans-serif`; 
              }

              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;

              // Organic skin hides numbers on small nodes for cleanliness
              if (!isOrganic || combinedScale > 0.6) {
                  ctx.fillText(node.n.toString(), x, y - (radius * spacingY));

                  if (settings.showFractionBar) {
                      ctx.beginPath();
                      ctx.moveTo(x - (radius * 0.4), y);
                      ctx.lineTo(x + (radius * 0.4), y);
                      ctx.lineWidth = 1 * globalScale;
                      ctx.strokeStyle = isTechnical ? cTop : `rgba(255,255,255,${0.8 * limitOpacity})`;
                      ctx.stroke();
                  }

                  ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
              }
          }
      }
  }, [data, visualDeps]); 

  // --- DYNAMIC CANVAS RENDER ---
  const render = (time: number) => {
      const bgCanvas = bgLineCanvasRef.current;
      const activeCanvas = dynamicCanvasRef.current;
      if (!bgCanvas || !activeCanvas) {
           animationFrameRef.current = requestAnimationFrame(render);
           return;
      }

      const bgCtx = bgCanvas.getContext('2d', { alpha: true });
      const activeCtx = activeCanvas.getContext('2d', { alpha: true });
      if (!bgCtx || !activeCtx) return; 

      const currentSettings = settingsRef.current;
      const currentVisualLatched = visualLatchedRef.current; 
      const currentActiveLines = activeLinesRef.current;
      const currentBrightenedLines = brightenedLinesRef.current;
      const size = hookDynamicSizeRef.current;
      const cursors = activeCursorsRef.current;
      const currentGlobalScale = globalScaleRef.current;

      const skin = currentSettings.activeSkin;
      const isMinimal = skin === 'minimal';
      const isTechnical = skin === 'technical';
      const isOrganic = skin === 'organic';

      const isAlternateJILayout = currentSettings.tuningSystem === 'ji' && currentSettings.layoutApproach !== 'lattice';
      const layoutSizeMult = isAlternateJILayout ? 1.5 : 1.0; 

      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
      const dpr = Math.min(window.devicePixelRatio || 1, isMobile ? 1.5 : 2.0);

      if (bgCanvas.width !== size * dpr || bgCanvas.height !== size * dpr) {
            bgCanvas.width = size * dpr;
            bgCanvas.height = size * dpr;
            activeCanvas.width = size * dpr;
            activeCanvas.height = size * dpr;
            bgCtx.scale(dpr, dpr);
            activeCtx.scale(dpr, dpr);
      }

      let viewX = 0, viewY = 0, viewW = size, viewH = size;
      if (scrollContainerRef.current) {
          viewX = scrollContainerRef.current.scrollLeft;
          viewY = scrollContainerRef.current.scrollTop;
          viewW = scrollContainerRef.current.clientWidth;
          viewH = scrollContainerRef.current.clientHeight;
      }

      bgCtx.clearRect(viewX, viewY, viewW, viewH);
      activeCtx.clearRect(viewX, viewY, viewW, viewH);

      const centerOffset = size / 2;
      const spacing = currentSettings.buttonSpacingScale * currentGlobalScale;
      const baseRadius = (60 * currentSettings.buttonSizeScale * currentGlobalScale) / 2;
      const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
      const colorCache = currentSettings.colors;

      const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
      const rawPhase = (time * 0.001 * animationSpeed);
      const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

      bgCtx.lineCap = isTechnical ? 'butt' : 'round';
      activeCtx.lineCap = isTechnical ? 'butt' : 'round';

      const viewPad = 100;
      const leftBound = viewX - viewPad;
      const rightBound = viewX + viewW + viewPad;
      const topBound = viewY - viewPad;
      const bottomBound = viewY + viewH + viewPad;

      // Active Lines Rendering (Background Canvas)
      if (currentBrightenedLines.length > 0) {
            bgCtx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;
                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;
                const limitColor = colorCache[line.limit] || '#666';
                bgCtx.beginPath();
                bgCtx.moveTo(x1, y1);
                bgCtx.lineTo(x2, y2);

                if (isTechnical) {
                    bgCtx.lineWidth = 1 * currentGlobalScale;
                    bgCtx.strokeStyle = limitColor;
                    bgCtx.globalAlpha = 1.0;
                } else if (isMinimal) {
                    bgCtx.lineWidth = 2 * currentGlobalScale;
                    bgCtx.strokeStyle = limitColor; 
                    bgCtx.globalAlpha = 0.6;
                } else if (isOrganic) {
                    bgCtx.lineWidth = 4 * currentGlobalScale;
                    bgCtx.strokeStyle = limitColor;
                    bgCtx.globalAlpha = 0.3;
                } else {
                    bgCtx.lineWidth = 1 * currentGlobalScale;
                    bgCtx.strokeStyle = limitColor;
                    bgCtx.globalAlpha = 0.8; 
                }

                bgCtx.stroke();
            }
      }

      bgCtx.setLineDash([]); 
      for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;
            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;
            const limitColor = colorCache[line.limit] || '#666';
            bgCtx.beginPath();
            bgCtx.moveTo(x1, y1);
            bgCtx.lineTo(x2, y2);

            if (isTechnical) {
                bgCtx.lineWidth = 2 * currentGlobalScale;
                bgCtx.strokeStyle = '#fff';
                bgCtx.setLineDash([4, 4]);
            } else if (isMinimal) {
                bgCtx.lineWidth = 3 * currentGlobalScale;
                bgCtx.strokeStyle = limitColor;
            } else if (isOrganic) {
                bgCtx.lineWidth = 8 * currentGlobalScale;
                bgCtx.strokeStyle = limitColor;
                bgCtx.globalAlpha = 0.5;
            } else {
                bgCtx.lineWidth = 4 * currentGlobalScale;
                bgCtx.strokeStyle = limitColor;
            }
            bgCtx.stroke();
            bgCtx.setLineDash([]);
            bgCtx.globalAlpha = 1.0;

            if (currentSettings.isVoiceLeadingAnimationEnabled && !isMinimal) {
                const grad = bgCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;
                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, isTechnical ? 'rgba(0,255,0,1)' : 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');
                bgCtx.strokeStyle = grad;
                bgCtx.lineWidth = (isTechnical ? 4 : 10 * (0.5 + currentSettings.voiceLeadingGlowAmount)) * currentGlobalScale;
                bgCtx.globalAlpha = isTechnical ? 1.0 : 0.3; 
                bgCtx.stroke();

                // restore
                bgCtx.lineWidth = 4 * currentGlobalScale;
                bgCtx.globalAlpha = 1.0;
            }
      }

      // Active Nodes Rendering (Active Canvas)
      for (const id of currentVisualLatched.keys()) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;
             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;
             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;
             const cTop = colorCache[node.limitTop] || '#666';
             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;

             const radius = baseRadius * limitScale * zoomScale * layoutSizeMult;

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius);
                activeCtx.lineTo(x + radius, y);
                activeCtx.lineTo(x, y + radius);
                activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             if (isTechnical) {
                 activeCtx.fillStyle = '#000';
                 activeCtx.fill();
                 activeCtx.strokeStyle = '#0f0'; // Retro Terminal Green
                 activeCtx.lineWidth = 2 * currentGlobalScale;
                 activeCtx.stroke();

                 // Crosshair
                 activeCtx.beginPath();
                 activeCtx.moveTo(x - radius*1.5, y); activeCtx.lineTo(x + radius*1.5, y);
                 activeCtx.moveTo(x, y - radius*1.5); activeCtx.lineTo(x, y + radius*1.5);
                 activeCtx.strokeStyle = cTop;
                 activeCtx.lineWidth = 1 * currentGlobalScale;
                 activeCtx.stroke();

             } else if (isMinimal) {
                 activeCtx.fillStyle = cTop;
                 activeCtx.fill();
                 activeCtx.strokeStyle = 'white';
                 activeCtx.lineWidth = 4 * currentGlobalScale;
                 activeCtx.stroke();
             } else if (isOrganic) {
                 const grad = activeCtx.createRadialGradient(x, y, 0, x, y, radius);
                 grad.addColorStop(0, '#fff'); // Hot center
                 grad.addColorStop(0.3, cTop);
                 grad.addColorStop(1, 'rgba(0,0,0,0)');
                 activeCtx.fillStyle = grad;
                 activeCtx.fill();
             } else {
                 // Default
                 const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
                 grad.addColorStop(0.45, cTop);
                 grad.addColorStop(0.55, colorCache[node.limitBottom] || '#666');
                 activeCtx.fillStyle = grad;
                 activeCtx.fill();

                 if (currentSettings.isColoredIlluminationEnabled) {
                     const rp = getRainbowPeriod(currentSettings.buttonSpacingScale * currentGlobalScale);
                     const phase = (y % rp) / rp;
                     const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                     const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                     activeCtx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                     activeCtx.lineWidth = 4 * currentGlobalScale;
                 } else {
                     activeCtx.strokeStyle = 'white';
                     activeCtx.lineWidth = 3 * currentGlobalScale;
                 }
                 activeCtx.stroke();
             }

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale * layoutSizeMult;
             if (combinedScale > 0.4) {
                if (isTechnical) {
                    activeCtx.fillStyle = '#0f0';
                    activeCtx.font = `bold ${Math.max(12, 16 * combinedScale * currentGlobalScale)}px monospace`;
                } else {
                    activeCtx.fillStyle = 'white';
                    activeCtx.font = `bold ${Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale * currentGlobalScale}px sans-serif`; 
                }

                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;

                if (!isOrganic || combinedScale > 0.6) {
                    activeCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                    if (currentSettings.showFractionBar) {
                        activeCtx.beginPath();
                        activeCtx.moveTo(x - (radius * 0.4), y);
                        activeCtx.lineTo(x + (radius * 0.4), y);
                        activeCtx.lineWidth = 1 * currentGlobalScale;
                        activeCtx.strokeStyle = isTechnical ? '#0f0' : 'white';
                        activeCtx.stroke();
                    }
                    activeCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
                }
             }
      }

      // Pitch Bend Visual
      if (currentSettings.isPitchBendEnabled) {
            cursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset;
                         const pos = cursorPositionsRef.current.get(c.pointerId);
                         if (!pos) return;
                         let cx = 0, cy = 0;
                         if (scrollContainerRef.current) {
                             const r = scrollContainerRef.current.getBoundingClientRect();
                             cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                             cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                         }
                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = isTechnical ? '#0f0' : 'white';
                         activeCtx.lineWidth = (isTechnical ? 1 : 2) * currentGlobalScale;
                         if(isTechnical) activeCtx.setLineDash([5, 5]);
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                         activeCtx.globalAlpha = 1.0;
                         activeCtx.setLineDash([]);
                    }
                }
            });
      }

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      switch(mode) {
          case 'rainbow':
              const period = getRainbowPeriod(settings.buttonSpacingScale * globalScale);
              const stops = [];
              for(let i=0; i<=6; i++) {
                  const pct = (i/6)*100;
                  const hue = (settings.rainbowOffset + i*60);
                  stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
              }
              return { ...baseStyle, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${period}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp} onPointerCancel={handlePointerUp}>
        <div className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" style={{ width: '100%', height: '100%' }} />
           {isGenerating && (<div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl"><svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg><span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span></div>)}
        </div>
    </div>
  );
});

