const NumberInput = ({ value, min, max, onChange, suffix = "", className = "", disabled = false }: { value: number; min: number; max: number; onChange: (val: number) => void; suffix?: string; className?: string; disabled?: boolean; }) => {
    const safeValue = (typeof value === 'number' && !isNaN(value)) ? value : min;
    const [text, setText] = useState(safeValue.toString());
    const [prevValue, setPrevValue] = useState(safeValue);
    const [error, setError] = useState<string | null>(null);
    if (value !== prevValue && value !== undefined && !isNaN(value)) {
        const currentNum = parseFloat(text);
        if (Math.abs(currentNum - value) > 0.0001) { setText(value.toString()); setError(null); }
        setPrevValue(value);
    }
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        if (val !== '' && !/^[\d.]+$/.test(val)) return;
        setText(val);
        if (val === '') return; 
        const num = parseFloat(val);
        if (isNaN(num)) return;
        if (num < min || num > max) { setError(`Range: ${min}-${max}`); } else { setError(null); onChange(num); }
    };
    const handleBlur = () => {
        const num = parseFloat(text);
        if (text === '' || isNaN(num) || error) { setText(prevValue.toString()); setError(null); }
    };
    return (
        <div className={`flex flex-col flex-grow ${disabled ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
            <div className="relative">
                <input type="text" inputMode="decimal" value={text} onChange={handleChange} onBlur={handleBlur} disabled={disabled} className={`w-full bg-slate-700 rounded p-2 text-sm text-white border border-slate-600 focus:outline-none focus:border-blue-500 transition-colors ${className} ${error ? 'border-red-500 focus:border-red-500' : ''}`} />
                {suffix && <span className="absolute right-3 top-2 text-sm text-slate-400 pointer-events-none">{suffix}</span>}
            </div>
            {error && <span className="text-[10px] text-red-400 mt-1 font-bold animate-pulse">{error}</span>}
        </div>
    );
};

const SkinPreviewCanvas = ({ skin, colors }: { skin: string, colors: LimitColorMap }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const w = canvas.width;
        const h = canvas.height;
        ctx.clearRect(0, 0, w, h);

        // Background shim if technical
        if (skin === 'technical') {
            ctx.fillStyle = '#0f172a';
            ctx.fillRect(0, 0, w, h);
        }

        // Configs
        const isMinimal = skin === 'minimal';
        const isTechnical = skin === 'technical';
        const isOrganic = skin === 'organic';

        const cx = w / 2;
        const cy = h / 2;
        const offset = 25;

        // Draw Line
        const limit = 3;
        const color = colors[limit] || '#EAB308';

        ctx.beginPath();
        ctx.moveTo(cx - offset, cy);
        ctx.lineTo(cx + offset, cy);

        if (isTechnical) {
            ctx.lineWidth = 1;
            ctx.strokeStyle = color;
            ctx.setLineDash([2, 4]);
        } else if (isMinimal) {
            ctx.lineWidth = 2;
            ctx.strokeStyle = '#334155';
            ctx.setLineDash([]);
        } else if (isOrganic) {
            ctx.lineWidth = 4;
            ctx.strokeStyle = color;
            ctx.globalAlpha = 0.5;
            ctx.setLineDash([]);
        } else {
            ctx.lineWidth = 2;
            ctx.strokeStyle = color;
            ctx.globalAlpha = 0.5;
            ctx.setLineDash([]);
        }
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.globalAlpha = 1.0;

        // Draw Nodes
        const drawNode = (x: number, y: number, l: number) => {
            const c = colors[l];
            const r = 10;
            ctx.beginPath();

            // Simple logic for preview shape (always circle for simplicity in preview)
            ctx.arc(x, y, r, 0, Math.PI*2);

            if (isTechnical) {
                ctx.fillStyle = '#0f172a';
                ctx.fill();
                ctx.lineWidth = 2;
                ctx.strokeStyle = '#0f0';
                ctx.stroke();

                // Tech crosshair
                ctx.beginPath();
                ctx.moveTo(x - r, y); ctx.lineTo(x + r, y);
                ctx.moveTo(x, y - r); ctx.lineTo(x, y + r);
                ctx.lineWidth = 1;
                ctx.strokeStyle = c;
                ctx.stroke();

            } else if (isMinimal) {
                ctx.fillStyle = c;
                ctx.fill();
            } else if (isOrganic) {
                const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
                grad.addColorStop(0, '#fff');
                grad.addColorStop(0.3, c);
                grad.addColorStop(1, 'rgba(0,0,0,0)');
                ctx.fillStyle = grad;
                ctx.fill();
            } else {
                const grad = ctx.createLinearGradient(x, y-r, x, y+r);
                grad.addColorStop(0, c);
                grad.addColorStop(1, '#333');
                ctx.fillStyle = grad;
                ctx.fill();
                ctx.lineWidth = 2;
                ctx.strokeStyle = 'white';
                ctx.stroke();
            }
        };

        drawNode(cx - offset, cy, 1);
        drawNode(cx + offset, cy, 3);

    }, [skin, colors]);

    return <canvas ref={canvasRef} width={120} height={50} className="rounded border border-slate-600 bg-slate-900/50 shadow-inner" />;
};

