                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <div className="grid grid-cols-5 gap-1 mb-4" role="group" aria-label="Waveform Selection">
                        {Object.values(WaveformType).map(w => (
                            <button key={w} onClick={() => updateOsc(oscKey, 'waveform', w)} className={`px-1 py-1 text-[9px] font-bold uppercase rounded border ${config.waveform === w ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`} aria-pressed={config.waveform === w} aria-label={`Select ${w} waveform`}>{w}</button>
