                    </div>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Resonance</span> <span>{config.filterResonance.toFixed(1)}</span></label>
                        <input type="range" min="0" max="20" step="0.1" value={config.filterResonance} onChange={(e) => updateOsc(oscKey, 'filterResonance', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" aria-label="Filter Resonance" />
                    </div>
                </div>
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-400">Envelope</h4>
                    <EnvelopeGraph attack={config.attack} decay={config.decay} sustain={config.sustain} release={config.release} />
                    <div className="grid grid-cols-2 gap-3 pt-2">
                        <div><label className="flex justify-between text-xs mb-1"><span>A: {config.attack.toFixed(2)}s</span></label><input type="range" min="0.01" max="5.0" step="0.01" value={config.attack} onChange={(e) => updateOsc(oscKey, 'attack', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" aria-label="Attack Time" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>D: {config.decay.toFixed(2)}s</span></label><input type="range" min="0.01" max="5.0" step="0.01" value={config.decay} onChange={(e) => updateOsc(oscKey, 'decay', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" aria-label="Decay Time" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>S: {config.sustain.toFixed(2)}</span></label><input type="range" min="0.0" max="1.0" step="0.01" value={config.sustain} onChange={(e) => updateOsc(oscKey, 'sustain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" aria-label="Sustain Level" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>R: {config.release.toFixed(2)}s</span></label><input type="range" min="0.01" max="8.0" step="0.01" value={config.release} onChange={(e) => updateOsc(oscKey, 'release', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" aria-label="Release Time" /></div>
                    </div>
                </div>
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <h3 className="text-xs font-bold text-slate-300 uppercase mb-3">LFO</h3>
                    <div className="flex gap-2 mb-4 text-[10px]" role="group" aria-label="LFO Target Selection">
                        {(['none', 'pitch', 'filter', 'tremolo'] as const).map(target => (
                             <button key={target} onClick={() => updateOsc(oscKey, 'lfoTarget', target)} className={`flex-1 py-1 rounded border capitalize ${config.lfoTarget === target ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`} aria-pressed={config.lfoTarget === target} aria-label={`Set LFO target to ${target}`}>{target}</button>
                        ))}
                    </div>
                    <div className="space-y-2">
                        <div><label className="flex justify-between text-xs mb-1"><span>Rate</span> <span>{config.lfoRate} Hz</span></label><input type="range" min="0.1" max="20" step="0.1" value={config.lfoRate} onChange={(e) => updateOsc(oscKey, 'lfoRate', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" aria-label="LFO Rate" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>Depth</span> <span>{config.lfoDepth}</span></label><input type="range" min="0" max="100" step="1" value={config.lfoDepth} onChange={(e) => updateOsc(oscKey, 'lfoDepth', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" aria-label="LFO Depth" /></div>
                    </div>
                </div>
            </div>
          </div>
      );
  };

  const arpConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 8, probability: 1.0, humanize: 0 };

  return (
    <div className="fixed top-0 right-0 h-full w-[450px] bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-0 overflow-hidden border-l border-slate-700 flex flex-col" role="dialog" aria-modal="true" aria-label="Synthesizer Controls">
        <div className="flex justify-between items-center p-6 pb-2">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white" aria-label="Close Synthesizer">Close</button>
        </div>

        <div className="flex border-b border-slate-700 bg-slate-900/80 mx-4 mt-2 rounded-t-lg overflow-hidden">
            {(['normal', 'latch', 'strum', 'arpeggio'] as PlayMode[]).map(mode => (
                <button
                    key={mode}
                    onClick={() => setActiveVoiceMode(mode)}
                    className={`flex-1 py-3 text-xs font-bold uppercase transition border-b-2 ${activeVoiceMode === mode ? 'border-indigo-500 text-indigo-400 bg-slate-800' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}
                    aria-pressed={activeVoiceMode === mode}
                >
                    {mode}
                </button>
            ))}
        </div>

        {!isSaveMode ? (
            <div className="px-6 py-4 bg-slate-800 border-b border-slate-700 space-y-3">
                <div>
                    <label className="block text-[10px] text-slate-400 mb-1 uppercase font-bold tracking-wider" htmlFor="patch-select">Active Patch</label>
                    <div className="relative">
                        <select 
                            id="patch-select"
                            value={currentPreset.name}
                            onChange={(e) => {
                                let p = PRESETS.find(pr => pr.name === e.target.value);
                                if (!p) p = userBank.find(pr => pr.name === e.target.value);
                                if (p) loadPreset(p);
                            }}
                            className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white appearance-none focus:border-indigo-500 focus:outline-none"
                        >
                            {Object.keys(categorizedPresets).map(cat => (
                                <optgroup key={cat} label={cat}>{categorizedPresets[cat].map(p => (<option key={p.id} value={p.name}>{p.name}</option>))}</optgroup>
                            ))}
                            <optgroup label="User Bank">{userBank.map((p, idx) => (<option key={`user-${idx}`} value={p.name}>{p.name}</option>))}</optgroup>
                        </select>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => { setSaveName(currentPreset.name); setIsSaveMode(true); }} className="flex-1 py-1.5 bg-indigo-700 hover:bg-indigo-600 text-indigo-100 text-xs font-bold rounded transition border border-indigo-500">Save to Slot</button>
                    <button onClick={handleResetToDefault} className="flex-1 py-1.5 bg-yellow-700 hover:bg-yellow-600 text-yellow-100 text-xs font-bold rounded transition border border-yellow-500">Reset to Default</button>
                </div>
            </div>
        ) : (
            <div className="px-6 py-4 bg-indigo-900/20 border-b border-indigo-500/30">
                <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] text-indigo-300 font-bold uppercase">Save Current Patch</label>
                    <button onClick={() => setIsSaveMode(false)} className="text-xs text-slate-400 hover:text-white">Cancel</button>
                </div>
                <input type="text" value={saveName} onChange={(e) => setSaveName(e.target.value)} placeholder="Patch Name" className="w-full bg-slate-900 border border-indigo-500 rounded p-2 text-sm mb-2 text-white" aria-label="Patch Name" />
                <select value={saveSlotIndex} onChange={(e) => setSaveSlotIndex(parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white mb-3" aria-label="Destination Slot">
                    {userBank.map((p, idx) => (<option key={idx} value={idx}>Slot {idx+1}: {p.name}</option>))}
                </select>
                <button onClick={handleSaveToSlot} className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded text-xs transition">Confirm Save</button>
            </div>
        )}

        <div className="flex border-b border-slate-700 bg-slate-900/50" role="tablist">
            {(['osc1', 'osc2', 'osc3'] as const).map(osc => (
                 <button role="tab" aria-selected={activeTab === osc} aria-controls={`panel-${osc}`} key={osc} onClick={() => setActiveTab(osc)} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === osc ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                    <span>{osc.replace('osc', 'Osc ')}</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${currentPreset[osc].enabled ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]' : 'bg-slate-700'}`}></span>
                </button>
            ))}
             <button role="tab" aria-selected={activeTab === 'matrix'} aria-controls="panel-matrix" onClick={() => setActiveTab('matrix')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'matrix' ? 'text-purple-400 border-b-2 border-purple-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Mods</span>
                <span className={`w-1.5 h-1.5 rounded-full ${(currentPreset.modMatrix?.length || 0) > 0 ? 'bg-purple-500 shadow-[0_0_5px_rgba(168,85,247,0.8)]' : 'bg-slate-700'}`}></span>
            </button>
             <button role="tab" aria-selected={activeTab === 'fx'} aria-controls="panel-fx" onClick={() => setActiveTab('fx')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'fx' ? 'text-green-400 border-b-2 border-green-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>FX</span>
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]"></span>
            </button>
             <button role="tab" aria-selected={activeTab === 'arp'} aria-controls="panel-arp" onClick={() => setActiveTab('arp')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'arp' ? 'text-red-400 border-b-2 border-red-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Arp</span>
                <span className={`w-1.5 h-1.5 rounded-full bg-red-500 shadow-[0_0_5px_rgba(239,68,68,0.8)]`}></span>
            </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700" onPointerUp={() => setDraggingCell(null)} onPointerLeave={() => setDraggingCell(null)} onPointerMove={handleMatrixDragMove}>
            {activeTab === 'osc1' && renderOscillatorTab('osc1', 'Oscillator 1')}
            {activeTab === 'osc2' && renderOscillatorTab('osc2', 'Oscillator 2')}
            {activeTab === 'osc3' && renderOscillatorTab('osc3', 'Oscillator 3')}

            {activeTab === 'matrix' && (
                <div role="tabpanel" id="panel-matrix" className="space-y-4 animate-in fade-in duration-300">
                    <div className="flex justify-between items-center mb-2"><h3 className="text-sm font-bold text-purple-300 uppercase">Modulation Grid</h3><div className="text-[10px] text-slate-500 italic">Drag vertical on cells to adjust amount</div></div>
                    <div className="overflow-x-auto pb-4"><div className="min-w-[600px]"><div className="grid grid-cols-[60px_repeat(12,1fr)] gap-1">
                        <div className="text-[10px] font-bold text-slate-500">SRC / DST</div>{MATRIX_TARGETS.map(t => (<div key={t.id} className="text-[9px] font-bold text-slate-400 text-center uppercase rotate-0 whitespace-nowrap overflow-hidden text-ellipsis" title={t.label}>{t.label.replace('Osc', 'O').replace('Pitch', 'P').replace('Cut', 'C').replace('Gain', 'G').replace('Res', 'Q')}</div>))}
                        {MATRIX_SOURCES.map(source => (<React.Fragment key={source.id}><div className="text-[10px] font-bold text-purple-400 flex items-center h-8 bg-slate-900/50 px-1 rounded-l">{source.label}</div>{MATRIX_TARGETS.map(target => { const amount = getMatrixValue(source.id, target.id); const isActive = amount !== 0; return (<div key={`${source.id}-${target.id}`} title={`${source.label} -> ${target.label}: ${amount}%`} className={`h-8 border border-slate-700 rounded flex flex-col justify-end items-center relative overflow-hidden cursor-ns-resize group ${isActive ? 'bg-purple-900/30 border-purple-500/50' : 'bg-slate-800 hover:bg-slate-700'}`} onPointerDown={(e) => handleMatrixDragStart(e, source.id, target.id)}>{isActive && (<div className={`absolute bottom-0 left-0 w-full transition-all ${amount > 0 ? 'bg-purple-500' : 'bg-orange-500'}`} style={{ height: `${Math.abs(amount)}%`, opacity: 0.4 }} />)}<span className={`text-[9px] z-10 font-mono ${isActive ? 'text-white font-bold' : 'text-transparent group-hover:text-slate-500'}`}>{amount !== 0 ? amount : '-'}</span></div>); })}</React.Fragment>))}
                    </div></div></div>
                </div>
            )}

            {activeTab === 'fx' && (
                 <div role="tabpanel" id="panel-fx" className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Global Effects ({activeVoiceMode})</h3>
                    <div><label className="flex justify-between text-xs mb-1 font-bold"><span>Master Gain</span> <span>{(currentPreset.gain * 100).toFixed(0)}%</span></label><input type="range" min="0.0" max="1.0" step="0.01" value={currentPreset.gain} onChange={(e) => updateGlobal('gain', parseFloat(e.target.value))} className="w-full h-1 bg-green-500 rounded appearance-none" aria-label="Master Gain" /></div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-cyan-300 uppercase">Stereo & Pan</h3>
                         <div><label className="flex justify-between text-xs mb-1"><span>Stereo Width</span> <span>{((currentPreset.spread || 0) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.spread || 0} onChange={(e) => updateGlobal('spread', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" aria-label="Stereo Width" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Auto-Pan Rate</span> <span>{(currentPreset.stereoPanSpeed || 0).toFixed(2)} Hz</span></label><input type="range" min="0" max="10" step="0.1" value={currentPreset.stereoPanSpeed || 0} onChange={(e) => updateGlobal('stereoPanSpeed', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" aria-label="Auto-Pan Rate" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Auto-Pan Depth</span> <span>{((currentPreset.stereoPanDepth || 0) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.stereoPanDepth || 0} onChange={(e) => updateGlobal('stereoPanDepth', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" aria-label="Auto-Pan Depth" /></div>
                    </div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-teal-300 uppercase">Delay</h3>
                         <div><label className="flex justify-between text-xs mb-1"><span>Delay Mix</span> <span>{(currentPreset.delayMix * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.delayMix} onChange={(e) => updateGlobal('delayMix', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" aria-label="Delay Mix" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Time</span> <span>{currentPreset.delayTime.toFixed(2)}s</span></label><input type="range" min="0" max="2" step="0.05" value={currentPreset.delayTime} onChange={(e) => updateGlobal('delayTime', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" aria-label="Delay Time" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Feedback</span> <span>{(currentPreset.delayFeedback * 100).toFixed(0)}%</span></label><input type="range" min="0" max="0.9" step="0.01" value={currentPreset.delayFeedback} onChange={(e) => updateGlobal('delayFeedback', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" aria-label="Delay Feedback" /></div>
                    </div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-blue-300 uppercase">Reverb</h3>
                         <select value={currentPreset.reverbType || 'room'} onChange={(e) => handleReverbTypeChange(e.target.value as ReverbType)} className="w-full bg-slate-700 text-xs rounded p-1 border border-slate-600 capitalize" disabled={activeVoiceMode !== 'normal'} aria-label="Reverb Type">{(['room', 'hall', 'cathedral', 'plate', 'shimmer'] as ReverbType[]).map(type => (<option key={type} value={type}>{type}</option>))}</select>
                         <div><label className="flex justify-between text-xs mb-1"><span>Mix</span> <span>{(currentPreset.reverbMix * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbMix} onChange={(e) => updateGlobal('reverbMix', parseFloat(e.target.value))} className="w-full h-1 bg-blue-600 rounded appearance-none" aria-label="Reverb Mix" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Size</span> <span>{(currentPreset.reverbSize || 2.5).toFixed(1)}s</span></label><input type="range" min="0.1" max="10.0" step="0.1" value={currentPreset.reverbSize || 2.5} onChange={(e) => updateGlobal('reverbSize', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} aria-label="Reverb Size" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Damping</span> <span>{((currentPreset.reverbDamping || 0.5) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbDamping || 0.5} onChange={(e) => updateGlobal('reverbDamping', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} aria-label="Reverb Damping" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Diffusion</span> <span>{((currentPreset.reverbDiffusion || 0.8) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbDiffusion || 0.8} onChange={(e) => updateGlobal('reverbDiffusion', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} aria-label="Reverb Diffusion" /></div>
                    </div>
                </div>
            )}

            {activeTab === 'arp' && (
                <div role="tabpanel" id="panel-arp" className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Granular Arp Settings ({activeVoiceMode})</h3>
                    <div className="p-4 bg-slate-900/50 rounded border border-slate-700 space-y-4">

                        <div role="group" aria-label="Arp Direction">
                            <label className="block text-xs font-bold text-slate-400 mb-1">Direction</label>
                            <div className="flex bg-slate-800 rounded border border-slate-600 overflow-hidden">
                                {(['order', 'up', 'down', 'updown', 'random'] as ArpDirection[]).map(dir => (
                                    <button 
                                        key={dir} 
                                        onClick={() => updateArp('direction', dir)}
                                        className={`flex-1 py-1 text-[10px] uppercase font-bold ${arpConfig.direction === dir ? 'bg-red-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                                        aria-pressed={arpConfig.direction === dir}
                                    >
                                        {dir}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Granular Settings replacing redundant ones */}

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Probability</span> <span className="font-bold text-white">{(arpConfig.probability !== undefined ? arpConfig.probability * 100 : 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.05" value={arpConfig.probability !== undefined ? arpConfig.probability : 1.0} onChange={(e) => updateArp('probability', parseFloat(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none" aria-label="Step Probability" />
                            <p className="text-[9px] text-slate-500 mt-1">Chance of each step playing.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Humanize</span> <span className="font-bold text-white">{arpConfig.humanize || 0} ms</span></label>
                            <input type="range" min="0" max="100" step="5" value={arpConfig.humanize || 0} onChange={(e) => updateArp('humanize', parseInt(e.target.value))} className="w-full h-1 bg-red-500 rounded appearance-none" aria-label="Humanize Jitter" />
                            <p className="text-[9px] text-slate-500 mt-1">Random timing offset per step.</p>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Octave Range</span> <span className="font-bold text-white">{arpConfig.octaves}</span></label>
                            <input type="range" min="1" max="4" step="1" value={arpConfig.octaves} onChange={(e) => updateArp('octaves', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" aria-label="Octave Range" />
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Swing</span> <span className="font-bold text-white">{arpConfig.swing}%</span></label>
                            <input type="range" min="0" max="100" step="1" value={arpConfig.swing} onChange={(e) => updateArp('swing', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" aria-label="Swing Amount" />
                        </div>

                    </div>
                    <p className="text-[10px] text-slate-500 text-center italic">Sequence Length and Division are now controlled per-pattern in the matrix view.</p>
                </div>
            )}

            <div className="pt-4 border-t border-slate-700 mt-4">
                <p className="text-[10px] text-slate-500 text-center">Changes applied immediately</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
  SAMPLE = 'sample',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export type TuningSystem = 'ji' | 'et' | 'indian' | 'pythagorean';

export type LayoutApproach = 
  | 'lattice' | 'diamond' | 'row' | 'honeycomb' // JI specific
  | 'et_wheel' | 'et_grid' | 'et_row'           // ET specific
  | 'indian_circle' | 'indian_thaat'           // Indian specific
  | 'pyth_spiral' | 'pyth_row';                // Pythagorean specific

export type BackgroundMode = 'rainbow' | 'charcoal' | 'midnight_blue' | 'deep_maroon' | 'forest_green' | 'slate_grey' | 'image' | 'none';

export interface LimitColorMap {
  [key: number]: string;
}

export interface LimitVisualSetting {
    size: number;   // 0.1 to 2.0 (Multiplier of base size)
    opacity: number; // 0.0 to 1.0
}

export interface LimitVisualsMap {
    [key: number]: LimitVisualSetting;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface ArpeggioStep {
    nodeId: string;
    ratio: number;
    n?: number;
    d?: number;
    muted?: boolean;
    limit?: number; // For quality indication (maxPrime)
}

export type ArpDirection = 'order' | 'up' | 'down' | 'updown' | 'random';
export type ArpDivision = '1/1' | '1/2' | '1/4' | '1/8' | '1/16' | '1/32' | '1/4T' | '1/8T' | '1/16T';

export interface ArpConfig {
    direction: ArpDirection;
    division: ArpDivision;
    octaves: number; // 1 to 4
    gate: number; // 0.1 to 1.0
    swing: number; // 0 to 100
    length: number; // 1 to 32 (Pattern Length)
    probability: number; // 0.0 to 1.0 (Chance to play)
    humanize: number; // 0 to 100 (ms of jitter)
}

export interface ArpeggioDefinition {
    id: string; // "A" - "G"
    steps: ArpeggioStep[];
    isPlaying: boolean;
    config: ArpConfig;
}

export interface XYPos {
  x: number;
  y: number;
}

export interface KeyMappings {
    volumeUp: string;
    volumeDown: string;
    spatialScaleUp: string;
    spatialScaleDown: string;
    latch: string;
    panic: string;
    center: string;
    settings: string;
    synth: string;
    off: string;
    bend: string;
    addChord: string;
    increaseDepth: string;
    decreaseDepth: string;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

export interface AppSettings {
  // Global Tuning
  tuningSystem: TuningSystem;
  layoutApproach: LayoutApproach;
  activeSkin: string; // Dynamic skin ID for visual presentation

  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Origins for lattice generation (Multiple tonality centers)
  generationOrigins: GenerationOrigin[];

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Arpeggios
  arpeggios: ArpeggioDefinition[];
  arpBpm: number;

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1
  audioLatencyHint: 'interactive' | 'balanced' | 'playback'; // Buffer size control

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Brightening
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;

  // Per-Limit Visuals (Size/Opacity)
  limitVisuals: LimitVisualsMap;

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Background
  backgroundMode: BackgroundMode;
  backgroundImageData: string | null; // Base64 string for custom image
  backgroundTiling: boolean; // True = Repeat, False = No Repeat (Centered)
  backgroundYOffset: number; // Vertical offset in pixels

  // Legacy Rainbow params (still used if mode is 'rainbow')
  isRainbowModeEnabled: boolean; 
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)

  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // Behavior
  enableKeyboardShortcuts: boolean;
  keyMappings: KeyMappings;
  strumDuration: number; // seconds, 0.1 to 2.0

  // UI Relocation & Scaling
  uiUnlocked: boolean;
  uiScale: number; // 0.5 (Tiny) to 1.5 (Huge)
  uiEdgeMargin: number; // in Millimeters (1-10)
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
    arpeggioBar: XYPos;
    zoom: XYPos; // NEW
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  sampleId?: string | null; // ID for custom sample
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;
  category?: string; // New field for categorization

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Stereo & Pan
  spread?: number; // 0 to 1 (Voice Stereo Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)

  // Reverb Unit
  reverbType?: ReverbType; // Convolution Preset (Logic base)
  reverbMix: number; // 0 to 1
  reverbSize: number; // Duration in seconds (0.1 to 10.0)
  reverbDamping: number; // 0 (Bright) to 1 (Dark)
  reverbDiffusion?: number; // 0 (Grainy) to 1 (Smooth)

  // Delay Unit
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds

  // Arp Settings
  arpConfig?: ArpConfig;
}

// Slot Types
export type PlayMode = 'normal' | 'latch' | 'strum' | 'arpeggio';

export interface PresetState {
    normal: SynthPreset;
    latch: SynthPreset;
    strum: SynthPreset;
    arpeggio: SynthPreset;
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface StoredLayout {
    hash: string; // JSON hash of the settings that generated this layout
    nodes: LatticeNode[];
    lines: LatticeLine[];
    dynamicSize: number;
}

export interface StoreState {
    settings: AppSettings;
    presets: PresetState;
    userBank: SynthPreset[]; // 20 Save Slots
    layout: StoredLayout | null;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

