                  {settings.tuningSystem === 'ji' && (<div className="animate-in slide-in-from-left-2 duration-300"><div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-6"><div className="space-y-6">{renderLayoutSelector('ji')}{renderBaseFrequency()}<h3 className="font-semibold text-blue-300 border-b border-slate-700 pb-1 flex justify-between items-center"><span>Lattice Axis Depth</span><span className="text-[10px] text-blue-500 uppercase font-black">ACTIVE</span></h3><div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3"><p className="text-[10px] text-slate-500 uppercase font-bold tracking-tight">Steps from center per prime limit</p>{[3, 5, 7, 11, 13].map(limit => (<div key={limit} className="flex items-center gap-3"><span className="w-16 text-xs font-bold text-slate-400">{limit}-Limit</span><input type="range" min="0" max="6" step="1" value={settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0} onChange={(e) => handleLimitDepthChange(limit as any, parseInt(e.target.value))} className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500" /><span className="text-xs font-mono w-4 text-right text-blue-400">{settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0}</span></div>))}</div></div><div className="space-y-6"><h3 className="font-semibold text-blue-300 border-b border-slate-700 pb-1">Complexity Thresholds</h3><div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-4"><p className="text-[10px] text-slate-500 uppercase font-bold">Limit max complexity per axis</p>{[3, 5, 7, 11, 13].map(limit => (<div key={limit} className="flex flex-col gap-1"><span className="text-[10px] font-bold text-slate-400 uppercase">{limit}-Limit MAX RATIO</span><NumberInput value={settings.limitComplexities?.[limit as 3|5|7|11|13] ?? 1000} min={1} max={10000} onChange={(val) => handleLimitComplexityChange(limit as any, val)} /></div>))}</div></div></div>{renderVisualsSettings(true)}</div>)}
