ation} onChange={(e) => handleChange('strumDuration', parseFloat(e.target.value))} className="flex-grow h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer" /><span className="text-xs font-mono w-10">{settings.strumDuration.toFixed(1)}s</span></div></div></div></div><div className="space-y-6"><h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Key Bindings</h3><div className="space-y-2 max-h-80 overflow-y-auto pr-2">{renderKeyBinding('Latch All', 'latch')}{renderKeyBinding('Panic', 'panic')}{renderKeyBinding('All Notes Off', 'off')}{renderKeyBinding('Center View', 'center')}{renderKeyBinding('Toggle Pitch Bend', 'bend')}{renderKeyBinding('Open Settings', 'settings')}{renderKeyBinding('Open Synth', 'synth')}{renderKeyBinding('Store Chord', 'addChord')}{renderKeyBinding('Volume Up', 'volumeUp')}{renderKeyBinding('Volume Down', 'volumeDown')}</div></div></div>
