import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 1),
  5: new Fraction(5, 1),
  7: new Fraction(7, 1),
  11: new Fraction(11, 1),
  13: new Fraction(13, 1),
};

// Calculate the unique simplified fraction for a set of absolute coordinates
const calculateAbsoluteRatio = (coords: number[]): Fraction => {
    let n = 1;
    let d = 1;
    PRIMES.forEach((prime, idx) => {
        const val = coords[idx];
        if (val > 0) n *= Math.pow(prime, val);
        else if (val < 0) d *= Math.pow(prime, Math.abs(val));
    });
    return new Fraction(n, d);
};

// Find the octave shift required to put a ratio into the [1, 2) range
const getBaseOctaveShift = (frac: Fraction): number => {
    let ratio = frac.n / frac.d;
    // We want ratio * 2^k to be in [1, 2)
    // log2(ratio) + k is in [0, 1)
    // k is roughly -log2(ratio)
    return -Math.floor(Math.log2(ratio));
};

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: number[][] = [origin.coords];
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const currentCoords = localQueue.shift()!;
          processed++;

          // For every found coordinate set, generate its octave stack
          const absFrac = calculateAbsoluteRatio(currentCoords);
          const baseShift = getBaseOctaveShift(absFrac);

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shiftedFrac = absFrac.shiftOctave(baseShift + oct);
              const id = `${currentCoords.join(',')}:${baseShift + oct}`;

              if (!nodesMap.has(id)) {
                  const ratio = shiftedFrac.n / shiftedFrac.d;
                  const { x, y } = projectCoordinates(currentCoords, ratio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: currentCoords,
                      ratio,
                      n: shiftedFrac.n,
                      d: shiftedFrac.d,
                      label: `${shiftedFrac.n}/${shiftedFrac.d}`,
                      x, y,
                      limitTop: getMaxPrime(shiftedFrac.n),
                      limitBottom: getMaxPrime(shiftedFrac.d),
                      maxPrime: Math.max(getMaxPrime(shiftedFrac.n), getMaxPrime(shiftedFrac.d)),
                      octave: baseShift + oct
                  });
              }
          }

          // Explore Neighbors
          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...currentCoords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const nextAbsFrac = calculateAbsoluteRatio(nextCoords).normalize();
                      const compLimit = settings.limitComplexities[prime as 3|5|7|11|13];

                      if (nextAbsFrac.n <= compLimit && nextAbsFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push(nextCoords);
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          // Check across immediate octaves for harmonic connections
          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const r = target.ratio / node.ratio;
                  const pRatio = prime; // Simplified check since octaves are handled in ID
                  // If the jump is exactly a prime * 2^k
                  const test = r / pRatio;
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });

      // Octave Lines
      const up = nodesMap.get(`${node.coords.join(',')}:${node.octave + 1}`);
      if (up) {
          lines.push({
              id: `${node.id}-oct`,
              x1: node.x, y1: node.y, x2: up.x, y2: up.y,
              limit: 1, sourceId: node.id, targetId: up.id
          });
      }
  });

  return { nodes, lines };
};

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
export const BASIS_VECTORS_X = [
    100, // Prime 3
    30,  // Prime 5
    20,  // Prime 7
    -20, // Prime 11
    -30  // Prime 13
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 * All layouts are designed to be strictly relative to (0,0) as the 1/1 origin.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    const pitchHeight = Math.log2(ratio); // 1/1 = 0, 2/1 = 1, 4/1 = 2, etc.

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(pitchHeight * PITCH_SCALE);
    } 
    else if (approach === 'tonality_diamond') {
        /**
         * Tonality Diamond (Identity Space):
         * Primary plane formed by Prime 3 and 5.
         */
        const unit = spacing * 0.8;
        x = (p3 - p5) * unit;
        y = (p3 + p5) * (unit * 0.6); 

        // Offset for high primes
        x += (p7 * 0.3 + p11 * -0.2) * unit;
        y += (p7 * 0.2 + p13 * 0.3) * unit;

        // Spread octaves vertically so stacks don't overlap
        y -= (pitchHeight * (PITCH_SCALE * 0.3)); 

        x = x * (1.0 / aspectRatio);
    }
    else if (approach === 'row') {
        x = pitchHeight * 1200; 
        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);
        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.6);
        y += (p3 * 5 + p5 * 3); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.9;
        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;

        x += (p11 * 0.25) * hexUnit;
        y += (p13 * 0.25) * hexUnit;

        // Spread octaves vertically
        y -= (pitchHeight * (PITCH_SCALE * 0.3)); 

        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

