                      <div className="space-y-1">
                        <label className="block text-[10px] font-bold text-slate-500 uppercase">Button Size</label>
                        <input type="range" min="0.5" max="2.0" step="0.1" value={settings.buttonSizeScale} onChange={(e) => handleChange('buttonSizeScale', parseFloat(e.target.value))} className="w-full h-1.5 bg-slate-700 appearance-none accent-pink-500" />
