        </div>
        <div className="flex border-b border-slate-700 bg-slate-900/50 overflow-x-auto flex-shrink-0">
           {(['tonality', 'behavior', 'graphics', 'midi', 'data'] as const).map(tab => (
             <button key={tab} onClick={() => setActiveTab(tab)} className={`flex-1 py-3 px-4 font-semibold transition uppercase tracking-wider text-[10px] ${activeTab === tab ? 'text-blue-400 border-b-2 border-blue-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>{tab}</button>
           ))}
        </div>
        <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-slate-800">
            {activeTab === 'tonality' && (
