                  <div className="flex flex-col md:flex-row gap-2 items-center bg-slate-900/40 p-2 rounded-lg border border-slate-700/50">
                     {(['ji', 'et', 'indian', 'pythagorean'] as TuningSystem[]).map(sys => (
                         <button key={sys} onClick={() => handleChange('tuningSystem', sys)} className={`flex-1 px-3 py-2 text-[9px] font-bold rounded border transition-all uppercase tracking-widest ${settings.tuningSystem === sys ? 'bg-blue-600 border-blue-400 text-white' : 'bg-slate-700 border-slate-600 text-slate-400 hover:bg-slate-600'}`}>{sys}</button>
                     ))}
                  </div>
                  {settings.tuningSystem === 'ji' && (
                      <div className="animate-in slide-in-from-left-2 duration-300">
