                                              <span className="w-16 text-xs font-bold text-slate-400">{limit}-Limit</span>
                                              <input type="range" min="0" max="6" step="1" value={settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0} onChange={(e) => handleLimitDepthChange(limit as any, parseInt(e.target.value))} className="flex-grow h-1 bg-slate-700 rounded-lg appearance-none accent-blue-500" />
                                          </div>
                                      ))}
