                              </div>
                              <div className="space-y-6">
                                  <h3 className="font-semibold text-blue-300 border-b border-slate-700 pb-1">Complexity Thresholds</h3>
                                  <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-4">
                                      {[3, 5, 7, 11, 13].map(limit => (
                                          <div key={limit} className="flex flex-col gap-1">
                                              <span className="text-[10px] font-bold text-slate-400 uppercase">{limit}-Limit MAX RATIO</span>
                                              <NumberInput value={settings.limitComplexities?.[limit as 3|5|7|11|13] ?? 1000} min={1} max={10000} onChange={(val) => handleLimitComplexityChange(limit as any, val)} />
                                          </div>
                                      ))}
                                  </div>
                              </div>
                          </div>
                          {renderVisualsSettings(true)}
                      </div>
                  )}
                  {settings.tuningSystem !== 'ji' && (
                    <div className="animate-in fade-in duration-300">
                        {renderLayoutSelector(settings.tuningSystem)}
                        {renderBaseFrequency()}
                        {renderVisualsSettings(false)}
                    </div>
                  )}
              </div>
            )}
            {activeTab === 'behavior' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Audio Performance</h3>
                    <div className="bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3">
                        <label className="block text-sm font-semibold text-slate-300">Audio Latency Mode</label>
                        <div className="flex gap-2">
                            {['interactive', 'balanced', 'playback'].map(mode => (
                                <button key={mode} onClick={() => handleChange('audioLatencyHint', mode)} className={`flex-1 py-2 text-xs font-bold rounded border capitalize ${settings.audioLatencyHint === mode ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}>{mode}</button>
                            ))}
                        </div>
                    </div>
                  </div>
                  <div className="space-y-6">
                    <h3 className="font-semibold text-indigo-400 border-b border-slate-700 pb-1">Key Bindings</h3>
                    <div className="space-y-2 max-h-80 overflow-y-auto pr-2">
                      {['latch', 'panic', 'off', 'center', 'bend', 'settings', 'synth', 'addChord'].map(k => renderKeyBinding(k, k as any))}
                    </div>
                  </div>
                </div>
              </div>
            )}
            {activeTab === 'data' && (
                <div className="space-y-6">
                    <h3 className="font-semibold text-orange-400 border-b border-slate-700 pb-1">Backup & Restore</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <button onClick={exportXML} className="py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded transition">Export to XML</button>
                        <input type="file" ref={fileInputRef} className="hidden" accept=".xml" onChange={handleFileChange} />
                        <button onClick={handleImportClick} className="py-2 bg-green-600 hover:bg-green-500 text-white font-bold rounded transition">Import from XML</button>
