import { useSyncExternalStore } from 'react';
import { AppSettings, SynthPreset, PresetState, PlayMode, StoreState } from '../types';
import { DEFAULT_SETTINGS, DEFAULT_NORMAL_PRESET, DEFAULT_LATCH_PRESET, DEFAULT_STRUM_PRESET, DEFAULT_ARP_PRESET, DEFAULT_USER_BANK, DEFAULT_COLORS } from '../constants';
import { XmlService } from './XmlService';

const SETTINGS_KEY = 'prismatonal_settings_v12'; 
const PRESET_KEY = 'prismatonal_presets_v12';
const USER_BANK_KEY = 'prismatonal_user_bank_v12';

class PrismaStore {
  private state: StoreState;
  private listeners: Set<() => void> = new Set();

  constructor() {
    // Load Settings with Robust Deep Merge
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    let loadedSettings: AppSettings = DEFAULT_SETTINGS;

    if (savedSettings) {
        try {
            const parsed = JSON.parse(savedSettings);
            loadedSettings = {
                ...DEFAULT_SETTINGS,
                ...parsed,
                // Migration: Rename diamond approach
                layoutApproach: parsed.layoutApproach === 'diamond' ? 'tonality_diamond' : (parsed.layoutApproach || DEFAULT_SETTINGS.layoutApproach),
                limitDepths: { ...DEFAULT_SETTINGS.limitDepths, ...(parsed.limitDepths || {}) },
                limitComplexities: { ...DEFAULT_SETTINGS.limitComplexities, ...(parsed.limitComplexities || {}) },
                colors: { ...DEFAULT_COLORS, ...(parsed.colors || {}) }, 
                limitVisuals: { ...DEFAULT_SETTINGS.limitVisuals, ...(parsed.limitVisuals || {}) },
                uiPositions: { ...DEFAULT_SETTINGS.uiPositions, ...(parsed.uiPositions || {}) },
                arpeggios: parsed.arpeggios || DEFAULT_SETTINGS.arpeggios,
                arpBpm: parsed.arpBpm || DEFAULT_SETTINGS.arpBpm
            };
        } catch (e) {
            console.error("Failed to parse settings, reverting to defaults", e);
            loadedSettings = DEFAULT_SETTINGS;
        }
    }

    // Load Presets
    const savedPresets = localStorage.getItem(PRESET_KEY);
    let loadedPresets: PresetState;

    if (savedPresets) {
        try {
            const parsed = JSON.parse(savedPresets);
            loadedPresets = {
                normal: parsed.normal || JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
                latch: parsed.latch || JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
                strum: parsed.strum || JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
                arpeggio: parsed.arpeggio || JSON.parse(JSON.stringify(DEFAULT_ARP_PRESET))
            };
        } catch (e) {
            loadedPresets = {
                normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
                latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
                strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
                arpeggio: JSON.parse(JSON.stringify(DEFAULT_ARP_PRESET))
            };
        }
    } else {
        loadedPresets = {
            normal: JSON.parse(JSON.stringify(DEFAULT_NORMAL_PRESET)),
            latch: JSON.parse(JSON.stringify(DEFAULT_LATCH_PRESET)),
            strum: JSON.parse(JSON.stringify(DEFAULT_STRUM_PRESET)),
            arpeggio: JSON.parse(JSON.stringify(DEFAULT_ARP_PRESET))
        };
    }

    // Load User Bank
    const savedUserBank = localStorage.getItem(USER_BANK_KEY);
    let loadedUserBank: SynthPreset[] = DEFAULT_USER_BANK;
    if (savedUserBank) {
        try {
            loadedUserBank = JSON.parse(savedUserBank);
        } catch(e) {
            loadedUserBank = DEFAULT_USER_BANK;
        }
    }

    this.state = {
        settings: loadedSettings,
        presets: loadedPresets,
        userBank: loadedUserBank
    };
  }

  // --- ACTIONS ---

  updateSettings = (partial: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => {
    const current = this.state.settings;
    let next: AppSettings;

    if (typeof partial === 'function') {
      next = partial(current);
    } else {
      next = { ...current, ...partial };
    }

    if (next === current) return;

    this.state = { ...this.state, settings: next };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(next));
    this.notify();
  };

  setPreset = (mode: PlayMode, newPreset: SynthPreset) => {
    const current = this.state.presets[mode];
    if (newPreset === current) return;

    const nextPresets = { ...this.state.presets, [mode]: newPreset };
    this.state = { ...this.state, presets: nextPresets };

    localStorage.setItem(PRESET_KEY, JSON.stringify(nextPresets));
    this.notify();
  };

  saveUserPatch = (slotIndex: number, preset: SynthPreset) => {
      if (slotIndex < 0 || slotIndex >= 100) return;
      const newBank = [...this.state.userBank];
      newBank[slotIndex] = { ...preset, category: 'User' };

      this.state = { ...this.state, userBank: newBank };
      localStorage.setItem(USER_BANK_KEY, JSON.stringify(newBank));
      this.notify();
  };

  exportXML = () => {
      const xml = XmlService.exportState(this.state);
      XmlService.downloadFile(xml);
  };

  importXML = async (file: File) => {
      try {
          const partial = await XmlService.parseImport(file);
          if (partial) {
              const nextState = { ...this.state, ...partial };
              localStorage.setItem(SETTINGS_KEY, JSON.stringify(nextState.settings));
              localStorage.setItem(PRESET_KEY, JSON.stringify(nextState.presets));
              localStorage.setItem(USER_BANK_KEY, JSON.stringify(nextState.userBank));
              this.state = nextState;
              this.notify();
              return true;
          }
      } catch (e) {
          console.error(e);
          alert("Failed to import XML file.");
      }
      return false;
  };

  // --- SUBSCRIPTION ---
  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getSnapshot = () => {
    return this.state;
  };

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const store = new PrismaStore();

export function useStore() {
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot);

  return {
    settings: state.settings,
    presets: state.presets, 
    userBank: state.userBank,
    updateSettings: store.updateSettings,
    setPreset: store.setPreset,
    saveUserPatch: store.saveUserPatch,
    exportXML: store.exportXML,
    importXML: store.importXML
  };
}

import { LatticeNode, LatticeLine, AppSettings, GenerationOrigin } from '../types';
import { projectCoordinates } from './ProjectionService';

// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];

// Calculate the unique simplified fraction for a set of absolute coordinates relative to 1/1
const calculateAbsoluteRatio = (coords: number[]): Fraction => {
    let n = 1;
    let d = 1;
    PRIMES.forEach((prime, idx) => {
        const val = coords[idx];
        if (val > 0) n *= Math.pow(prime, val);
        else if (val < 0) d *= Math.pow(prime, Math.abs(val));
    });
    return new Fraction(n, d);
};

// Find the octave shift required to put a ratio into the [1, 2) range
const getBaseOctaveShift = (frac: Fraction): number => {
    let ratio = frac.n / frac.d;
    return -Math.floor(Math.log2(ratio));
};

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: number[][] = [origin.coords];
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const currentCoords = localQueue.shift()!;
          processed++;

          // For every found coordinate set, generate its octave stack
          const absFrac = calculateAbsoluteRatio(currentCoords);
          const baseShift = getBaseOctaveShift(absFrac);

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shiftedFrac = absFrac.shiftOctave(baseShift + oct);
              const id = `${currentCoords.join(',')}:${baseShift + oct}`;

              if (!nodesMap.has(id)) {
                  const ratio = shiftedFrac.n / shiftedFrac.d;
                  const { x, y } = projectCoordinates(currentCoords, ratio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: currentCoords,
                      ratio,
                      n: shiftedFrac.n,
                      d: shiftedFrac.d,
                      label: `${shiftedFrac.n}/${shiftedFrac.d}`,
                      x, y,
                      limitTop: getMaxPrime(shiftedFrac.n),
                      limitBottom: getMaxPrime(shiftedFrac.d),
                      maxPrime: Math.max(getMaxPrime(shiftedFrac.n), getMaxPrime(shiftedFrac.d)),
                      octave: baseShift + oct
                  });
              }
          }

          // Explore Neighbors
          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...currentCoords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const nextAbsFrac = calculateAbsoluteRatio(nextCoords).normalize();
                      const compLimit = settings.limitComplexities[prime as 3|5|7|11|13];

                      if (nextAbsFrac.n <= compLimit && nextAbsFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push(nextCoords);
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const r = target.ratio / node.ratio;
                  const test = r / prime;
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });

      const up = nodesMap.get(`${node.coords.join(',')}:${node.octave + 1}`);
      if (up) {
          lines.push({
              id: `${node.id}-oct`,
              x1: node.x, y1: node.y, x2: up.x, y2: up.y,
              limit: 1, sourceId: node.id, targetId: up.id
          });
      }
  });

  return { nodes, lines };
};

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
export const BASIS_VECTORS_X = [
    100, // Prime 3
    30,  // Prime 5
    20,  // Prime 7
    -20, // Prime 11
    -30  // Prime 13
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 * All layouts are designed to be strictly relative to (0,0) as the 1/1 origin.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    const pitchHeight = Math.log2(ratio); // 1/1 = 0, 2/1 = 1, 4/1 = 2, etc.

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(pitchHeight * PITCH_SCALE);
    } 
    else if (approach === 'tonality_diamond') {
        /**
         * Tonality Diamond (Identity Space):
         * Primary plane formed by Prime 3 and 5.
         */
        const unit = spacing * 0.8;
        x = (p3 - p5) * unit;
        y = (p3 + p5) * (unit * 0.6); 

        // Offset for high primes
        x += (p7 * 0.3 + p11 * -0.2) * unit;
        y += (p7 * 0.2 + p13 * 0.3) * unit;

        // Spread octaves vertically so stacks don't overlap
        y -= (pitchHeight * (PITCH_SCALE * 0.3)); 

        x = x * (1.0 / aspectRatio);
    }
    else if (approach === 'row') {
        x = pitchHeight * 1200; 
        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);
        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.6);
        y += (p3 * 5 + p5 * 3); 
    }
    else if (approach === 'honeycomb') {
        const hexUnit = spacing * 0.9;
        x = (p3 + p5 * 0.5 + p7 * -0.5) * hexUnit;
        y = (p5 * 0.866 + p7 * 0.866) * hexUnit;

        x += (p11 * 0.25) * hexUnit;
        y += (p13 * 0.25) * hexUnit;

        // Spread octaves vertically
        y -= (pitchHeight * (PITCH_SCALE * 0.3)); 

        x = x * (1.0 / aspectRatio);
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

