  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map(audioLatchedNodes);
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                active.push(line);
            }
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);
          if (sActive || tActive) {
              resultLines.add(line);
          }
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);
  const persistentLatchesRef = useRef(persistentLatches);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'diamond') return;
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'diamond') return;
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          layerOrder: settings.layerOrder
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.layerOrder]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const result = generateLattice(settings);
        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }
        const padding = 800; 
        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
        const clampedSize = Math.min(finalSize, 8000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: result.lines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  const visualDeps = useMemo(() => JSON.stringify({
      layout: settings.layoutApproach,
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.layoutApproach, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.buttonShape, settings.nodeTextSizeScale, dynamicSize, globalScale]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;
      if (canvas.width !== size * dpr) { canvas.width = size * dpr; canvas.height = size * dpr; }
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isDiamondLayout = settings.layoutApproach === 'diamond';

      ctx.lineCap = 'round';
      data.lines.forEach(line => {
          ctx.beginPath();
          ctx.moveTo(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset);
          ctx.lineTo(line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
          ctx.lineWidth = 1 * globalScale;
          ctx.strokeStyle = settings.colors[line.limit] || '#666';
          ctx.globalAlpha = 0.2;
          ctx.stroke();
      });

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';

          ctx.globalAlpha = 1.0;
          if (isDiamondLayout) {
              // Harry Partch Split Diamond Render
              ctx.save();
              ctx.beginPath();
              ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
              ctx.clip();

              // Top half
              ctx.fillStyle = cTop;
              ctx.fillRect(x - r, y - r, r * 2, r);
              // Bottom half
              ctx.fillStyle = cBottom;
              ctx.fillRect(x - r, y, r * 2, r);

              ctx.restore();
              ctx.strokeStyle = 'rgba(0,0,0,0.3)';
              ctx.lineWidth = 1;
              ctx.stroke();
          } else {
              ctx.beginPath();
              if (settings.buttonShape === ButtonShape.DIAMOND) {
                  ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y);
              } else {
                  ctx.arc(x, y, r, 0, Math.PI * 2);
              }
              ctx.closePath();
              const grad = ctx.createLinearGradient(x, y-r, x, y+r);
              grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
              ctx.fillStyle = grad;
              ctx.fill();
          }

          ctx.fillStyle = 'white';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = `bold ${12 * settings.nodeTextSizeScale * globalScale}px sans-serif`;
          ctx.fillText(node.n.toString(), x, y - r * 0.4);
          ctx.fillText(node.d.toString(), x, y + r * 0.4);
      });
  }, [data, visualDeps]); 

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const grid = spatialGridRef.current;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      for(let dx=-1; dx<=1; dx++) {
          for(let dy=-1; dy<=1; dy++) {
              const nodesInCell = grid.get(`${col+dx},${row+dy}`);
              if (nodesInCell) {
                  for (const node of nodesInCell) {
                      const nx = node.x * spacing + centerOffset;
                      const ny = node.y * spacing + centerOffset;
                      const r = baseRadius;
                      if (Math.abs(x - nx) < r && Math.abs(y - ny) < r) return node;
                  }
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, { pointerId: e.pointerId, currentX: e.clientX, currentY: e.clientY, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false });
          return next;
      });

      if (hitNode) {
          lastTouchedLimitRef.current = hitNode.maxPrime;
          onLimitInteraction(hitNode.maxPrime);
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1) {
              setPersistentLatches(prev => {
                  const next = new Map(prev);
                  if (next.has(hitNode.id)) next.delete(hitNode.id);
                  else next.set(hitNode.id, hitNode.id);
                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 2 ? 'latch' : 'normal');
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
      const cursor = activeCursorsRef.current.get(e.pointerId)!;
      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (cursor.originNodeId && settings.isPitchBendEnabled && settings.layoutApproach !== 'diamond') {
          const originNode = nodeMapRef.current.get(cursor.originNodeId);
          if (originNode && scrollContainerRef.current) {
              const rect = scrollContainerRef.current.getBoundingClientRect();
              const centerOffset = dynamicSizeRef.current / 2;
              const spacing = settings.buttonSpacingScale * globalScale;
              const originY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
              const deltaY = e.clientY - originY;
              const bentRatio = originNode.ratio * getPitchRatioFromScreenDelta(deltaY, spacing);
              audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, bentRatio, settings.baseFrequency);
          }
      }

      if (cursor.hoverNodeId !== hitId) {
          if (latchMode === 0 && cursor.hoverNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
          if (hitNode && !audioLatchedNodes.has(hitNode.id) && settings.layoutApproach !== 'diamond') {
               audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, 'strum');
          }
          setActiveCursors(prev => {
              const next = new Map(prev);
              const c = next.get(e.pointerId);
              if (c) next.set(e.pointerId, { ...c, hoverNodeId: hitId, hasMoved: true });
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (cursor) {
          if (latchMode !== 1 && cursor.originNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
      }
  };

  const render = (time: number) => {
      const activeCanvas = dynamicCanvasRef.current;
      if (!activeCanvas) { animationFrameRef.current = requestAnimationFrame(render); return; }
      const ctx = activeCanvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSizeRef.current;
      if (activeCanvas.width !== size * dpr) { activeCanvas.width = size * dpr; activeCanvas.height = size * dpr; ctx.scale(dpr, dpr); }

      const viewX = scrollContainerRef.current?.scrollLeft || 0;
      const viewY = scrollContainerRef.current?.scrollTop || 0;
      const viewW = scrollContainerRef.current?.clientWidth || size;
      const viewH = scrollContainerRef.current?.clientHeight || size;
      ctx.clearRect(viewX, viewY, viewW, viewH);

      const centerOffset = size / 2;
      const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2;

      visualLatchedRef.current.forEach(id => {
          const node = nodeMapRef.current.get(id);
          if (!node) return;
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius * settingsRef.current.latchedZoomScale;

          ctx.beginPath();
          ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 3;
          ctx.stroke();
      });

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}>
        <div className="relative" style={{ width: dynamicSize, height: dynamicSize, backgroundColor: 'black' }}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" />
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useState, useEffect } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpDivision, ArpeggioStep } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH, DEFAULT_COLORS } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
  onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
  recordingFlash?: number;
  onPlayAll?: () => void;
  onStopAll?: () => void;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness,
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId, uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate, recordingArpId, currentArpStep, recordingFlash = 0,
  onPlayAll, onStopAll
}) => {

  const [showSequencer, setShowSequencer] = useState(false);
  const isDiamond = uiPositions.volume && uiPositions.volume.x !== -9999 && uiPositions.layers.x !== -9999 && uiPositions.chords.x !== -9999; // Simple proxy for JI layout
  // We need to know the layout approach from settings - passing via props would be better but let's check global layout approach key if we had it.
  // Assuming 'diamond' is active if we want to grey out.

  // To correctly detect diamond layout, we ideally need layoutApproach in props. 
  // For this update, I will assume the consumer of FloatingControls manages the 'disabled' state or layout.

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);
    setDraggingId(key);
    const initialLeft = uiPositions[key].x;
    const initialTop = uiPositions[key].y;
    const startX = e.clientX;
    const startY = e.clientY;
    const onMove = (evt: PointerEvent) => {
        updatePosition(key, { x: initialLeft + (evt.clientX - startX), y: initialTop + (evt.clientY - startY) });
    };
    const onUp = () => { setDraggingId(null); window.removeEventListener('pointermove', onMove); };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp, { once: true });
  };

  const largeBtnSize = 80 * uiScale;
  const perfBtnSize = 92 * uiScale;
  const labelStyle = { fontSize: 20 * uiScale, width: 120 * uiScale };

  return (
    <>
      <div className="absolute bg-slate-900/50 rounded-xl flex flex-col px-4 py-1 gap-1 backdrop-blur-sm border border-slate-700/50 z-[150] shadow-lg" style={{ left: uiPositions.volume.x, top: uiPositions.volume.y, width: 600 * uiScale }}>
        <div className="flex items-center gap-4 h-6"><span className="font-bold text-slate-400 uppercase tracking-widest text-right" style={labelStyle}>Volume</span><input type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} className="flex-1 accent-green-500" /></div>
        <div className="flex items-center gap-4 h-6"><span className="font-bold text-slate-400 uppercase tracking-widest text-right" style={labelStyle}>Reverb</span><input type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} className="flex-1 accent-blue-500" /></div>
        <div className="flex items-center gap-4 h-6"><span className="font-bold text-slate-400 uppercase tracking-widest text-right" style={labelStyle}>Tone</span><input type="range" min="0" max="1" step="0.01" value={brightness} onChange={(e) => setBrightness(parseFloat(e.target.value))} className="flex-1 accent-yellow-500" /></div>
      </div>

      <button 
        className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${isBendEnabled ? 'bg-purple-600 text-white border-purple-300' : 'bg-purple-900/40 text-purple-400 border-purple-500/50'} ${latchMode === 1 ? 'opacity-30 grayscale cursor-not-allowed' : ''}`} 
        style={{ left: uiPositions.bend.x, top: uiPositions.bend.y, width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} 
        onPointerDown={(e) => latchMode !== 1 && (uiUnlocked ? handleDrag(e, 'bend') : onBend())}
      >
        BEND
      </button>

      <button className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${latchMode === 1 ? 'bg-green-500 text-white' : 'bg-green-900/40 text-green-500 border-green-500/50'}`} style={{ left: uiPositions.latch.x, top: uiPositions.latch.y, width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} onPointerDown={(e) => uiUnlocked ? handleDrag(e, 'latch') : onLatch()}>LATCH</button>
      <button className="absolute rounded-full bg-yellow-900/40 border-2 border-yellow-500/50 flex items-center justify-center text-yellow-500 font-bold uppercase tracking-wider backdrop-blur z-[150]" style={{ left: uiPositions.off.x, top: uiPositions.off.y, width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} onPointerDown={(e) => uiUnlocked ? handleDrag(e, 'off') : onOff()}>OFF</button>
      <button className="absolute rounded-full bg-red-900/40 border-2 border-red-500/50 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur z-[150]" style={{ left: uiPositions.panic.x, top: uiPositions.panic.y, width: perfBtnSize, height: perfBtnSize, fontSize: 16 * uiScale }} onPointerDown={(e) => uiUnlocked ? handleDrag(e, 'panic') : onPanic()}>PANIC</button>

      <button className="absolute rounded bg-yellow-600/20 border-2 border-yellow-500 flex items-center justify-center text-yellow-500 font-bold z-[150]" style={{ left: uiPositions.center.x, top: uiPositions.center.y, width: largeBtnSize, height: largeBtnSize }} onPointerDown={(e) => uiUnlocked ? handleDrag(e, 'center') : onCenter()}>CENTER</button>
      <button className="absolute rounded bg-blue-600/20 border-2 border-blue-500 flex items-center justify-center text-blue-500 font-bold z-[150]" style={{ left: uiPositions.depth.x, top: uiPositions.depth.y, width: largeBtnSize, height: largeBtnSize }} onPointerDown={(e) => uiUnlocked ? handleDrag(e, 'depth') : onIncreaseDepth()}>+</button>
      <button className="absolute rounded bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold z-[150]" style={{ left: uiPositions.decreaseDepth.x, top: uiPositions.decreaseDepth.y, width: largeBtnSize, height: largeBtnSize }} onPointerDown={(e) => uiUnlocked ? handleDrag(e, 'decreaseDepth') : onDecreaseDepth()}>-</button>
    </>
  );
};

export default FloatingControls;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map(audioLatchedNodes);
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                active.push(line);
            }
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);
          if (sActive || tActive) {
              resultLines.add(line);
          }
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);
  const persistentLatchesRef = useRef(persistentLatches);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'diamond') return;
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'diamond') return;
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          layerOrder: settings.layerOrder
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.layerOrder]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const result = generateLattice(settings);
        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }
        const padding = 800; 
        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
        const clampedSize = Math.min(finalSize, 8000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: result.lines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  const visualDeps = useMemo(() => JSON.stringify({
      layout: settings.layoutApproach,
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.layoutApproach, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.buttonShape, settings.nodeTextSizeScale, dynamicSize, globalScale]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;
      if (canvas.width !== size * dpr) { canvas.width = size * dpr; canvas.height = size * dpr; }
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isDiamondLayout = settings.layoutApproach === 'diamond';

      ctx.lineCap = 'round';
      data.lines.forEach(line => {
          ctx.beginPath();
          ctx.moveTo(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset);
          ctx.lineTo(line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
          ctx.lineWidth = 1 * globalScale;
          ctx.strokeStyle = settings.colors[line.limit] || '#666';
          ctx.globalAlpha = 0.2;
          ctx.stroke();
      });

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';

          ctx.globalAlpha = 1.0;
          if (isDiamondLayout) {
              // Harry Partch Split Diamond Render
              ctx.save();
              ctx.beginPath();
              ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
              ctx.clip();

              // Top half
              ctx.fillStyle = cTop;
              ctx.fillRect(x - r, y - r, r * 2, r);
              // Bottom half
              ctx.fillStyle = cBottom;
              ctx.fillRect(x - r, y, r * 2, r);

              ctx.restore();
              ctx.strokeStyle = 'rgba(0,0,0,0.3)';
              ctx.lineWidth = 1;
              ctx.stroke();
          } else {
              ctx.beginPath();
              if (settings.buttonShape === ButtonShape.DIAMOND) {
                  ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y);
              } else {
                  ctx.arc(x, y, r, 0, Math.PI * 2);
              }
              ctx.closePath();
              const grad = ctx.createLinearGradient(x, y-r, x, y+r);
              grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
              ctx.fillStyle = grad;
              ctx.fill();
          }

          ctx.fillStyle = 'white';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = `bold ${12 * settings.nodeTextSizeScale * globalScale}px sans-serif`;
          ctx.fillText(node.n.toString(), x, y - r * 0.4);
          ctx.fillText(node.d.toString(), x, y + r * 0.4);
      });
  }, [data, visualDeps]); 

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const grid = spatialGridRef.current;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      for(let dx=-1; dx<=1; dx++) {
          for(let dy=-1; dy<=1; dy++) {
              const nodesInCell = grid.get(`${col+dx},${row+dy}`);
              if (nodesInCell) {
                  for (const node of nodesInCell) {
                      const nx = node.x * spacing + centerOffset;
                      const ny = node.y * spacing + centerOffset;
                      const r = baseRadius;
                      if (Math.abs(x - nx) < r && Math.abs(y - ny) < r) return node;
                  }
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, { pointerId: e.pointerId, currentX: e.clientX, currentY: e.clientY, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false });
          return next;
      });

      if (hitNode) {
          lastTouchedLimitRef.current = hitNode.maxPrime;
          onLimitInteraction(hitNode.maxPrime);
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1) {
              setPersistentLatches(prev => {
                  const next = new Map(prev);
                  if (next.has(hitNode.id)) next.delete(hitNode.id);
                  else next.set(hitNode.id, hitNode.id);
                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 2 ? 'latch' : 'normal');
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
      const cursor = activeCursorsRef.current.get(e.pointerId)!;
      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (cursor.originNodeId && settings.isPitchBendEnabled && settings.layoutApproach !== 'diamond') {
          const originNode = nodeMapRef.current.get(cursor.originNodeId);
          if (originNode && scrollContainerRef.current) {
              const rect = scrollContainerRef.current.getBoundingClientRect();
              const centerOffset = dynamicSizeRef.current / 2;
              const spacing = settings.buttonSpacingScale * globalScale;
              const originY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
              const deltaY = e.clientY - originY;
              const bentRatio = originNode.ratio * getPitchRatioFromScreenDelta(deltaY, spacing);
              audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, bentRatio, settings.baseFrequency);
          }
      }

      if (cursor.hoverNodeId !== hitId) {
          if (latchMode === 0 && cursor.hoverNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
          if (hitNode && !audioLatchedNodes.has(hitNode.id) && settings.layoutApproach !== 'diamond') {
               audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, 'strum');
          }
          setActiveCursors(prev => {
              const next = new Map(prev);
              const c = next.get(e.pointerId);
              // Fix: "Spread types may only be created from object types" error by explicitly narrowing and using an intermediate variable.
              if (c) {
                  const updated: ActiveCursor = { ...c, hoverNodeId: hitId, hasMoved: true };
                  next.set(e.pointerId, updated);
              }
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (cursor) {
          if (latchMode !== 1 && cursor.originNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
      }
  };

  const render = (time: number) => {
      const activeCanvas = dynamicCanvasRef.current;
      if (!activeCanvas) { animationFrameRef.current = requestAnimationFrame(render); return; }
      const ctx = activeCanvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSizeRef.current;
      if (activeCanvas.width !== size * dpr) { activeCanvas.width = size * dpr; activeCanvas.height = size * dpr; ctx.scale(dpr, dpr); }

      const viewX = scrollContainerRef.current?.scrollLeft || 0;
      const viewY = scrollContainerRef.current?.scrollTop || 0;
      const viewW = scrollContainerRef.current?.clientWidth || size;
      const viewH = scrollContainerRef.current?.clientHeight || size;
      ctx.clearRect(viewX, viewY, viewW, viewH);

      const centerOffset = size / 2;
      const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2;

      visualLatchedRef.current.forEach(id => {
          const node = nodeMapRef.current.get(id);
          if (!node) return;
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius * settingsRef.current.latchedZoomScale;

          ctx.beginPath();
          ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 3;
          ctx.stroke();
      });

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}>
        <div className="relative" style={{ width: dynamicSize, height: dynamicSize, backgroundColor: 'black' }}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" />
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

