// --- Math Helpers ---

const gcd = (a: number, b: number): number => {
  let x = Math.abs(Math.round(a));
  let y = Math.abs(Math.round(b));
  while (y !== 0) {
    let t = y;
    y = x % y;
    x = t;
  }
  return x;
};

const getMaxPrime = (n: number): number => {
  let temp = Math.abs(Math.round(n));
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;

  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) {
      maxP = d;
      temp /= d;
    }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

class Fraction {
  n: number;
  d: number;

  constructor(n: number, d: number) {
    const common = gcd(n, d);
    this.n = n / common;
    this.d = d / common;
  }

  mul(other: Fraction): Fraction {
    return new Fraction(this.n * other.n, this.d * other.d);
  }

  normalize(): Fraction {
    let nn = this.n;
    let dd = this.d;
    while (nn >= 2 * dd) dd *= 2;
    while (nn < dd) nn *= 2;
    return new Fraction(nn, dd);
  }

  shiftOctave(octave: number): Fraction {
    let nn = this.n;
    let dd = this.d;
    if (octave > 0) nn *= Math.pow(2, octave);
    else if (octave < 0) dd *= Math.pow(2, Math.abs(octave));
    return new Fraction(nn, dd);
  }
}

const PRIMES = [3, 5, 7, 11, 13];
const PRIME_RATIOS = {
  3: new Fraction(3, 2),
  5: new Fraction(5, 4),
  7: new Fraction(7, 4),
  11: new Fraction(11, 8),
  13: new Fraction(13, 8),
};

const ODD_IDENTITIES = [1, 3, 5, 7, 11, 13];

// --- Generation ---

export const generateLattice = (
    settings: AppSettings, 
    generationOrigins: GenerationOrigin[] = [{coords: [0,0,0,0,0], octave: 0}]
): { nodes: LatticeNode[], lines: LatticeLine[] } => {

  if (settings.layoutApproach === 'tonality_diamond') {
      return generatePartchDiamond(settings);
  }

  const nodesMap = new Map<string, LatticeNode>();
  const OCTAVE_RANGE = 2; 

  generationOrigins.forEach(origin => {
      const localQueue: { coords: number[], ratio: Fraction }[] = [];

      // Calculate start ratio for origin coords
      let originFrac = new Fraction(1, 1);
      PRIMES.forEach((p, idx) => {
          const val = origin.coords[idx];
          const pRat = PRIME_RATIOS[p as 3|5|7|11|13];
          for(let i=0; i<Math.abs(val); i++) {
              originFrac = val > 0 ? originFrac.mul(pRat).normalize() : originFrac.mul(new Fraction(pRat.d, pRat.n)).normalize();
          }
      });

      localQueue.push({ coords: origin.coords, ratio: originFrac });
      const visitedLocal = new Set<string>([origin.coords.join(',')]);

      const MAX_LOCAL_NODES = 800;
      let processed = 0;

      while (localQueue.length > 0 && processed < MAX_LOCAL_NODES) {
          const current = localQueue.shift()!;
          processed++;

          for (let oct = origin.octave - OCTAVE_RANGE; oct <= origin.octave + OCTAVE_RANGE; oct++) {
              const shifted = current.ratio.shiftOctave(oct);
              const id = `${current.coords.join(',')}:${oct}`;

              if (!nodesMap.has(id)) {
                  const absoluteRatio = shifted.n / shifted.d;
                  const { x, y } = projectCoordinates(current.coords, absoluteRatio, settings.latticeAspectRatio, settings.layoutApproach);

                  nodesMap.set(id, {
                      id,
                      coords: current.coords,
                      ratio: absoluteRatio,
                      n: shifted.n,
                      d: shifted.d,
                      label: `${shifted.n}/${shifted.d}`,
                      x, y,
                      limitTop: getMaxPrime(shifted.n),
                      limitBottom: getMaxPrime(shifted.d),
                      maxPrime: Math.max(getMaxPrime(shifted.n), getMaxPrime(shifted.d)),
                      octave: oct
                  });
              }
          }

          PRIMES.forEach((prime, idx) => {
              const depthLimit = settings.limitDepths[prime as 3|5|7|11|13];
              if (depthLimit <= 0) return;

              [1, -1].forEach(dir => {
                  const nextCoords = [...current.coords];
                  nextCoords[idx] += dir;

                  if (Math.abs(nextCoords[idx] - origin.coords[idx]) > depthLimit) return;

                  const key = nextCoords.join(',');
                  if (!visitedLocal.has(key)) {
                      const pRat = PRIME_RATIOS[prime as 3|5|7|11|13];
                      const nextFrac = dir === 1 ? current.ratio.mul(pRat).normalize() : current.ratio.mul(new Fraction(pRat.d, pRat.n)).normalize();

                      const compLimit = settings.limitComplexities[prime as 3|5|7|11|13];
                      if (nextFrac.n <= compLimit && nextFrac.d <= compLimit) {
                          visitedLocal.add(key);
                          localQueue.push({ coords: nextCoords, ratio: nextFrac });
                      }
                  }
              });
          });
      }
  });

  const nodes = Array.from(nodesMap.values());
  const lines: LatticeLine[] = [];

  nodes.forEach(node => {
      PRIMES.forEach((prime, idx) => {
          const targetCoords = [...node.coords];
          targetCoords[idx] += 1;
          const coordKey = targetCoords.join(',');

          for (let o = node.octave - 1; o <= node.octave + 1; o++) {
              const target = nodesMap.get(`${coordKey}:${o}`);
              if (target) {
                  const ratio = target.ratio / node.ratio;
                  const test = ratio / (PRIME_RATIOS[prime as 3|5|7|11|13].n / PRIME_RATIOS[prime as 3|5|7|11|13].d);
                  if (Math.abs(Math.log2(test) - Math.round(Math.log2(test))) < 0.001) {
                      lines.push({
                          id: `${node.id}-${target.id}`,
                          x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                          limit: prime, sourceId: node.id, targetId: target.id
                      });
                  }
              }
          }
      });
  });

  return { nodes, lines };
};

/**
 * Generates a Harry Partch-style Tonality Diamond
 */
const generatePartchDiamond = (settings: AppSettings): { nodes: LatticeNode[], lines: LatticeLine[] } => {
    const nodes: LatticeNode[] = [];
    const lines: LatticeLine[] = [];

    // Find highest enabled odd limit
    let maxEnabledLimit = 1;
    settings.layerOrder.forEach(l => {
        if (!settings.hiddenLimits.includes(l) && ODD_IDENTITIES.includes(l)) {
            if (l > maxEnabledLimit) maxEnabledLimit = l;
        }
    });

    const activeIdentities = ODD_IDENTITIES.filter(id => id <= maxEnabledLimit);
    const N = activeIdentities.length;
    const spacing = 140; // Base spacing for discrete grid

    for (let o = 0; o < N; o++) {
        for (let u = 0; u < N; u++) {
            const idOton = activeIdentities[o];
            const idUton = activeIdentities[u];

            const frac = new Fraction(idOton, idUton).normalize();
            const ratio = frac.n / frac.d;

            // Standard Partch Diamond Layout Rotation
            // x increases with identity index (midline)
            // y: u increases -> downward, o increases -> upward
            const x = (o + u) - (N - 1);
            const y = (u - o);

            const id = `diamond-${o}-${u}`;

            nodes.push({
                id,
                coords: [o, u, 0, 0, 0], // Discrete indices
                ratio,
                n: frac.n,
                d: frac.d,
                label: `${frac.n}/${frac.d}`,
                x: x * spacing,
                y: y * spacing * 0.866, // Hexagonal-ish height factor
                limitTop: getMaxPrime(frac.n),
                limitBottom: getMaxPrime(frac.d),
                maxPrime: Math.max(getMaxPrime(frac.n), getMaxPrime(frac.d)),
                octave: 0
            });
        }
    }

    // Connect neighbors in the diamond grid
    nodes.forEach((node, i) => {
        const [o, u] = node.coords;
        nodes.forEach((target, j) => {
            if (i === j) return;
            const [to, tu] = target.coords;
            const distO = Math.abs(o - to);
            const distU = Math.abs(u - tu);
            if ((distO === 1 && distU === 0) || (distO === 0 && distU === 1)) {
                lines.push({
                    id: `${node.id}-${target.id}`,
                    x1: node.x, y1: node.y, x2: target.x, y2: target.y,
                    limit: Math.max(node.maxPrime, target.maxPrime),
                    sourceId: node.id, targetId: target.id
                });
            }
        });
    });

    return { nodes, lines };
};

import { AppSettings, LayoutApproach } from '../types';

export const PITCH_SCALE = 200; // Pixels per octave (Base Scale)

// Basis vectors for the lattice projection (X-axis contribution per prime index)
export const BASIS_VECTORS_X = [
    100, // Prime 3
    30,  // Prime 5
    20,  // Prime 7
    -20, // Prime 11
    -30  // Prime 13
];

/**
 * Projects harmonic coordinates into 2D screen space based on selected layout approach.
 */
export const projectCoordinates = (
    coords: number[], 
    ratio: number, 
    aspectRatio: number,
    approach: LayoutApproach = 'lattice'
): { x: number, y: number } => {
    let x = 0;
    let y = 0;

    const spacing = 140; 
    const p3 = coords[0] || 0;
    const p5 = coords[1] || 0;
    const p7 = coords[2] || 0;
    const p11 = coords[3] || 0;
    const p13 = coords[4] || 0;

    if (approach === 'lattice') {
        for(let i = 0; i < coords.length; i++) {
            if (i < BASIS_VECTORS_X.length) {
                x += coords[i] * BASIS_VECTORS_X[i];
            }
        }
        x = x * (1.0 / aspectRatio);
        y = -(Math.log2(ratio) * PITCH_SCALE);
    } 
    else if (approach === 'tonality_diamond') {
        /**
         * Partch Tonality Diamond (Discrete Identity Space):
         * Direct coordinate setting in LatticeService handles this layout.
         */
        x = coords[0] * spacing;
        y = coords[1] * spacing;
    }
    else if (approach === 'et_row' || approach === 'pyth_row') {
        x = Math.log2(ratio) * 1200; 
        const maxP = Math.max(1, ...coords.map((c, i) => c !== 0 ? [3,5,7,11,13][i] : 1));
        const limitIndex = [1, 3, 5, 7, 11, 13].indexOf(maxP);
        const dir = limitIndex % 2 === 0 ? 1 : -1;
        y = dir * (limitIndex * spacing * 0.6);
        y += (p3 * 5 + p5 * 3); 
    }

    return { x, y };
};

export const getPitchRatioFromScreenDelta = (
    deltaY: number, 
    spacingScale: number
): number => {
    const effectiveScale = PITCH_SCALE * spacingScale;
    return Math.pow(2, -deltaY / effectiveScale);
};

export const getRainbowPeriod = (spacingScale: number): number => {
    return PITCH_SCALE * spacingScale;
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map(audioLatchedNodes);
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                active.push(line);
            }
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);
          if (sActive || tActive) {
              resultLines.add(line);
          }
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);
  const persistentLatchesRef = useRef(persistentLatches);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'tonality_diamond') return;
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'tonality_diamond') return;
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          layerOrder: settings.layerOrder
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.layerOrder]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const result = generateLattice(settings);
        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }
        const padding = 800; 
        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
        const clampedSize = Math.min(finalSize, 8000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: result.lines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  const visualDeps = useMemo(() => JSON.stringify({
      layout: settings.layoutApproach,
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.layoutApproach, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.buttonShape, settings.nodeTextSizeScale, dynamicSize, globalScale]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;
      if (canvas.width !== size * dpr) { canvas.width = size * dpr; canvas.height = size * dpr; }
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isPartchDiamond = settings.layoutApproach === 'tonality_diamond';

      ctx.lineCap = 'round';
      data.lines.forEach(line => {
          ctx.beginPath();
          ctx.moveTo(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset);
          ctx.lineTo(line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
          ctx.lineWidth = 1 * globalScale;
          ctx.strokeStyle = settings.colors[line.limit] || '#666';
          ctx.globalAlpha = 0.25;
          ctx.stroke();
      });

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';

          ctx.globalAlpha = 1.0;
          if (isPartchDiamond) {
              // Harry Partch Split Diamond Render
              ctx.save();
              ctx.beginPath();
              ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
              ctx.clip();

              // Top half
              ctx.fillStyle = cTop;
              ctx.fillRect(x - r, y - r, r * 2, r);
              // Bottom half
              ctx.fillStyle = cBottom;
              ctx.fillRect(x - r, y, r * 2, r);

              ctx.restore();
              ctx.strokeStyle = 'rgba(255,255,255,0.4)';
              ctx.lineWidth = 1 * globalScale;
              ctx.stroke();
          } else {
              ctx.beginPath();
              if (settings.buttonShape === ButtonShape.DIAMOND) {
                  ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y);
              } else {
                  ctx.arc(x, y, r, 0, Math.PI * 2);
              }
              ctx.closePath();
              const grad = ctx.createLinearGradient(x, y-r, x, y+r);
              grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
              ctx.fillStyle = grad;
              ctx.fill();
              ctx.strokeStyle = 'rgba(255,255,255,0.2)';
              ctx.stroke();
          }

          ctx.fillStyle = 'white';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = `bold ${Math.max(10, 12 * settings.nodeTextSizeScale * globalScale)}px sans-serif`;
          ctx.fillText(node.n.toString(), x, y - r * 0.4);
          ctx.fillText(node.d.toString(), x, y + r * 0.4);
      });
  }, [data, visualDeps]); 

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const grid = spatialGridRef.current;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      for(let dx=-1; dx<=1; dx++) {
          for(let dy=-1; dy<=1; dy++) {
              const nodesInCell = grid.get(`${col+dx},${row+dy}`);
              if (nodesInCell) {
                  for (const node of nodesInCell) {
                      const nx = node.x * spacing + centerOffset;
                      const ny = node.y * spacing + centerOffset;
                      const r = baseRadius;
                      if (Math.abs(x - nx) < r && Math.abs(y - ny) < r) return node;
                  }
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, { pointerId: e.pointerId, currentX: e.clientX, currentY: e.clientY, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false });
          return next;
      });

      if (hitNode) {
          lastTouchedLimitRef.current = hitNode.maxPrime;
          onLimitInteraction(hitNode.maxPrime);
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1) {
              setPersistentLatches(prev => {
                  const next = new Map(prev);
                  if (next.has(hitNode.id)) next.delete(hitNode.id);
                  else next.set(hitNode.id, hitNode.id);
                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 2 ? 'latch' : 'normal');
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
      const cursor = activeCursorsRef.current.get(e.pointerId)!;
      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (cursor.originNodeId && settings.isPitchBendEnabled && settings.layoutApproach !== 'tonality_diamond') {
          const originNode = nodeMapRef.current.get(cursor.originNodeId);
          if (originNode && scrollContainerRef.current) {
              const rect = scrollContainerRef.current.getBoundingClientRect();
              const centerOffset = dynamicSizeRef.current / 2;
              const spacing = settings.buttonSpacingScale * globalScale;
              const originY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
              const deltaY = e.clientY - originY;
              const bentRatio = originNode.ratio * getPitchRatioFromScreenDelta(deltaY, spacing);
              audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, bentRatio, settings.baseFrequency);
          }
      }

      if (cursor.hoverNodeId !== hitId) {
          if (latchMode === 0 && cursor.hoverNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
          if (hitNode && !audioLatchedNodes.has(hitNode.id) && settings.layoutApproach !== 'tonality_diamond') {
               audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, 'strum');
          }
          setActiveCursors(prev => {
              const next = new Map(prev);
              const c = next.get(e.pointerId);
              if (c) {
                  const updated: ActiveCursor = Object.assign({}, c, { hoverNodeId: hitId, hasMoved: true });
                  next.set(e.pointerId, updated);
              }
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (cursor) {
          if (latchMode !== 1 && cursor.originNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
      }
  };

  const render = (time: number) => {
      const activeCanvas = dynamicCanvasRef.current;
      if (!activeCanvas) { animationFrameRef.current = requestAnimationFrame(render); return; }
      const ctx = activeCanvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSizeRef.current;
      if (activeCanvas.width !== size * dpr) { activeCanvas.width = size * dpr; activeCanvas.height = size * dpr; ctx.scale(dpr, dpr); }

      const viewX = scrollContainerRef.current?.scrollLeft || 0;
      const viewY = scrollContainerRef.current?.scrollTop || 0;
      const viewW = scrollContainerRef.current?.clientWidth || size;
      const viewH = scrollContainerRef.current?.clientHeight || size;
      ctx.clearRect(viewX, viewY, viewW, viewH);

      const centerOffset = size / 2;
      const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2;

      visualLatchedRef.current.forEach(id => {
          const node = nodeMapRef.current.get(id);
          if (!node) return;
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius * settingsRef.current.latchedZoomScale;

          ctx.beginPath();
          ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 3 * globalScaleRef.current;
          ctx.stroke();
      });

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      switch(mode) {
          case 'rainbow':
              const period = getRainbowPeriod(settings.buttonSpacingScale * globalScale);
              const stops = [];
              for(let i=0; i<=6; i++) {
                  const pct = (i/6)*100;
                  const hue = (settings.rainbowOffset + i*60);
                  stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
              }
              return { ...baseStyle, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${period}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}>
        <div className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" />
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useRef, useState, useEffect } from 'react';
import { AppSettings, ButtonShape, ChordDefinition, BackgroundMode, LimitColorMap, KeyMappings, TuningSystem, LayoutApproach } from '../types';
import { DEFAULT_COLORS } from '../constants';
import { midiService, MidiDevice } from '../services/MidiService';
import { useStore } from '../services/Store'; 

interface Props {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
}

const PRESET_PALETTES: Record<string, LimitColorMap> = {
    'charcoal': { 1: '#FFFFFF', 3: '#D4D4D8', 5: '#A1A1AA', 7: '#71717A', 11: '#52525B', 13: '#3F3F46' },
    'midnight_blue': { 1: '#FFFFFF', 3: '#67E8F9', 5: '#3B82F6', 7: '#60A5FA', 11: '#818CF8', 13: '#A5B4FC' },
    'deep_maroon': { 1: '#FCD34D', 3: '#FB923C', 5: '#EF4444', 7: '#F87171', 11: '#FCA5A5', 13: '#FDA4AF' },
    'forest_green': { 1: '#BEF264', 3: '#4ADE80', 5: '#10B981', 7: '#34D399', 11: '#2DD4BF', 13: '#5EEAD4' },
    'slate_grey': { 1: '#F1F5F9', 3: '#94A3B8', 5: '#64748B', 7: '#F43F5E', 11: '#818CF8', 13: '#34D399' }
};

const NumberInput = ({ value, min, max, onChange, suffix = "", className = "", disabled = false }: { value: number; min: number; max: number; onChange: (val: number) => void; suffix?: string; className?: string; disabled?: boolean; }) => {
    const safeValue = (typeof value === 'number' && !isNaN(value)) ? value : min;
    const [text, setText] = useState(safeValue.toString());
    const [prevValue, setPrevValue] = useState(safeValue);
    const [error, setError] = useState<string | null>(null);
    if (value !== prevValue && value !== undefined && !isNaN(value)) {
        const currentNum = parseFloat(text);
        if (Math.abs(currentNum - value) > 0.0001) { setText(value.toString()); setError(null); }
        setPrevValue(value);
    }
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        if (val !== '' && !/^[\d.]+$/.test(val)) return;
        setText(val);
        if (val === '') return; 
        const num = parseFloat(val);
        if (isNaN(num)) return;
        if (num < min || num > max) { setError(`Range: ${min}-${max}`); } else { setError(null); onChange(num); }
    };
    const handleBlur = () => {
        const num = parseFloat(text);
        if (text === '' || isNaN(num) || error) { setText(prevValue.toString()); setError(null); }
    };
    return (
        <div className={`flex flex-col flex-grow ${disabled ? 'opacity-40 grayscale pointer-events-none' : ''}`}>
            <div className="relative">
                <input type="text" inputMode="decimal" value={text} onChange={handleChange} onBlur={handleBlur} disabled={disabled} className={`w-full bg-slate-700 rounded p-2 text-sm text-white border border-slate-600 focus:outline-none focus:border-blue-500 transition-colors ${className} ${error ? 'border-red-500 focus:border-red-500' : ''}`} />
                {suffix && <span className="absolute right-3 top-2 text-sm text-slate-400 pointer-events-none">{suffix}</span>}
            </div>
            {error && <span className="text-[10px] text-red-400 mt-1 font-bold animate-pulse">{error}</span>}
        </div>
    );
};

const SettingsModal: React.FC<Props> = ({ isOpen, onClose, settings, updateSettings }) => {
  const [activeTab, setActiveTab] = useState<'tonality' | 'behavior' | 'visuals' | 'midi' | 'data'>('tonality');
  const [midiDevices, setMidiDevices] = useState<MidiDevice[]>([]);
  const { exportXML, importXML } = useStore();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const bgImageInputRef = useRef<HTMLInputElement>(null);
  const [listeningFor, setListeningFor] = useState<keyof KeyMappings | null>(null);

  useEffect(() => {
    if (isOpen && activeTab === 'midi') {
        midiService.init().then(success => { if (success) { midiService.getOutputs().then(devices => { setMidiDevices(devices); }); } });
    }
  }, [isOpen, activeTab]);

  useEffect(() => {
      const handleBinderKeyDown = (e: KeyboardEvent) => {
          if (!listeningFor) return;
          e.preventDefault(); e.stopPropagation();
          let key = e.key.toLowerCase(); if (key === ' ') key = 'Space';
          updateSettings({ ...settings, keyMappings: { ...settings.keyMappings, [listeningFor]: key } });
          setListeningFor(null);
      };
      if (listeningFor) window.addEventListener('keydown', handleBinderKeyDown);
      return () => window.removeEventListener('keydown', handleBinderKeyDown);
  }, [listeningFor, settings, updateSettings]);

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => updateSettings({ ...settings, [key]: value });
  const handleLimitDepthChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => updateSettings({ ...settings, limitDepths: { ...settings.limitDepths, [limit]: val } });
  const handleLimitComplexityChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => updateSettings({ ...settings, limitComplexities: { ...settings.limitComplexities, [limit]: val } });
  const handleColorChange = (limit: number, color: string) => updateSettings({ ...settings, colors: { ...settings.colors, [limit]: color } });

  const handleImportClick = () => {
      const confirmed = window.confirm(
        "WARNING: Importing will overwrite ALL system settings, keyboard mappings, user bank patches, and currently selected synth sounds. " +
        "This action cannot be undone. \n\nDo you wish to proceed?"
      );
      if (confirmed) {
          fileInputRef.current?.click();
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) importXML(file).then(success => { if (success) onClose(); });
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const renderKeyBinding = (label: string, actionKey: keyof KeyMappings) => {
      const isListening = listeningFor === actionKey;
      const currentKey = settings.keyMappings[actionKey].toUpperCase();
      return (
          <div className="flex justify-between items-center bg-slate-800 p-2 rounded border border-slate-700 hover:border-slate-600 transition-colors">
              <span className="text-sm font-bold text-slate-300">{label}</span>
              <button onClick={() => setListeningFor(actionKey)} className={`px-3 py-1 text-xs font-mono font-bold rounded min-w-[80px] border transition-all ${isListening ? 'bg-red-900 border-red-500 text-white animate-pulse' : 'bg-slate-700 border-slate-600 text-blue-300 hover:bg-slate-600'}`}>
                  {isListening ? 'Press Key...' : currentKey}
              </button>
          </div>
      );
  };

  const handleBackgroundImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (readerEvent) => {
        const base64 = readerEvent.target?.result as string;
        handleChange('backgroundImageData', base64);
        handleChange('backgroundMode', 'image');
      };
      reader.readAsDataURL(file);
    }
  };

  const renderBaseFrequency = () => (
      <div className="bg-slate-900/60 p-4 rounded-lg border border-blue-500/20 mb-6">
          <div className="flex justify-between items-center mb-2">
            <h3 className="font-bold text-blue-400 text-xs uppercase tracking-widest">Global Tuning Center</h3>
            <span className="text-[9px] text-slate-500 font-mono">1/1 REFERENCE</span>
          </div>
          <NumberInput value={settings.baseFrequency} min={20} max={15000} suffix="Hz" onChange={(val) => handleChange('baseFrequency', val)} />
          <p className="text-[10px] text-slate-500 mt-2 italic">Sets the fundamental frequency for the origin node across all tuning modes.</p>
      </div>
  );

  const renderLayoutSelector = (system: TuningSystem) => {
    let options: { value: LayoutApproach; label: string }[] = [];

    switch (system) {
      case 'ji':
        options = [
          { value: 'lattice', label: 'Tonality Lattice' },
          { value: 'tonality_diamond', label: 'Tonality Diamond' },
        ];
        break;
