                      <input type="checkbox" checked={settings.midiEnabled} onChange={(e) => handleChange('midiEnabled', e.target.checked)} className="w-6 h-6 rounded border-slate-600 text-green-500" />
                    </label>

                    <div className={`space-y-4 transition-opacity ${settings.midiEnabled ? 'opacity-100' : 'opacity-30 pointer-events-none'}`}>
                      <div>
                        <label className="block text-xs font-bold text-slate-400 mb-2 uppercase">Output Device</label>
                        <select value={settings.midiOutputId || ''} onChange={(e) => { const id = e.target.value || null; handleChange('midiOutputId', id); midiService.setOutput(id); }} className="w-full bg-slate-700 rounded p-2 text-sm text-white border border-slate-600">
                          <option value="">No MIDI Output Selected</option>
                          {midiDevices.map(d => (<option key={d.id} value={d.id}>{d.name}</option>))}
                        </select>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'data' && (
                <div className="space-y-8 animate-in fade-in duration-300">
                    <div className="space-y-6">
                        <h3 className="font-semibold text-orange-400 border-b border-slate-700 pb-1">Backup & Restore</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="bg-slate-900/50 p-6 rounded-lg border border-slate-700 flex flex-col items-center text-center">
                                <h4 className="font-bold text-white mb-2">Export Full Data</h4>
                                <button onClick={exportXML} className="w-full py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded transition">Export to XML</button>
                            </div>
                            <div className="bg-slate-900/50 p-6 rounded-lg border border-slate-700 flex flex-col items-center text-center">
                                <h4 className="font-bold text-white mb-2">Import Full Data</h4>
                                <input type="file" ref={fileInputRef} className="hidden" accept=".xml" onChange={handleFileChange} />
                                <button onClick={handleImportClick} className="w-full py-2 bg-green-600 hover:bg-green-500 text-white font-bold rounded transition">Import from XML</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos, ArpeggioStep, ArpConfig, ArpeggioDefinition, ButtonShape } from './types';
import { PIXELS_PER_MM, SCROLLBAR_WIDTH } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';

const REFERENCE_SHORT_EDGE = 1080; 

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Arpeggio State
  const [recordingArpId, setRecordingArpId] = useState<string | null>(null);
  const [currentArpStep, setCurrentArpStep] = useState(0);
  const [recordingFlash, setRecordingFlash] = useState<number>(0); 

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  // Default shape interlock: use DIAMOND for tonality_diamond layout
  useEffect(() => {
    if (settings.layoutApproach === 'tonality_diamond' && settings.buttonShape !== ButtonShape.DIAMOND) {
        updateSettings({ buttonShape: ButtonShape.DIAMOND });
    }
  }, [settings.layoutApproach]);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, []);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginLeft = marginPx + safeArea.left;
      const marginTop = marginPx + safeArea.top;
      const marginRight = marginPx + safeArea.right + SCROLLBAR_WIDTH;
      const marginBottom = marginPx + safeArea.bottom + SCROLLBAR_WIDTH;

      const internalBlockGap = 24 * scale; 
      const baseGap = Math.max(marginPx, 32 * scale); 

      // Dimensions
      const volumeBarWidth = 600 * scale; 
      const arpBarWidth = 675 * scale; 
      const settingsGroupWidth = 170; 
      const settingsGroupHeight = 40; 
      const largeBtn = 80 * scale; 
      const perfBtn = 92 * scale; 

      const colWidth = 136 * scale; 
      const verticalStackGap = 12 * PIXELS_PER_MM * scale; 

      const newPos = { ...settings.uiPositions };

      const requiredWidth = volumeBarWidth + arpBarWidth + settingsGroupWidth + (baseGap * 4);
      const shouldHideExtras = w < requiredWidth;

      const extraLimitMargin = 12 * scale;
      const limitBarX = w - marginRight - colWidth - extraLimitMargin;
      const layersY = marginTop + settingsGroupHeight + verticalStackGap;

      if (shouldHideExtras) {
          newPos.arpeggioBar = { x: -9999, y: -9999 };
          newPos.layers = { x: -9999, y: -9999 };
          newPos.volume = { x: (w / 2) - (volumeBarWidth / 2), y: marginTop };
      } else {
          newPos.arpeggioBar = { x: marginLeft, y: marginTop };
          const volX = w - marginRight - settingsGroupWidth - baseGap - volumeBarWidth;
          newPos.volume = { x: volX, y: marginTop };
          newPos.layers = { x: limitBarX, y: layersY };
      }

      newPos.space = { x: -9999, y: -9999 };

      const bottomY = h - marginBottom - largeBtn; 
      let currentX = marginLeft;
      newPos.center = { x: currentX, y: bottomY };
      currentX += (largeBtn + internalBlockGap); 

      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (largeBtn + internalBlockGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (largeBtn + internalBlockGap);
      }
      currentX += baseGap; 
      newPos.chords = { x: currentX, y: bottomY };

      const perfY = h - marginBottom - perfBtn;
      let rightX = w - marginRight - perfBtn; 
      newPos.panic = { x: rightX, y: perfY };
      rightX -= (perfBtn + internalBlockGap); 
      newPos.off = { x: rightX, y: perfY };
      rightX -= (perfBtn + internalBlockGap); 
      newPos.latch = { x: rightX, y: perfY };
      rightX -= (perfBtn + internalBlockGap); 
      newPos.bend = { x: rightX, y: perfY };

      return newPos;
  };

  useEffect(() => {
    const handleResize = () => {
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;
        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);
        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);
        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  useEffect(() => { audioEngine.setMasterVolume(masterVolume); }, [masterVolume]);
  useEffect(() => { audioEngine.setGlobalSpatialScale(spatialScale); }, [spatialScale]);
  useEffect(() => { audioEngine.setGlobalBrightness(brightness); }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    arpeggiatorService.stop();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
    setRecordingArpId(null);
    updateSettings(prev => ({ ...prev, arpeggios: prev.arpeggios.map(a => ({ ...a, isPlaying: false })) }));
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
    setRecordingArpId(null);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => {
      if (latchMode === 1) return;
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;
          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);
          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: latchedNodes.map(n => ({ id: n.id, n: n.n, d: n.d })),
                  visible: true,
                  position: { x: 0, y: 0 } 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  const handleArpToggle = (id: string) => {
      const arp = settings.arpeggios.find(a => a.id === id);
      if (!arp) return;
      if (recordingArpId === id) { setRecordingArpId(null); return; }
      if (recordingArpId) { setRecordingArpId(id); return; }
      if (arp.steps.length === 0) {
          setRecordingArpId(id);
          updateSettings(prev => ({ ...prev, arpeggios: prev.arpeggios.map(a => a.id === id ? { ...a, isPlaying: false } : a) }));
          return;
      }
      const newIsPlaying = !arp.isPlaying;
      updateSettings(prev => ({ ...prev, arpeggios: prev.arpeggios.map(a => ({ ...a, isPlaying: a.id === id ? newIsPlaying : false })) }));
      if (newIsPlaying) arpeggiatorService.start(arp.steps, arp.config, settings.arpBpm, (step) => setCurrentArpStep(step));
      else arpeggiatorService.stop();
  };

  const handleArpRecordNote = (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => {
      if (!recordingArpId) return;
      setRecordingFlash(Date.now()); 
      const arpIndex = settings.arpeggios.findIndex(a => a.id === recordingArpId);
      if (arpIndex === -1) return;
      const currentSteps = settings.arpeggios[arpIndex].steps;
      if (currentSteps.length >= 32) { setRecordingArpId(null); return; }
      updateSettings(prev => {
          const next = [...prev.arpeggios];
          next[arpIndex] = { ...next[arpIndex], steps: [...currentSteps, { nodeId, ratio, n, d, limit, muted: false }] };
          return { ...prev, arpeggios: next };
      });
  };

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: `calc(${settings.uiEdgeMargin * PIXELS_PER_MM}px + env(safe-area-inset-top))`, left: `calc(${settings.uiEdgeMargin * PIXELS_PER_MM}px + env(safe-area-inset-left))` }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: `calc(${settings.uiEdgeMargin * PIXELS_PER_MM}px + env(safe-area-inset-top))`, right: `calc(${settings.uiEdgeMargin * PIXELS_PER_MM}px + env(safe-area-inset-right) + ${SCROLLBAR_WIDTH}px)` }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond ref={diamondRef} settings={settings} updateSettings={updateSettings} audioEngine={audioEngine} onLimitInteraction={handleLimitInteraction} activeChordIds={activeChordIds} uiUnlocked={settings.uiUnlocked} latchMode={latchMode} globalScale={effectiveScale} onNodeTrigger={handleArpRecordNote} />

      <FloatingControls volume={masterVolume} setVolume={setMasterVolume} spatialScale={spatialScale} setSpatialScale={setSpatialScale} brightness={brightness} setBrightness={setBrightness} onPanic={handlePanic} onOff={handleOff} onLatch={handleLatchToggle} latchMode={latchMode} onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled} onCenter={handleCenter} onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth} onAddChord={handleAddChord} toggleChord={toggleChord} activeChordIds={activeChordIds} savedChords={settings.savedChords} chordShortcutSizeScale={settings.chordShortcutSizeScale} showIncreaseDepthButton={settings.showIncreaseDepthButton} uiUnlocked={settings.uiUnlocked} uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate} draggingId={draggingId} setDraggingId={setDraggingId} uiScale={effectiveScale} layoutApproach={settings.layoutApproach} arpeggios={settings.arpeggios} arpBpm={settings.arpBpm} onArpToggle={handleArpToggle} onArpBpmChange={(b) => updateSettings({ arpBpm: b })} onArpRowConfigChange={(id, c) => updateSettings({ arpeggios: settings.arpeggios.map(a => a.id === id ? { ...a, config: { ...a.config, ...c } } : a) })} onArpPatternUpdate={(id, s) => updateSettings({ arpeggios: settings.arpeggios.map(a => a.id === id ? { ...a, steps: s } : a) })} recordingArpId={recordingArpId} currentArpStep={currentArpStep} recordingFlash={recordingFlash} />

      <LimitLayerControls settings={settings} updateSettings={updateSettings} draggingId={draggingId} setDraggingId={setDraggingId} uiScale={effectiveScale} />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; 
  onNodeTrigger?: (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => void;
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const visualLatchedNodes = useMemo(() => {
      const visual = new Map(audioLatchedNodes);
      activeCursors.forEach(cursor => {
          if (cursor.hoverNodeId) {
              visual.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });
      return visual;
  }, [audioLatchedNodes, activeCursors]);

  const activeLines = useMemo(() => {
    const latched = visualLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    if (latched.size < 2) return [];

    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                active.push(line);
            }
        }
    } 
    return active;
  }, [data.lines, visualLatchedNodes, settings.voiceLeadingSteps, nodeMap]);

  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || visualLatchedNodes.size === 0) return [];
      const activeIds = new Set(visualLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();

      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);
          if (sActive || tActive) {
              resultLines.add(line);
          }
      });
      return Array.from(resultLines);
  }, [visualLatchedNodes, data.lines, settings.lineBrighteningEnabled]);

  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const visualLatchedRef = useRef(visualLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);
  const persistentLatchesRef = useRef(persistentLatches);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { visualLatchedRef.current = visualLatchedNodes; }, [visualLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);
  useEffect(() => { persistentLatchesRef.current = persistentLatches; }, [persistentLatches]);

  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'tonality_diamond') return;
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        if (settingsRef.current.layoutApproach === 'tonality_diamond') return;
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        audioLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  const generationDeps = useMemo(() => {
      return JSON.stringify({
          tuning: settings.tuningSystem,
          layout: settings.layoutApproach,
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio,
          layerOrder: settings.layerOrder
      });
  }, [settings.tuningSystem, settings.layoutApproach, settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio, settings.layerOrder]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const result = generateLattice(settings);
        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }
        const padding = 800; 
        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
        const clampedSize = Math.min(finalSize, 8000);
        if (Math.abs(clampedSize - dynamicSizeRef.current) > 50) setDynamicSize(clampedSize);
        setData({ nodes: result.nodes, lines: result.lines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  const visualDeps = useMemo(() => JSON.stringify({
      layout: settings.layoutApproach,
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.layoutApproach, settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.buttonShape, settings.nodeTextSizeScale, dynamicSize, globalScale]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;
      if (canvas.width !== size * dpr) { canvas.width = size * dpr; canvas.height = size * dpr; }
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isPartchDiamond = settings.layoutApproach === 'tonality_diamond';

      ctx.lineCap = 'round';
      data.lines.forEach(line => {
          ctx.beginPath();
          ctx.moveTo(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset);
          ctx.lineTo(line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
          ctx.lineWidth = 1 * globalScale;
          ctx.strokeStyle = settings.colors[line.limit] || '#666';
          ctx.globalAlpha = 0.25;
          ctx.stroke();
      });

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';

          ctx.globalAlpha = 1.0;
          if (isPartchDiamond) {
              // Harry Partch Split Diamond Render
              ctx.save();
              ctx.beginPath();
              ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
              ctx.clip();

              // Top half
              ctx.fillStyle = cTop;
              ctx.fillRect(x - r, y - r, r * 2, r);
              // Bottom half
              ctx.fillStyle = cBottom;
              ctx.fillRect(x - r, y, r * 2, r);

              ctx.restore();
              ctx.strokeStyle = 'rgba(255,255,255,0.4)';
              ctx.lineWidth = 1 * globalScale;
              ctx.stroke();
          } else {
              ctx.beginPath();
              if (settings.buttonShape === ButtonShape.DIAMOND) {
                  ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y);
              } else {
                  ctx.arc(x, y, r, 0, Math.PI * 2);
              }
              ctx.closePath();
              const grad = ctx.createLinearGradient(x, y-r, x, y+r);
              grad.addColorStop(0.45, cTop); grad.addColorStop(0.55, cBottom);
              ctx.fillStyle = grad;
              ctx.fill();
              ctx.strokeStyle = 'rgba(255,255,255,0.2)';
              ctx.stroke();
          }

          ctx.fillStyle = 'white';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = `bold ${Math.max(10, 12 * settings.nodeTextSizeScale * globalScale)}px sans-serif`;
          ctx.fillText(node.n.toString(), x, y - r * 0.4);
          ctx.fillText(node.d.toString(), x, y + r * 0.4);
      });
  }, [data, visualDeps]); 

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const grid = spatialGridRef.current;
      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      for(let dx=-1; dx<=1; dx++) {
          for(let dy=-1; dy<=1; dy++) {
              const nodesInCell = grid.get(`${col+dx},${row+dy}`);
              if (nodesInCell) {
                  for (const node of nodesInCell) {
                      const nx = node.x * spacing + centerOffset;
                      const ny = node.y * spacing + centerOffset;
                      const r = baseRadius;
                      if (Math.abs(x - nx) < r && Math.abs(y - ny) < r) return node;
                  }
              }
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, { pointerId: e.pointerId, currentX: e.clientX, currentY: e.clientY, originNodeId: nodeId, hoverNodeId: nodeId, hasMoved: false });
          return next;
      });

      if (hitNode) {
          lastTouchedLimitRef.current = hitNode.maxPrime;
          onLimitInteraction(hitNode.maxPrime);
          if (onNodeTrigger) onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);

          if (latchMode === 1) {
              setPersistentLatches(prev => {
                  const next = new Map(prev);
                  if (next.has(hitNode.id)) next.delete(hitNode.id);
                  else next.set(hitNode.id, hitNode.id);
                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}-${hitNode.id}`;
              audioEngine.startVoice(voiceId, hitNode.ratio, settings.baseFrequency, latchMode === 2 ? 'latch' : 'normal');
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
      if (uiUnlocked || !activeCursorsRef.current.has(e.pointerId)) return;
      const cursor = activeCursorsRef.current.get(e.pointerId)!;
      const hitNode = getHitNode(e.clientX, e.clientY);
      const hitId = hitNode ? hitNode.id : null;

      if (cursor.originNodeId && settings.isPitchBendEnabled && settings.layoutApproach !== 'tonality_diamond') {
          const originNode = nodeMapRef.current.get(cursor.originNodeId);
          if (originNode && scrollContainerRef.current) {
              const rect = scrollContainerRef.current.getBoundingClientRect();
              const centerOffset = dynamicSizeRef.current / 2;
              const spacing = settings.buttonSpacingScale * globalScale;
              const originY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
              const deltaY = e.clientY - originY;
              const bentRatio = originNode.ratio * getPitchRatioFromScreenDelta(deltaY, spacing);
              audioEngine.glideVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`, bentRatio, settings.baseFrequency);
          }
      }

      if (cursor.hoverNodeId !== hitId) {
          if (latchMode === 0 && cursor.hoverNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.hoverNodeId}`);
          if (hitNode && !audioLatchedNodes.has(hitNode.id) && settings.layoutApproach !== 'tonality_diamond') {
               audioEngine.startVoice(`cursor-${e.pointerId}-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, 'strum');
          }
          setActiveCursors(prev => {
              const next = new Map(prev);
              const c = next.get(e.pointerId);
              if (c) {
                  // Use object spread instead of Object.assign to fix TypeScript type inference error.
                  const updated: ActiveCursor = { ...c, hoverNodeId: hitId, hasMoved: true };
                  next.set(e.pointerId, updated);
              }
              return next;
          });
      }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (cursor) {
          if (latchMode !== 1 && cursor.originNodeId) audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
          setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
      }
  };

  const render = (time: number) => {
      const activeCanvas = dynamicCanvasRef.current;
      if (!activeCanvas) { animationFrameRef.current = requestAnimationFrame(render); return; }
      const ctx = activeCanvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSizeRef.current;
      if (activeCanvas.width !== size * dpr) { activeCanvas.width = size * dpr; activeCanvas.height = size * dpr; ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.scale(dpr, dpr); }

      const viewX = scrollContainerRef.current?.scrollLeft || 0;
      const viewY = scrollContainerRef.current?.scrollTop || 0;
      const viewW = scrollContainerRef.current?.clientWidth || size;
      const viewH = scrollContainerRef.current?.clientHeight || size;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(dpr, dpr);
      ctx.clearRect(viewX, viewY, viewW, viewH);

      const centerOffset = size / 2;
      const spacing = settingsRef.current.buttonSpacingScale * globalScaleRef.current;
      const baseRadius = (60 * settingsRef.current.buttonSizeScale * globalScaleRef.current) / 2;

      visualLatchedRef.current.forEach(id => {
          const node = nodeMapRef.current.get(id);
          if (!node) return;
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const r = baseRadius * settingsRef.current.latchedZoomScale;

          ctx.beginPath();
          ctx.moveTo(x, y - r); ctx.lineTo(x + r, y); ctx.lineTo(x, y + r); ctx.lineTo(x - r, y); ctx.closePath();
          ctx.strokeStyle = 'white';
          ctx.lineWidth = 3 * globalScaleRef.current;
          ctx.stroke();
      });

      animationFrameRef.current = requestAnimationFrame(render);
  };

  useEffect(() => {
    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []);

  const getBackgroundStyle = () => {
      const mode = settings.backgroundMode;
      const offset = settings.backgroundYOffset || 0;

      const baseStyle: React.CSSProperties = {
          minWidth: '100%', minHeight: '100%', width: dynamicSize, height: dynamicSize,
          pointerEvents: uiUnlocked ? 'none' : 'auto',
          backgroundPosition: `center calc(50% + ${offset}px)`,
          backgroundRepeat: 'no-repeat', backgroundSize: 'cover'
      };

      switch(mode) {
          case 'rainbow':
              const period = getRainbowPeriod(settings.buttonSpacingScale * globalScale);
              const stops = [];
              for(let i=0; i<=6; i++) {
                  const pct = (i/6)*100;
                  const hue = (settings.rainbowOffset + i*60);
                  stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
              }
              return { ...baseStyle, backgroundImage: `linear-gradient(to bottom, ${stops.join(', ')})`, backgroundSize: `100% ${period}px`, backgroundRepeat: 'repeat', backgroundPosition: `0px calc(50% + ${offset}px)` };
          case 'charcoal': return { ...baseStyle, backgroundColor: '#18181b' }; 
          case 'midnight_blue': return { ...baseStyle, backgroundColor: '#0a0a23' }; 
          case 'deep_maroon': return { ...baseStyle, backgroundColor: '#3e0000' };
          case 'forest_green': return { ...baseStyle, backgroundColor: '#002200' };
          case 'slate_grey': return { ...baseStyle, backgroundColor: '#334155' };
          case 'image':
              if (settings.backgroundImageData) {
                  return { ...baseStyle, backgroundImage: `url(${settings.backgroundImageData})`, backgroundRepeat: settings.backgroundTiling ? 'repeat' : 'no-repeat', backgroundSize: settings.backgroundTiling ? 'auto' : 'contain', backgroundPosition: `center calc(50% + ${offset}px)` };
              }
              return { ...baseStyle, backgroundColor: 'black' };
          default: return { ...baseStyle, backgroundColor: 'black' };
      }
  };

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" style={{ touchAction: 'none' }} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}>
        <div className="relative" style={getBackgroundStyle()}>
           <canvas ref={bgLineCanvasRef} className="absolute top-0 left-0 z-[5] pointer-events-none" />
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10] pointer-events-none" />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20] pointer-events-none" />
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export type TuningSystem = 'ji' | 'et';

export type LayoutApproach = 
  | 'lattice' | 'tonality_diamond' // Just Intonation
  | 'et_wheel' | 'et_grid' | 'et_row'; // ET specific

export type BackgroundMode = 'rainbow' | 'charcoal' | 'midnight_blue' | 'deep_maroon' | 'forest_green' | 'slate_grey' | 'image' | 'none';

export interface LimitColorMap {
  [key: number]: string;
}

export interface LimitVisualSetting {
    size: number;   // 0.1 to 2.0 (Multiplier of base size)
    opacity: number; // 0.0 to 1.0
}

export interface LimitVisualsMap {
    [key: number]: LimitVisualSetting;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface ArpeggioStep {
    nodeId: string;
    ratio: number;
    n?: number;
    d?: number;
    muted?: boolean;
    limit?: number; // For quality indication (maxPrime)
}

export type ArpDirection = 'order' | 'up' | 'down' | 'updown' | 'random';
export type ArpDivision = '1/1' | '1/2' | '1/4' | '1/8' | '1/16' | '1/32' | '1/4T' | '1/8T' | '1/16T';

export interface ArpConfig {
    direction: ArpDirection;
    division: ArpDivision;
    octaves: number; // 1 to 4
    gate: number; // 0.1 to 1.0
    swing: number; // 0 to 100
    length: number; // 1 to 32 (Pattern Length)
    probability: number; // 0.0 to 1.0 (Chance to play)
    humanize: number; // 0 to 100 (ms of jitter)
}

export interface ArpeggioDefinition {
    id: string; // "A" - "G"
    steps: ArpeggioStep[];
    isPlaying: boolean;
    config: ArpConfig;
}

export interface XYPos {
  x: number;
  y: number;
}

export interface KeyMappings {
    volumeUp: string;
    volumeDown: string;
    spatialScaleUp: string;
    spatialScaleDown: string;
    latch: string;
    panic: string;
    center: string;
    settings: string;
    synth: string;
    off: string;
    bend: string;
    addChord: string;
    increaseDepth: string;
    decreaseDepth: string;
}

export interface AppSettings {
  // Global Tuning
  tuningSystem: TuningSystem;
  layoutApproach: LayoutApproach;

  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Origins for lattice generation (Multiple tonality centers)
  generationOrigins: GenerationOrigin[];

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Arpeggios
  arpeggios: ArpeggioDefinition[];
  arpBpm: number;

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1
  audioLatencyHint: 'interactive' | 'balanced' | 'playback'; // Buffer size control

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Brightening
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;

  // Per-Limit Visuals (Size/Opacity)
  limitVisuals: LimitVisualsMap;

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Background
  backgroundMode: BackgroundMode;
  backgroundImageData: string | null; // Base64 string for custom image
  backgroundTiling: boolean; // True = Repeat, False = No Repeat (Centered)
  backgroundYOffset: number; // Vertical offset in pixels

  // Legacy Rainbow params (still used if mode is 'rainbow')
  isRainbowModeEnabled: boolean; 
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)

  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // Behavior
  enableKeyboardShortcuts: boolean;
  keyMappings: KeyMappings;
  strumDuration: number; // seconds, 0.1 to 2.0

  // UI Relocation & Scaling
  uiUnlocked: boolean;
  uiScale: number; // 0.5 (Tiny) to 1.5 (Huge)
  uiEdgeMargin: number; // in Millimeters (1-10)
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
    arpeggioBar: XYPos;
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;
  category?: string; // New field for categorization

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Stereo & Pan
  spread?: number; // 0 to 1 (Voice Stereo Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)

  // Reverb Unit
  reverbType?: ReverbType; // Convolution Preset (Logic base)
  reverbMix: number; // 0 to 1
  reverbSize: number; // Duration in seconds (0.1 to 10.0)
  reverbDamping: number; // 0 (Bright) to 1 (Dark)
  reverbDiffusion?: number; // 0 (Grainy) to 1 (Smooth)

  // Delay Unit
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds

  // Arp Settings
  arpConfig?: ArpConfig;
